  if (/timeout|navigation|net::|ECONNRESET|ENOTFOUND/i.test(String(cause?.message || ''))) {
    return transientNazemError(`تعذر ${action} بسبب بطء أو انقطاع الاتصال بناظم.`, 'NAZEM_OPERATION_TIMEOUT', cause);
