          `UPDATE nazem_sync_jobs SET payload_json = JSON_SET(
              COALESCE(payload_json, JSON_OBJECT()), '$.requestedFrom', 'student-plan-import'
            ), next_attempt_at = IF(status IN ('pending','retrying'), NOW(3), next_attempt_at)
           WHERE id = ?`,
