  router.post('/conflicts/:conflictId/resolve', requireSettings, async (req, res, next) => {
    const connection = await db().getConnection();
    try {
      const resolution = String(req.body.resolution || '');
      if (!['use_ruwasi', 'use_nazem', 'ignore_remote'].includes(resolution)) {
        throw invalid('حل التعارض غير مدعوم.');
      }
      await connection.beginTransaction();
      const [[conflict]] = await connection.query(
        `SELECT conflict.id, conflict.entity_type AS entityType, conflict.entity_id AS entityId,
          conflict.teacher_id AS teacherId,
          conflict.local_snapshot AS localSnapshot, conflict.remote_snapshot AS remoteSnapshot,
          COALESCE(plan.student_id, recitationTask.student_id, dailyLink.ruwasi_student_id) AS studentId,
          COALESCE(plan.id, recitationTask.plan_id, dailyLink.ruwasi_plan_id) AS planId,
          planLink.nazem_student_id AS nazemStudentId, planLink.nazem_plan_id AS nazemPlanId
         FROM nazem_sync_conflicts conflict
         LEFT JOIN student_quran_plans plan ON conflict.entity_type = 'plan' AND plan.id = conflict.entity_id
         LEFT JOIN nazem_plan_links planLink
           ON conflict.entity_type = 'plan' AND planLink.ruwasi_plan_id = conflict.entity_id
          AND planLink.teacher_id = conflict.teacher_id
         LEFT JOIN nazem_recitation_links recitationLink
           ON conflict.entity_type = 'recitation' AND recitationLink.ruwasi_recitation_id = conflict.entity_id
         LEFT JOIN student_quran_tasks recitationTask ON recitationTask.id = recitationLink.ruwasi_task_id
         LEFT JOIN nazem_daily_follow_up_links dailyLink
           ON conflict.entity_type = 'recitation_day' AND dailyLink.id = conflict.entity_id
         WHERE conflict.id = ? AND conflict.status = 'open' LIMIT 1 FOR UPDATE`,
        [req.params.conflictId],
      );
      if (!conflict) {
        const error = new Error('التعارض غير موجود أو سبق حله.');
        error.statusCode = 404;
        throw error;
      }
      let importedPlan = null;
      if (resolution === 'use_ruwasi' && conflict.entityType === 'plan') {
        await enqueueNazemSyncJob(connection, {
          operationType: 'plan.upsert',
          entityType: 'plan',
          entityId: conflict.entityId,
          teacherId: conflict.teacherId,
          studentId: conflict.studentId,
          payload: { planId: conflict.entityId, studentId: conflict.studentId, conflictId: conflict.id },
          idempotencyKey: `nazem:conflict:${conflict.id}:use-ruwasi`,
        });
        await connection.query(
          `UPDATE nazem_plan_links SET sync_status = 'pending', last_error_code = NULL, last_error = NULL
           WHERE ruwasi_plan_id = ? AND teacher_id = ?`,
          [conflict.entityId, conflict.teacherId],
        );
      } else if (resolution === 'use_ruwasi' && conflict.entityType === 'recitation') {
        await enqueueNazemSyncJob(connection, {
          operationType: 'recitation.submit',
          entityType: 'recitation',
          entityId: conflict.entityId,
          teacherId: conflict.teacherId,
          studentId: conflict.studentId,
          payload: { attemptId: conflict.entityId, force: true, conflictId: conflict.id },
          idempotencyKey: `nazem:conflict:${conflict.id}:use-ruwasi`,
        });
        await connection.query(
          "UPDATE nazem_recitation_links SET sync_status = 'pending', last_error_code = NULL, last_error = NULL WHERE ruwasi_recitation_id = ? AND teacher_id = ?",
          [conflict.entityId, conflict.teacherId],
        );
      } else if (resolution === 'use_ruwasi' && conflict.entityType === 'recitation_day') {
        await enqueueNazemSyncJob(connection, {
          operationType: 'recitation.submit',
          entityType: 'recitation_day',
          entityId: conflict.entityId,
          teacherId: conflict.teacherId,
          studentId: conflict.studentId,
          payload: { dailyFollowUpId: conflict.entityId, force: true, conflictId: conflict.id },
          idempotencyKey: `nazem:conflict:${conflict.id}:use-ruwasi`,
        });
        await connection.query(
          `UPDATE nazem_daily_follow_up_links SET sync_status = 'pending',
            last_error_code = NULL, last_error = NULL WHERE id = ? AND teacher_id = ?`,
          [conflict.entityId, conflict.teacherId],
        );
        await connection.query(
          `UPDATE nazem_recitation_links SET sync_status = 'pending',
            last_error_code = NULL, last_error = NULL WHERE daily_follow_up_id = ? AND teacher_id = ?`,
          [conflict.entityId, conflict.teacherId],
        );
      } else if (resolution === 'use_nazem' && conflict.entityType === 'plan') {
        if (typeof importPlanCandidate !== 'function') throw invalid('استيراد خطط ناظم غير متاح.');
        const [[candidate]] = await connection.query(
          `SELECT id, progress_snapshot AS progressSnapshot
           FROM nazem_plan_candidates
           WHERE teacher_id = ? AND ruwasi_student_id = ? AND nazem_plan_id = ?
           ORDER BY last_seen_at DESC LIMIT 1 FOR UPDATE`,
          [conflict.teacherId, conflict.studentId, conflict.nazemPlanId],
        );
        if (!candidate) throw invalid('أعد التحقق من حساب ناظم قبل اعتماد خطته.');
        importedPlan = await importPlanCandidate(connection, {
          teacherId: conflict.teacherId,
          studentId: conflict.studentId,
          nazemStudentId: conflict.nazemStudentId,
          nazemPlanId: conflict.nazemPlanId,
          remoteSnapshot: parseSnapshot(conflict.remoteSnapshot),
          progressSnapshot: parseSnapshot(candidate.progressSnapshot),
        });
        await connection.query(
          `UPDATE nazem_plan_candidates SET discovery_status = 'imported',
            last_error_code = NULL, last_error = NULL, resolved_by_role = ?, resolved_by_id = ?,
            resolved_at = NOW(3) WHERE id = ?`,
          [req.auth?.role || 'manager', Number(req.auth?.id || 0) || null, candidate.id],
        );
      } else if (resolution === 'use_nazem' && conflict.entityType === 'recitation_day') {
        const remote = parseSnapshot(conflict.remoteSnapshot) || {};
        const local = parseSnapshot(conflict.localSnapshot) || {};
        const remoteCompleted = isNazemFollowUpCompleted(remote.status);
        const remoteErrors = Math.max(0, Number(remote.mistake || 0)) + Math.max(0, Number(remote.tune || 0));
        const remoteRepeatCount = remoteCompleted
          ? Math.min(30, Math.max(1, Math.trunc(Number(remote.repetition || 1))))
          : 0;
        const remoteListeningCount = remoteCompleted && Number(remote.hearing) === 1 ? 1 : 0;
        const remoteLinkCount = remoteCompleted ? normalizeNazemLinkCount(remote.link) : 0;
        const taskIds = Array.isArray(local.taskIds) ? local.taskIds.map(Number).filter(Boolean) : [];
        const attemptIds = Array.isArray(local.attemptIds) ? local.attemptIds.map(Number).filter(Boolean) : [];
        if (!taskIds.length || !attemptIds.length) throw invalid('تعذر تحديد مقاطع المنصة المرتبطة بنتيجة ناظم.');
        const placeholders = taskIds.map(() => '?').join(',');
        const [tasks] = await connection.query(
          `SELECT id, evaluation_score AS score, evaluation_passing_score AS passingScore,
            evaluation_max_score AS maxScore
           FROM student_quran_tasks WHERE id IN (${placeholders}) FOR UPDATE`,
          taskIds,
        );
        for (const task of tasks) {
          const passingScore = Math.max(1, Number(task.passingScore || 85));
          const currentScore = Number(task.score || 0);
          const score = remoteCompleted
            ? Math.max(passingScore, currentScore)
            : Math.max(0, Math.min(passingScore - 0.01, currentScore || passingScore - 1));
          const isFirst = Number(task.id) === Number(taskIds[0]);
          await connection.query(
            `UPDATE student_quran_tasks SET mistake_count = ?, evaluation_score = ?,
              teacher_completed = ?, teacher_rating_key = 'score', teacher_rating_label = ?,
              evaluated_by = ?, evaluated_at = NOW(3)
             WHERE id = ?`,
            [isFirst ? remoteErrors : 0, score, remoteCompleted ? 1 : 0,
              remoteCompleted ? 'متقن' : 'يحتاج إعادة', conflict.teacherId, task.id],
          );
        }
        const attemptPlaceholders = attemptIds.map(() => '?').join(',');
        await connection.query(
          `UPDATE student_quran_recitation_attempts attempt
           JOIN student_quran_tasks task ON task.id = attempt.task_id
           SET attempt.teacher_completed = ?, attempt.evaluation_score = task.evaluation_score,
             attempt.mistake_count = CASE WHEN attempt.id = ? THEN ? ELSE 0 END
           WHERE attempt.id IN (${attemptPlaceholders})`,
          [remoteCompleted ? 1 : 0, attemptIds[0], remoteErrors, ...attemptIds],
        );
        if (local.taskType === 'memorization' && conflict.planId && local.date) {
          await connection.query(
            `UPDATE student_quran_tasks SET student_status = ?,
              actual_to_page = CASE WHEN ? = 1 THEN to_page ELSE NULL END,
              actual_to_surah = CASE WHEN ? = 1 THEN to_surah ELSE NULL END,
              actual_to_ayah = CASE WHEN ? = 1 THEN to_ayah ELSE NULL END,
              actual_repeat_count = ?, actual_listening_count = ?,
              execution_state = CASE WHEN ? = 1 THEN 'complete' ELSE NULL END,
              execution_actor_role = 'teacher', execution_actor_id = ?, executed_at = NOW(3)
             WHERE plan_id = ? AND student_id = ? AND task_date = ? AND task_type = 'repeat'
               AND from_surah = ? AND from_ayah = ? AND to_surah = ? AND to_ayah = ?`,
            [
              remoteCompleted ? 'done' : 'not_done', remoteCompleted ? 1 : 0,
              remoteCompleted ? 1 : 0, remoteCompleted ? 1 : 0,
              remoteRepeatCount, remoteListeningCount, remoteCompleted ? 1 : 0,
              conflict.teacherId, conflict.planId, conflict.studentId, local.date,
              Number(local.fromSurahId), Number(local.fromAyah),
              Number(local.scheduledToSurahId), Number(local.scheduledToAyah),
            ],
          );
          await connection.query(
            `UPDATE student_quran_tasks SET actual_link_count = NULL
             WHERE plan_id = ? AND student_id = ? AND task_date = ? AND task_type = 'memorization'`,
            [conflict.planId, conflict.studentId, local.date],
          );
          await connection.query(
            'UPDATE student_quran_tasks SET actual_link_count = ? WHERE id = ?',
            [remoteLinkCount, taskIds[0]],
          );
        }
        if (remote.attendanceStatus != null && local.date) {
          await applyRemoteAttendanceToRuwasi(connection, conflict.studentId, {
            attendanceStatus: remote.attendanceStatus,
            date: local.date,
          }, { inTransaction: true });
        }
        await connection.query(
          `UPDATE nazem_daily_follow_up_links SET sync_status = 'synced', remote_snapshot = ?,
            last_synced_at = NOW(3), last_remote_checked_at = NOW(3),
            last_error_code = NULL, last_error = NULL WHERE id = ? AND teacher_id = ?`,
          [JSON.stringify(remote), conflict.entityId, conflict.teacherId],
        );
        await connection.query(
          `UPDATE nazem_recitation_links SET sync_status = 'synced', remote_snapshot = ?,
            last_synced_at = NOW(3), last_error_code = NULL, last_error = NULL
           WHERE daily_follow_up_id = ? AND teacher_id = ?`,
          [JSON.stringify(remote), conflict.entityId, conflict.teacherId],
        );
      } else if (resolution === 'use_nazem') {
        throw invalid('اعتماد نسخة ناظم متاح لتعارضات الخطط فقط.');
      } else if (conflict.entityType === 'plan') {
        await connection.query(
          `UPDATE nazem_plan_links SET sync_status = 'synced',
            last_synced_snapshot = ?, remote_snapshot = ?, last_synced_at = NOW(3),
            last_remote_checked_at = NOW(3),
            last_error_code = NULL, last_error = NULL
           WHERE ruwasi_plan_id = ? AND teacher_id = ?`,
          [
            JSON.stringify({
              local: typeof conflict.localSnapshot === 'string'
                ? JSON.parse(conflict.localSnapshot) : conflict.localSnapshot,
              remote: typeof conflict.remoteSnapshot === 'string'
                ? JSON.parse(conflict.remoteSnapshot) : conflict.remoteSnapshot,
            }),
            typeof conflict.remoteSnapshot === 'string'
              ? conflict.remoteSnapshot : JSON.stringify(conflict.remoteSnapshot || {}),
            conflict.entityId,
            conflict.teacherId,
          ],
        );
      } else if (conflict.entityType === 'recitation') {
        await connection.query(
          `UPDATE nazem_recitation_links SET sync_status = 'synced', remote_snapshot = ?,
            last_synced_at = NOW(3),
            last_error_code = NULL, last_error = NULL
           WHERE ruwasi_recitation_id = ? AND teacher_id = ?`,
          [
            typeof conflict.remoteSnapshot === 'string'
              ? conflict.remoteSnapshot : JSON.stringify(conflict.remoteSnapshot || {}),
            conflict.entityId,
            conflict.teacherId,
          ],
        );
      } else if (conflict.entityType === 'recitation_day') {
        await connection.query(
          `UPDATE nazem_daily_follow_up_links SET sync_status = 'conflict', remote_snapshot = ?,
            last_remote_checked_at = NOW(3), last_error_code = 'NAZEM_DIFFERENCE_ACCEPTED',
            last_error = 'اعتمد المسؤول استمرار الاختلاف بين المنصة وناظم.'
           WHERE id = ? AND teacher_id = ?`,
          [JSON.stringify(parseSnapshot(conflict.remoteSnapshot) || {}), conflict.entityId, conflict.teacherId],
        );
      }
      await connection.query(
        `UPDATE nazem_sync_conflicts SET status = 'resolved', resolution = ?,
          resolved_by_role = ?, resolved_by_id = ?, resolved_at = NOW(3) WHERE id = ?`,
        [resolution, req.auth?.role || 'manager', Number(req.auth?.id || 0) || null, conflict.id],
      );
      if (resolution === 'use_nazem') {
        await connection.query(
          `UPDATE nazem_sync_jobs SET status = 'dismissed', last_error_code = NULL,
            last_error = NULL, lease_owner = NULL, lease_expires_at = NULL,
            last_heartbeat_at = NULL
           WHERE entity_type = ? AND entity_id = ? AND teacher_id = ? AND status = 'conflict'`,
          [conflict.entityType, conflict.entityId, conflict.teacherId],
        );
      }
      await connection.commit();
      res.json({ ok: true, ...(importedPlan ? { planId: importedPlan.planId } : {}) });
    } catch (error) {
      await connection.rollback();
      next(error);
    } finally {
      connection.release();
    }
  });

  router.get('/plan-statuses', requirePlanStatusAccess, async (req, res, next) => {
    try {
      const studentId = Number(req.query.studentId || 0);
      const params = [];
      const filters = [];
      if (studentId) {
        filters.push('plan.student_id = ?');
        params.push(studentId);
      }
      if (req.auth?.role === 'supervisor') {
        filters.push(`EXISTS (
          SELECT 1 FROM supervisor_committees scope
          JOIN students scopedStudent ON scopedStudent.committee_id = scope.committee_id
          WHERE scope.supervisor_id = ? AND scopedStudent.id = plan.student_id
        )`);
        params.push(req.auth.id);
      }
      const [rows] = await db().query(
        `SELECT plan.id AS planId, link.sync_status AS status,
          link.last_error_code AS lastErrorCode, link.last_error AS lastError,
          DATE_FORMAT(link.last_synced_at, '%Y-%m-%d %H:%i') AS lastSyncedAt
         FROM student_quran_plans plan
         LEFT JOIN nazem_plan_links link ON link.ruwasi_plan_id = plan.id
         ${filters.length ? `WHERE ${filters.join(' AND ')}` : ''}
         ORDER BY plan.id DESC LIMIT 500`,
        params,
      );
      res.json(rows);
    } catch (error) {
      next(error);
    }
  });

  router.get('/daily-statuses', requirePlanStatusAccess, async (req, res, next) => {
    try {
      const date = /^\d{4}-\d{2}-\d{2}$/.test(String(req.query.date || ''))
        ? String(req.query.date)
        : null;
      const filters = [];
      const params = [];
      if (date) {
        filters.push('daily.follow_up_date = ?');
        params.push(date);
      }
      if (req.auth?.role === 'supervisor') {
        filters.push('daily.teacher_id = ?');
        params.push(Number(req.auth.id));
      }
      const [rows] = await db().query(
        `SELECT daily.id, daily.ruwasi_student_id AS studentId,
          DATE_FORMAT(daily.follow_up_date, '%Y-%m-%d') AS date,
          daily.task_type AS taskType, daily.sync_status AS status,
          daily.last_error_code AS lastErrorCode, daily.last_error AS lastError,
          DATE_FORMAT(daily.last_synced_at, '%Y-%m-%d %H:%i') AS lastSyncedAt,
          student.name AS studentName
         FROM nazem_daily_follow_up_links daily
         JOIN students student ON student.id = daily.ruwasi_student_id
         ${filters.length ? `WHERE ${filters.join(' AND ')}` : ''}
         ORDER BY daily.follow_up_date DESC, daily.updated_at DESC LIMIT 250`,
        params,
      );
      const attendanceFilters = ["job.operation_type = 'attendance.submit'"];
      const attendanceParams = [];
      if (date) {
        attendanceFilters.push("JSON_UNQUOTE(JSON_EXTRACT(job.payload_json, '$.date')) = ?");
        attendanceParams.push(date);
      }
      if (req.auth?.role === 'supervisor') {
        attendanceFilters.push('job.teacher_id = ?');
        attendanceParams.push(Number(req.auth.id));
      }
      const [attendanceRows] = await db().query(
        `SELECT job.id, job.student_id AS studentId,
          JSON_UNQUOTE(JSON_EXTRACT(job.payload_json, '$.date')) AS date,
          'attendance' AS taskType, job.status,
          job.last_error_code AS lastErrorCode, job.last_error AS lastError,
          DATE_FORMAT(job.last_succeeded_at, '%Y-%m-%d %H:%i') AS lastSyncedAt,
          student.name AS studentName
         FROM nazem_sync_jobs job
         LEFT JOIN students student ON student.id = job.student_id
         WHERE ${attendanceFilters.join(' AND ')}
           AND NOT EXISTS (
             SELECT 1 FROM nazem_sync_jobs newer
             WHERE newer.operation_type = 'attendance.submit'
               AND newer.teacher_id = job.teacher_id
               AND newer.student_id = job.student_id
               AND JSON_UNQUOTE(JSON_EXTRACT(newer.payload_json, '$.date')) =
                 JSON_UNQUOTE(JSON_EXTRACT(job.payload_json, '$.date'))
               AND newer.id > job.id
           )
         ORDER BY job.created_at DESC LIMIT 250`,
        attendanceParams,
      );
      res.json([...rows, ...attendanceRows]);
    } catch (error) {
      next(error);
    }
  });

  return router;
}

import { groupProgramSections } from '../../shared/program-sections.js';
import { countTrailingCharacter } from '../../shared/string-suffix.js';
import { saveProgramSections } from '../services/programSections.js';
import { saveManualProgramPoints } from '../services/manualProgramPoints.js';
import express from 'express';
import { deleteProgram } from '../services/deleteProgram.js';
import { db } from '../db.js';
import { requirePermission } from '../services/dashboardPermissions.js';

const FILE_PATTERN = /^data:[a-zA-Z0-9][a-zA-Z0-9.+/-]*;base64,[a-zA-Z0-9+/=]+$/;

const fail = (message, statusCode = 422) => Object.assign(new Error(message), { statusCode });
const clean = (value, max) => String(value || '').trim().slice(0, max);
const dataBytes = (value) => {
  const base64 = String(value || '').split(',')[1] || '';
  const padding = countTrailingCharacter(base64, '=');
  return Math.max(0, Math.floor((base64.length * 3) / 4) - padding);
};

export function normalizePayload(body = {}, child = false) {
  const sectionsEnabled = body.sectionsEnabled === true;
  if (child && sectionsEnabled) throw fail('لا يمكن إضافة أقسام داخل القسم.');
  if (sectionsEnabled && (!Array.isArray(body.sections) || !body.sections.length || body.sections.length > 30)) throw fail('أضف من قسم واحد إلى 30 قسمًا.');
  const title = clean(body.title, 180);
  const status = body.status === 'locked' ? 'locked' : 'open';
  const pointsReward = Math.trunc(Number(body.pointsReward || 0));
  const allowMultipleAttempts = body.allowMultipleAttempts === true;
  if (!title) throw fail('اسم المستوى مطلوب.');
  if (!sectionsEnabled && (!Number.isFinite(pointsReward) || pointsReward < 0 || pointsReward > 10000)) {
    throw fail('عدد الكيلومترات يجب أن يكون بين 0 و10000.');
  }

  const submittedContents = Array.isArray(body.contents) ? body.contents : [];
  const text = String(submittedContents.find((item) => item?.type === 'text')?.value || '').trim();
  if (text.length > 20000) throw fail('النص يتجاوز الحد المسموح.');
  const contents = text ? [{ type: 'text', value: text, fileName: '', mimeType: '' }] : [];
  const attachment = submittedContents.find((item) => item?.type === 'file');
  if (attachment?.value) {
    const value = String(attachment.value).trim();
    if (!FILE_PATTERN.test(value) || dataBytes(value) > 10 * 1024 * 1024) {
      throw fail('الملف غير صالح أو يتجاوز حجمه 10 ميجابايت.');
    }
    contents.push({
      type: 'file',
      value,
      fileName: clean(attachment.fileName, 255) || 'ملف مرفق',
      mimeType: clean(attachment.mimeType, 120) || 'application/octet-stream',
    });
  }

  const questions = (Array.isArray(body.questions) ? body.questions : []).slice(0, 100).map((item, index) => {
    const text = clean(item?.text, 500);
    const options = (Array.isArray(item?.options) ? item.options : []).slice(0, 6).map((option) => ({
      text: clean(option?.text, 300),
      isCorrect: option?.isCorrect === true,
    }));
    if (!text || options.length < 2 || options.some((option) => !option.text)) {
      throw fail(`السؤال رقم ${index + 1} يحتاج نصًا وخيارين على الأقل.`);
    }
    if (options.filter((option) => option.isCorrect).length !== 1) {
      throw fail(`حدد إجابة صحيحة واحدة للسؤال رقم ${index + 1}.`);
    }
    return { text, options };
  });
  return { title, status, pointsReward: sectionsEnabled ? 0 : pointsReward, allowMultipleAttempts: !child && !sectionsEnabled && allowMultipleAttempts, contents, questions: sectionsEnabled ? [] : questions,
    sections: sectionsEnabled ? body.sections.map(section => ({ ...normalizePayload(section, true), id: section.id })) : [] };
}

async function loadPrograms({ studentId = null, pathId = null, includeAnswers = false } = {}) {
  const params = [];
  let where = '1 = 1';
  if (pathId) { where += ' AND (p.id = ? OR p.parent_path_id = ?)'; params.push(pathId, pathId); }
  if (studentId) { where += " AND p.status = 'open' AND (p.parent_path_id IS NULL OR EXISTS (SELECT 1 FROM learning_paths parent WHERE parent.id = p.parent_path_id AND parent.status = 'open'))"; }
  const [paths] = await db().query(
    `SELECT p.id, p.title, p.status, p.points_reward AS pointsReward,
      p.allow_multiple_attempts AS allowMultipleAttempts, p.parent_path_id AS parentPathId, EXISTS (SELECT 1 FROM learning_paths child WHERE child.parent_path_id = p.id) AS sectionsEnabled,
      p.sort_order AS sortOrder${studentId ? ', sp.score, sp.total_questions AS totalQuestions, sp.earned_points AS earnedPoints, sp.completed_at AS completedAt' : ''}
     FROM learning_paths p
     ${studentId ? 'LEFT JOIN student_path_progress sp ON sp.path_id = p.id AND sp.student_id = ?' : ''}
     WHERE ${where} ORDER BY p.sort_order ASC, p.id DESC`,
    studentId ? [studentId, ...params] : params
  );
  if (!paths.length) return [];
  const ids = paths.map((path) => Number(path.id));
  const placeholders = ids.map(() => '?').join(',');
  const [contents] = await db().query(
    `SELECT id, path_id AS pathId, block_type AS type, content_value AS value, file_name AS fileName, mime_type AS mimeType
     FROM learning_path_content_blocks WHERE path_id IN (${placeholders}) ORDER BY sort_order ASC, id ASC`, ids
  );
  const [questions] = await db().query(
    `SELECT id, path_id AS pathId, question_text AS text FROM learning_path_questions
     WHERE path_id IN (${placeholders}) ORDER BY sort_order ASC, id ASC`, ids
  );
  const questionIds = questions.map((question) => Number(question.id));
  let options = [];
  if (questionIds.length) {
    const [rows] = await db().query(
      `SELECT id, question_id AS questionId, option_text AS text${includeAnswers ? ', is_correct AS isCorrect' : ''}
       FROM learning_path_options WHERE question_id IN (${questionIds.map(() => '?').join(',')}) ORDER BY sort_order ASC, id ASC`, questionIds
    );
    options = rows;
  }
  const programs = paths.map((path) => ({
    ...path,
    id: Number(path.id),
    sectionsEnabled: Boolean(path.sectionsEnabled),
    pointsReward: Number(path.pointsReward || 0),
    allowMultipleAttempts: Boolean(path.allowMultipleAttempts),
    score: Number(path.score || 0),
    totalQuestions: Number(path.totalQuestions || 0),
    earnedPoints: Number(path.earnedPoints || 0),
    completedAt: path.completedAt || null,
    contents: contents.filter((item) => Number(item.pathId) === Number(path.id)).map((item) => ({ ...item, id: Number(item.id) })),
    questions: questions.filter((item) => Number(item.pathId) === Number(path.id)).map((question) => ({
      ...question,
      id: Number(question.id),
      options: options.filter((option) => Number(option.questionId) === Number(question.id)).map((option) => ({
        id: Number(option.id), text: option.text, ...(includeAnswers ? { isCorrect: Boolean(option.isCorrect) } : {}),
      })),
    })),
  }));
  const selected = pathId && programs.find(program => program.id === Number(pathId));
  return selected?.parentPathId ? [selected] : groupProgramSections(programs);
}

async function replaceProgramChildren(connection, pathId, payload) {
  await connection.query('DELETE FROM learning_path_content_blocks WHERE path_id = ?', [pathId]);
  await connection.query('DELETE FROM learning_path_questions WHERE path_id = ?', [pathId]);
  for (const [index, item] of payload.contents.entries()) {
    await connection.query(
      'INSERT INTO learning_path_content_blocks (path_id, block_type, content_value, file_name, mime_type, sort_order) VALUES (?, ?, ?, ?, ?, ?)',
      [pathId, item.type, item.value, item.fileName || null, item.mimeType || null, index]
    );
  }
  for (const [questionIndex, question] of payload.questions.entries()) {
    const [result] = await connection.query(
      'INSERT INTO learning_path_questions (path_id, question_text, sort_order) VALUES (?, ?, ?)',
      [pathId, question.text, questionIndex]
    );
    for (const [optionIndex, option] of question.options.entries()) {
      await connection.query(
        'INSERT INTO learning_path_options (question_id, option_text, is_correct, sort_order) VALUES (?, ?, ?, ?)',
        [result.insertId, option.text, option.isCorrect ? 1 : 0, optionIndex]
      );
    }
  }
}

export function createProgramRouter({ loadSettings, applyStudentPointDelta, logStudentPointTransaction, getToday }) {
  const router = express.Router();
  const requireProgramManagement = (req, res, next) => {
    if (req.auth?.role === 'student') {
      return res.status(403).json({ message: 'ليس لديك صلاحية إدارة البرامج.' });
    }
    return requirePermission('programs')(req, res, next);
  };
  const ensureEnabled = async (req, res, next) => {
    try {
      if (!(await loadSettings()).learningPathsEnabled) return res.status(404).json({ message: 'البرامج غير مفعلة.' });
      return next();
    } catch (error) { return next(error); }
  };

  router.get('/configuration', requireProgramManagement, async (_req, res, next) => {
    try {
      const settings = await loadSettings();
      return res.json({ learningPathsEnabled: Boolean(settings.learningPathsEnabled) });
    } catch (error) {
      return next(error);
    }
  });

  router.patch('/configuration', requireProgramManagement, async (req, res, next) => {
    try {
      const learningPathsEnabled = req.body.learningPathsEnabled === true;
      await db().query(
        `INSERT INTO app_settings (setting_key, setting_value) VALUES ('learningPathsEnabled', ?)
         ON DUPLICATE KEY UPDATE setting_value = VALUES(setting_value)`,
        [String(learningPathsEnabled)],
      );
      return res.json({ learningPathsEnabled });
    } catch (error) {
      return next(error);
    }
  });

  router.use(ensureEnabled);
  router.get('/', async (req, res, next) => {
    try {
      const studentId = req.auth?.role === 'student' ? Number(req.auth.id) : null;
      res.json({ programs: await loadPrograms({ studentId, includeAnswers: !studentId }) });
    } catch (error) { next(error); }
  });
  router.post('/', requireProgramManagement, async (req, res, next) => {
    const connection = await db().getConnection();
    try {
      const payload = normalizePayload(req.body);
      await connection.beginTransaction();
      const [result] = await connection.query(
        'INSERT INTO learning_paths (title, status, points_reward, allow_multiple_attempts, sort_order) VALUES (?, ?, ?, ?, ?)',
        [payload.title, payload.status, payload.pointsReward, payload.allowMultipleAttempts ? 1 : 0, Number(req.body.sortOrder || 0)]
      );
      await replaceProgramChildren(connection, result.insertId, payload);
      await saveProgramSections(connection, result.insertId, payload.sections, replaceProgramChildren);
      await connection.commit();
      res.status(201).json({ program: (await loadPrograms({ pathId: result.insertId, includeAnswers: true }))[0] });
    } catch (error) { await connection.rollback(); next(error); } finally { connection.release(); }
  });
  router.put('/:id', requireProgramManagement, async (req, res, next) => {
    const connection = await db().getConnection();
    try {
      const payload = normalizePayload(req.body);
      await connection.beginTransaction();
      const [[current]] = await connection.query('SELECT parent_path_id AS parentPathId FROM learning_paths WHERE id = ? FOR UPDATE', [req.params.id]);
      if (current?.parentPathId) payload.allowMultipleAttempts = false;
      if (current?.parentPathId && payload.sections.length) throw fail('لا يمكن إضافة أقسام داخل القسم.');
      const [prior] = await connection.query('SELECT student_id FROM student_path_progress WHERE path_id = ? LIMIT 1', [req.params.id]);
      if (prior.length && payload.sections.length) throw fail('لا يمكن تحويل برنامج له نتائج إلى أقسام.');
      const [result] = await connection.query(
        'UPDATE learning_paths SET title = ?, status = ?, points_reward = ?, allow_multiple_attempts = ? WHERE id = ?',
        [payload.title, payload.status, payload.pointsReward, payload.allowMultipleAttempts ? 1 : 0, req.params.id]
      );
      if (!result.affectedRows) throw fail('المستوى غير موجود.', 404);
      await replaceProgramChildren(connection, req.params.id, payload);
      await saveProgramSections(connection, req.params.id, payload.sections, replaceProgramChildren);
      await connection.commit();
      res.json({ program: (await loadPrograms({ pathId: req.params.id, includeAnswers: true }))[0] });
    } catch (error) { await connection.rollback(); next(error); } finally { connection.release(); }
  });
  router.delete('/:id', requireProgramManagement, async (req, res, next) => {
    const connection = await db().getConnection();
    try {
      await connection.beginTransaction();
      await deleteProgram(connection, req.params.id);
      await connection.commit();
      return res.json({ ok: true });
    } catch (error) { await connection.rollback(); return next(error); }
    finally { connection.release(); }
  });
  router.get('/:id/grades', requireProgramManagement, async (req, res, next) => {
    try {
      const scope = req.auth.role === 'supervisor';
      const [students] = await db().query(`SELECT s.id, s.name, sp.earned_points AS earnedPoints, sp.completed_at AS completedAt
        FROM students s LEFT JOIN student_path_progress sp ON sp.student_id = s.id AND sp.path_id = ?
        ${scope ? 'WHERE EXISTS (SELECT 1 FROM supervisor_committees sc WHERE sc.committee_id = s.committee_id AND sc.supervisor_id = ?)' : ''}
        ORDER BY s.name, s.id`, scope ? [req.params.id, req.auth.id] : [req.params.id]);
      res.json({ students });
    } catch (error) { next(error); }
  });
  router.put('/:id/grades/:studentId', requireProgramManagement, async (req, res, next) => {
    const connection = await db().getConnection();
    try {
      await connection.beginTransaction();
      const result = await saveManualProgramPoints(connection, {
        programId: Number(req.params.id), studentId: Number(req.params.studentId), points: req.body.points,
        actor: req.auth, settings: await loadSettings(), date: getToday(),
      }, { applyStudentPointDelta, logStudentPointTransaction });
      await connection.commit();
      res.json(result);
    } catch (error) { await connection.rollback(); next(error); } finally { connection.release(); }
  });
  router.post('/:id/submit', async (req, res, next) => {
    if (req.auth?.role !== 'student') return res.status(403).json({ message: 'التقييم متاح للطلاب فقط.' });
    const connection = await db().getConnection();
    try {
      const settings = await loadSettings();
      const [program] = await loadPrograms({ studentId: Number(req.auth.id), pathId: req.params.id, includeAnswers: true });
      if (!program) throw fail('المستوى غير موجود أو غير متاح.', 404);
      if (!program.questions.length) throw fail('لا توجد أسئلة في هذا المستوى.');
      const answers = req.body?.answers && typeof req.body.answers === 'object' ? req.body.answers : {};
      const results = program.questions.map((question) => {
        const correct = question.options.find((option) => option.isCorrect);
        const selectedOptionId = Number(answers[question.id] || 0);
        return { questionId: question.id, selectedOptionId, correctOptionId: correct.id, correct: selectedOptionId === correct.id };
      });
      const score = results.filter((item) => item.correct).length;
      await connection.beginTransaction();
      await connection.query('SELECT id FROM students WHERE id = ? FOR UPDATE', [req.auth.id]);
      const [[previous]] = await connection.query(
        'SELECT score, earned_points AS earnedPoints FROM student_path_progress WHERE student_id = ? AND path_id = ? FOR UPDATE',
        [req.auth.id, req.params.id]
      );
      if (previous && !program.allowMultipleAttempts) throw fail('سبق لك إكمال هذا الاختبار.', 409);
      const targetPoints = settings.pointsSystemEnabled
        ? Math.round(program.pointsReward * score / program.questions.length)
        : 0;
      const delta = targetPoints - Number(previous?.earnedPoints || 0);
      if (delta) {
        await applyStudentPointDelta(connection, req.auth.id, delta, settings, { date: getToday() });
      }
      if (targetPoints > 0) {
        await logStudentPointTransaction(connection, {
          studentId: req.auth.id, actorRole: 'student', actorName: req.auth.name || 'الطالب',
          type: 'increase', points: targetPoints, reason: `إكمال برنامج: ${program.title}`,
          date: getToday(), sourceType: 'learning_path', sourceId: program.id,
          dedupeKey: `learning_path:${req.auth.id}:${program.id}`,
        });
      } else {
        await connection.query(
          'DELETE FROM student_point_transactions WHERE dedupe_key = ?',
          [`learning_path:${req.auth.id}:${program.id}`],
        );
      }
      await connection.query(
        `INSERT INTO student_path_progress (student_id, path_id, status, score, total_questions, earned_points, completed_at)
         VALUES (?, ?, 'completed', ?, ?, ?, NOW())
         ON DUPLICATE KEY UPDATE status = 'completed', score = ?, total_questions = ?, earned_points = ?, completed_at = NOW()`,
        [req.auth.id, program.id, score, program.questions.length, targetPoints, score, program.questions.length, targetPoints]
      );
      await connection.commit();
      res.json({ score, totalQuestions: program.questions.length, earnedPoints: targetPoints, awardedPoints: delta, results });
    } catch (error) { await connection.rollback(); next(error); } finally { connection.release(); }
  });
  return router;
}

import express from 'express';
import { db } from '../db.js';
import { requirePermission } from '../services/dashboardPermissions.js';
import { isUuid } from '../../shared/offline-recitation.js';
import { countTrailingCharacter } from '../../shared/string-suffix.js';

const MAX_IMAGE_BYTES = 10 * 1024 * 1024;
const IMAGE_DATA_PATTERN = /^data:image\/(?:png|jpe?g|webp);base64,[a-zA-Z0-9+/=]+$/;

const cleanText = (value, maxLength) => String(value || '').trim().slice(0, maxLength);
const isDateOnly = (value) => /^\d{4}-\d{2}-\d{2}$/.test(String(value || ''));
const daysBetween = (from, to) => Math.floor((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86400000);

const imageByteLength = (imageData) => {
  const base64 = String(imageData || '').split(',')[1] || '';
  const padding = countTrailingCharacter(base64, '=');
  return Math.max(0, Math.floor((base64.length * 3) / 4) - padding);
};

function normalizeProductPayload(body = {}, current = null) {
  const name = cleanText(body.name ?? current?.name, 180);
  const imageData = String(body.imageData ?? current?.imageData ?? '').trim();
  const pointsPrice = Math.trunc(Number(body.pointsPrice ?? current?.pointsPrice ?? 0));
  const rawStock = body.stock ?? current?.stock;
  const stock = rawStock === '' || rawStock === null || rawStock === undefined
    ? null
    : Math.trunc(Number(rawStock));
  const isActive = body.isActive === undefined ? current?.isActive !== false : body.isActive === true;

  if (!name) throw Object.assign(new Error('اسم المنتج مطلوب.'), { statusCode: 422 });
  if (!IMAGE_DATA_PATTERN.test(imageData) || imageByteLength(imageData) > MAX_IMAGE_BYTES) {
    throw Object.assign(new Error('صورة المنتج غير صالحة أو يتجاوز حجمها 10 ميجابايت.'), { statusCode: 422 });
  }
  if (!Number.isFinite(pointsPrice) || pointsPrice < 1) {
    throw Object.assign(new Error('سعر المنتج بالكيلومترات يجب أن يكون كيلومترًا واحدًا أو أكثر.'), { statusCode: 422 });
  }
  if (stock !== null && (!Number.isFinite(stock) || stock < 0)) {
    throw Object.assign(new Error('كمية المخزون غير صحيحة.'), { statusCode: 422 });
  }
  return { name, imageData, pointsPrice, stock, isActive };
}

const mapProduct = (row) => ({
  id: Number(row.id),
  name: row.name,
  imageData: row.imageData,
  pointsPrice: Number(row.pointsPrice || 0),
  stock: row.stock === null ? null : Number(row.stock),
  isActive: Boolean(row.isActive),
});

export function createStoreRouter({
  loadSettings,
  applyStudentPointDelta,
  logStudentPointTransaction,
  getToday,
}) {
  const router = express.Router();
  const requireStoreManagement = (req, res, next) => {
    if (!['manager', 'admin'].includes(req.auth?.role)) {
      return res.status(403).json({ message: 'إدارة المتجر متاحة للإداريين فقط.' });
    }
    return requirePermission('store')(req, res, next);
  };

  router.get('/configuration', requireStoreManagement, async (_req, res, next) => {
    try {
      const settings = await loadSettings();
      return res.json({
        pointsSystemEnabled: Boolean(settings.pointsSystemEnabled),
        storeEnabled: Boolean(settings.pointsSystemEnabled && settings.storeEnabled),
        storePurchaseDeductsRanking: Boolean(settings.storePurchaseDeductsRanking),
      });
    } catch (error) {
      return next(error);
    }
  });

  router.patch('/configuration', requireStoreManagement, async (req, res, next) => {
    try {
      const current = await loadSettings();
      const requestedEnabled = req.body.storeEnabled === undefined
        ? Boolean(current.storeEnabled)
        : req.body.storeEnabled === true;
      if (requestedEnabled && !current.pointsSystemEnabled) {
        return res.status(422).json({ message: 'فعّل نظام الكيلومترات أولاً.' });
      }
      const storeEnabled = Boolean(current.pointsSystemEnabled && requestedEnabled);
      const storePurchaseDeductsRanking = storeEnabled && (req.body.storePurchaseDeductsRanking === undefined
        ? Boolean(current.storePurchaseDeductsRanking)
        : req.body.storePurchaseDeductsRanking === true);
      await db().query(
        `INSERT INTO app_settings (setting_key, setting_value) VALUES
          ('storeEnabled', ?),
          ('storePurchaseDeductsRanking', ?)
         ON DUPLICATE KEY UPDATE setting_value = VALUES(setting_value)`,
        [String(storeEnabled), String(storePurchaseDeductsRanking)],
      );
      return res.json({
        pointsSystemEnabled: Boolean(current.pointsSystemEnabled),
        storeEnabled,
        storePurchaseDeductsRanking,
      });
    } catch (error) {
      return next(error);
    }
  });

  router.get('/products', async (req, res, next) => {
    try {
      const settings = await loadSettings();
      if (!settings.pointsSystemEnabled || !settings.storeEnabled) {
        return res.status(404).json({ message: 'المتجر غير مفعل.' });
      }
      if (!['student', 'manager', 'admin'].includes(req.auth?.role)) {
        return res.status(403).json({ message: 'لا يمكنك الوصول إلى المتجر.' });
      }
      const management = req.auth?.role === 'manager' || req.auth?.role === 'admin';
      const [rows] = await db().query(
        `
        SELECT
          id,
          name,
          image_data AS imageData,
          points_price AS pointsPrice,
          stock,
          is_active AS isActive
        FROM store_products
        WHERE deleted_at IS NULL
          ${management ? '' : 'AND is_active = 1 AND (stock IS NULL OR stock > 0)'}
        ORDER BY is_active DESC, created_at DESC, id DESC
        `,
      );
      if (req.auth?.role !== 'student') return res.json({ products: rows.map(mapProduct) });
      const [[student]] = await db().query(
        'SELECT store_balance AS storeBalance FROM students WHERE id = ?',
        [req.auth.id],
      );
      return res.json({
        products: rows.map(mapProduct),
        storeBalance: Number(student?.storeBalance || 0),
      });
    } catch (error) {
      return next(error);
    }
  });

  router.post('/products', requireStoreManagement, async (req, res, next) => {
    try {
      const product = normalizeProductPayload(req.body);
      const [result] = await db().query(
        `
        INSERT INTO store_products (name, description, image_data, points_price, stock, is_active)
        VALUES (?, NULL, ?, ?, ?, ?)
        `,
        [product.name, product.imageData, product.pointsPrice, product.stock, product.isActive ? 1 : 0],
      );
      return res.status(201).json({ ...product, id: Number(result.insertId) });
    } catch (error) {
      return next(error);
    }
  });

  router.put('/products/:id', requireStoreManagement, async (req, res, next) => {
    try {
      const [[row]] = await db().query(
        `SELECT id, name, image_data AS imageData, points_price AS pointsPrice, stock, is_active AS isActive
         FROM store_products WHERE id = ? AND deleted_at IS NULL`,
        [req.params.id],
      );
      if (!row) return res.status(404).json({ message: 'المنتج غير موجود.' });
      const product = normalizeProductPayload(req.body, mapProduct(row));
      await db().query(
        `UPDATE store_products
         SET name = ?, description = NULL, image_data = ?, points_price = ?, stock = ?, is_active = ?
         WHERE id = ? AND deleted_at IS NULL`,
        [product.name, product.imageData, product.pointsPrice, product.stock, product.isActive ? 1 : 0, req.params.id],
      );
      return res.json({ ...product, id: Number(req.params.id) });
    } catch (error) {
      return next(error);
    }
  });

  router.delete('/products/:id', requireStoreManagement, async (req, res, next) => {
    try {
      const [result] = await db().query(
        'UPDATE store_products SET is_active = 0, deleted_at = NOW() WHERE id = ? AND deleted_at IS NULL',
        [req.params.id],
      );
      if (!result.affectedRows) return res.status(404).json({ message: 'المنتج غير موجود.' });
      return res.json({ ok: true });
    } catch (error) {
      return next(error);
    }
  });

  router.patch('/products/:id/active', requireStoreManagement, async (req, res, next) => {
    try {
      const isActive = req.body.isActive === true;
      const [result] = await db().query(
        'UPDATE store_products SET is_active = ? WHERE id = ? AND deleted_at IS NULL',
        [isActive ? 1 : 0, req.params.id],
      );
      if (!result.affectedRows) return res.status(404).json({ message: 'المنتج غير موجود.' });
      return res.json({ ok: true, isActive });
    } catch (error) {
      return next(error);
    }
  });

  router.get('/orders', requireStoreManagement, async (_req, res, next) => {
    try {
      const [rows] = await db().query(
        `
        SELECT
          o.id,
          o.product_name AS productName,
          o.points_price AS pointsPrice,
          o.fulfilled_at AS fulfilledAt,
          DATE_FORMAT(o.created_at, '%Y-%m-%d %H:%i') AS createdAt,
          s.name AS studentName,
          c.name AS committeeName
        FROM store_orders o
        JOIN students s ON s.id = o.student_id
        LEFT JOIN committees c ON c.id = s.committee_id
        ORDER BY o.fulfilled_at IS NULL DESC, o.created_at DESC, o.id DESC
        `,
      );
      return res.json(rows.map((row) => ({
        ...row,
        id: Number(row.id),
        pointsPrice: Number(row.pointsPrice || 0),
        fulfilled: Boolean(row.fulfilledAt),
      })));
    } catch (error) {
      return next(error);
    }
  });

  router.patch('/orders/:id/fulfilled', requireStoreManagement, async (req, res, next) => {
    try {
      const fulfilled = req.body.fulfilled === true;
      const [result] = await db().query(
        `UPDATE store_orders
         SET fulfilled_at = ${fulfilled ? 'COALESCE(fulfilled_at, NOW())' : 'NULL'},
             fulfilled_by_role = ?,
             fulfilled_by_id = ?
         WHERE id = ?`,
        [fulfilled ? req.auth?.role || null : null, fulfilled ? req.auth?.id || null : null, req.params.id],
      );
      if (!result.affectedRows) return res.status(404).json({ message: 'الطلب غير موجود.' });
      return res.json({ ok: true, fulfilled });
    } catch (error) {
      return next(error);
    }
  });

  router.delete('/orders/:id', requireStoreManagement, async (req, res, next) => {
    try {
      const [result] = await db().query('DELETE FROM store_orders WHERE id = ?', [req.params.id]);
      if (!result.affectedRows) return res.status(404).json({ message: 'الطلب غير موجود.' });
      return res.json({ ok: true });
    } catch (error) {
      return next(error);
    }
  });

  router.post('/purchase', async (req, res, next) => {
    const connection = await db().getConnection();
    try {
      if (req.auth?.role !== 'student') {
        return res.status(403).json({ message: 'الشراء متاح للطالب فقط.' });
      }
      const productId = Number(req.body.productId || 0);
      const today = getToday();
      const purchaseDate = String(req.body.purchaseDate || today);
      const requestId = isUuid(req.body.requestId) ? String(req.body.requestId).toLowerCase() : null;
      if (!productId) return res.status(422).json({ message: 'اختر منتجاً.' });
      if (!isDateOnly(purchaseDate) || daysBetween(purchaseDate, today) < 0 || daysBetween(purchaseDate, today) > 14) {
        return res.status(422).json({ message: 'تاريخ الشراء غير صالح للمزامنة.' });
      }
      const settings = await loadSettings();
      if (!settings.pointsSystemEnabled || !settings.storeEnabled) {
        return res.status(409).json({ message: 'المتجر غير مفعل.' });
      }

      await connection.beginTransaction();
      const [[student]] = await connection.query(
        'SELECT id, points, store_balance AS storeBalance FROM students WHERE id = ? FOR UPDATE',
        [req.auth.id],
      );
      if (requestId) {
        const [[existingRequest]] = await connection.query(
          `SELECT id FROM store_orders
           WHERE student_id = ? AND request_id = ? LIMIT 1 FOR UPDATE`,
          [req.auth.id, requestId],
        );
        if (existingRequest) {
          const [[currentStudent]] = await connection.query(
            'SELECT store_balance AS storeBalance FROM students WHERE id = ?',
            [req.auth.id],
          );
          await connection.commit();
          return res.json({
            ok: true,
            message: 'تمت مزامنة الشراء سابقًا.',
            orderId: Number(existingRequest.id),
            purchaseDate,
            storeBalance: Number(currentStudent?.storeBalance || 0),
            alreadySynced: true,
          });
        }
      }
      const [[product]] = await connection.query(
        `SELECT id, name, points_price AS pointsPrice, stock
         FROM store_products
         WHERE id = ? AND is_active = 1 AND deleted_at IS NULL
         FOR UPDATE`,
        [productId],
      );
      if (!product || (product.stock !== null && Number(product.stock) < 1)) {
        await connection.rollback();
        return res.status(409).json({ message: 'المنتج غير متاح حالياً.' });
      }
      const price = Number(product.pointsPrice || 0);
      if (!student || Number(student.storeBalance || 0) < price) {
        await connection.rollback();
        return res.status(422).json({ message: 'رصيد المتجر غير كافٍ.' });
      }

      const [orderResult] = await connection.query(
        `INSERT INTO store_orders
          (student_id, product_id, product_name, points_price, order_date, request_id)
         VALUES (?, ?, ?, ?, ?, ?)`,
        [student.id, product.id, product.name, price, purchaseDate, requestId],
      );
      await connection.query(
        'UPDATE students SET store_balance = store_balance - ? WHERE id = ?',
        [price, student.id],
      );
      if (product.stock !== null) {
        await connection.query('UPDATE store_products SET stock = stock - 1 WHERE id = ?', [product.id]);
      }

      if (settings.storePurchaseDeductsRanking) {
        const effectiveDelta = await applyStudentPointDelta(connection, student.id, -price, settings, {
          date: purchaseDate,
          updateStoreBalance: false,
        });
        if (effectiveDelta) {
          await logStudentPointTransaction(connection, {
            studentId: student.id,
            actorRole: 'student',
            actorName: req.auth?.name || 'الطالب',
            type: 'deduction',
            points: Math.abs(effectiveDelta),
            reason: `شراء ${product.name}`,
            date: purchaseDate,
            sourceType: 'store_purchase',
            sourceId: orderResult.insertId,
            dedupeKey: `store_purchase:${orderResult.insertId}`,
          });
        }
      }

      await connection.commit();
      return res.status(201).json({
        ok: true,
        message: 'تم الشراء.',
        orderId: Number(orderResult.insertId),
        purchaseDate,
        storeBalance: Number(student.storeBalance || 0) - price,
      });
    } catch (error) {
      await connection.rollback();
      return next(error);
    } finally {
      connection.release();
    }
  });

  return router;
}

import express from 'express';
import { db } from '../db.js';
import {
  getSummitChallengeTitle,
  getSummitProgressSummary,
  normalizeSummitChallengeType,
} from '../../shared/summit.js';
import { SUMMIT_DAILY_CHALLENGE_GAME_TYPES } from '../../shared/daily-challenge.js';
import {
  createDailyChallenge,
  isDailyChallengeCorrect,
  sanitizeDailyChallenge,
} from '../../shared/daily-challenge-engine.js';
import {
  getSummitMapEventLocation,
  getSummitMapEventLocations,
  getSummitActiveStation,
  getSummitMapTotalKilometers,
  normalizeSummitMapConfig,
} from '../../shared/summit-map.js';
import {
  scoreSummitChallenge,
} from '../../shared/summit-engine.js';

const fail = (message, statusCode = 422) => Object.assign(new Error(message), { statusCode });

async function loadJourney(connection, studentId, settings) {
  const [[student]] = await connection.query(
    'SELECT points AS rankingPoints FROM students WHERE id = ? LIMIT 1',
    [studentId],
  );
  if (!student) throw fail('الطالب غير موجود.', 404);
  const [rewards] = await connection.query(
    `SELECT stage_points AS stagePoints, best_reward AS bestReward,
      attempts_count AS attemptsCount, completed_at AS completedAt
     FROM student_summit_stage_rewards WHERE student_id = ?`,
    [studentId],
  );
  const rewardByStage = new Map(rewards.map((row) => [Number(row.stagePoints), row]));
  const mapConfig = normalizeSummitMapConfig(settings.summitMapConfig);
  const configuredActiveStation = getSummitActiveStation(mapConfig);
  const activeStationReward = configuredActiveStation
    ? rewardByStage.get(Number(configuredActiveStation.kilometer))
    : null;
  const activeStation = configuredActiveStation && !activeStationReward?.completedAt
    ? configuredActiveStation
    : null;
  const totalKilometers = getSummitMapTotalKilometers(mapConfig);
  const configuredStages = getSummitMapEventLocations(mapConfig).map((location) => ({
    ...location,
    key: location.id,
    points: location.kilometer,
    duration: 45,
    challenge: location.challengeEnabled ? getSummitChallengeTitle(location.challengeType) : '',
  }));
  const stagesWithGoal = mapConfig.goal.enabled ? [...configuredStages, {
    id: 'mystery-goal', key: 'mystery-goal', name: mapConfig.goal.name,
    points: totalKilometers, kilometer: totalKilometers, duration: 0, isGoal: true,
    notificationEnabled: false, challengeEnabled: false, challenge: '',
  }] : configuredStages;
  const progressSummary = getSummitProgressSummary(student.rankingPoints, stagesWithGoal, totalKilometers);
  const summary = {
    ...progressSummary,
    reachedSummit: mapConfig.goal.enabled && progressSummary.reachedSummit,
  };
  const [[progressState]] = await connection.query(
    'SELECT kilometers FROM student_summit_progress WHERE student_id = ? LIMIT 1',
    [studentId],
  );
  const storedDisplayedKilometers = progressState
    ? Math.min(totalKilometers, Math.max(0, Number(progressState.kilometers || 0)))
    : summary.points;
  if (!progressState) {
    await connection.query(
      'INSERT IGNORE INTO student_summit_progress (student_id, kilometers) VALUES (?, ?)',
      [studentId, storedDisplayedKilometers],
    );
  }
  return {
    ...summary,
    totalKilometers,
    displayedKilometers: activeStation ? Number(activeStation.kilometer) : storedDisplayedKilometers,
    activeStation,
    enabled: Boolean(settings.summitEnabled),
    challengeMaxPoints: Math.max(0, Number(settings.summitChallengeMaxPoints || 50)),
    mapConfig,
    stages: stagesWithGoal.map((stage) => {
      const reward = rewardByStage.get(stage.points);
      return {
        ...stage,
        unlocked: summary.points >= stage.points,
        completed: stage.isGoal
          ? summary.reachedSummit
          : Boolean(reward?.completedAt),
        bestReward: Number(reward?.bestReward || 0),
        attemptsCount: Number(reward?.attemptsCount || 0),
      };
    }),
  };
}

export function createSummitRouter({
  loadSettings,
  applyStudentPointDelta,
  logStudentPointTransaction,
  getToday,
}) {
  const router = express.Router();

  router.get('/', async (req, res, next) => {
    try {
      if (req.auth?.role !== 'student') return res.status(403).json({ message: 'رحلة القمّة متاحة للطلاب فقط.' });
      const settings = await loadSettings();
      if (!settings.summitEnabled) return res.status(404).json({ message: 'رحلة القمّة غير مفعّلة.' });
      return res.json(await loadJourney(db(), req.auth.id, settings));
    } catch (error) { return next(error); }
  });

  router.put('/progress', async (req, res, next) => {
    try {
      if (req.auth?.role !== 'student') return res.status(403).json({ message: 'رحلة القمّة متاحة للطلاب فقط.' });
      const requested = Math.max(0, Math.trunc(Number(req.body?.kilometers) || 0));
      const settings = await loadSettings();
      const totalKilometers = getSummitMapTotalKilometers(settings.summitMapConfig);
      const [[student]] = await db().query('SELECT points FROM students WHERE id = ? LIMIT 1', [req.auth.id]);
      if (!student) throw fail('الطالب غير موجود.', 404);
      const kilometers = Math.min(totalKilometers, Number(student.points || 0), requested);
      await db().query(
        `INSERT INTO student_summit_progress (student_id, kilometers, reached_summit_at)
         VALUES (?, ?, IF(? >= ?, NOW(), NULL))
         ON DUPLICATE KEY UPDATE kilometers = VALUES(kilometers),
           reached_summit_at = IF(VALUES(kilometers) >= ?, COALESCE(reached_summit_at, NOW()), reached_summit_at)`,
        [req.auth.id, kilometers, kilometers, totalKilometers, totalKilometers],
      );
      return res.json({ kilometers });
    } catch (error) { return next(error); }
  });

  router.post('/stages/:points/acknowledge', async (req, res, next) => {
    try {
      if (req.auth?.role !== 'student') return res.status(403).json({ message: 'رحلة القمّة متاحة للطلاب فقط.' });
      const settings = await loadSettings();
      const stage = getSummitMapEventLocation(settings.summitMapConfig, req.params.points);
      if (
        !stage
        || stage.challengeEnabled
        || (!['station', 'city'].includes(stage.locationType) && !stage.notificationEnabled)
      ) {
        throw fail('لا يوجد إشعار مستقل في هذا الموقع.');
      }
      const [[student]] = await db().query('SELECT points FROM students WHERE id = ? LIMIT 1', [req.auth.id]);
      const activeStation = getSummitActiveStation(settings.summitMapConfig);
      const forcedStation = activeStation?.id === stage.id;
      if (!student || (!forcedStation && Number(student.points || 0) < Number(stage.kilometer))) {
        throw fail('لم تصل إلى هذا الموقع بعد.', 403);
      }
      await db().query(
        `INSERT INTO student_summit_stage_rewards
          (student_id, stage_points, best_reward, attempts_count, completed_at)
         VALUES (?, ?, 0, 0, NOW())
         ON DUPLICATE KEY UPDATE completed_at = COALESCE(completed_at, NOW())`,
        [req.auth.id, stage.kilometer],
      );
      return res.json({ ok: true });
    } catch (error) { return next(error); }
  });

  router.post('/stages/:points/start', async (req, res, next) => {
    const connection = await db().getConnection();
    try {
      if (req.auth?.role !== 'student') return res.status(403).json({ message: 'رحلة القمّة متاحة للطلاب فقط.' });
      const settings = await loadSettings();
      if (!settings.summitEnabled) throw fail('رحلة القمّة غير مفعّلة.', 404);
      const station = getSummitMapEventLocation(settings.summitMapConfig, req.params.points);
      if (!station?.challengeEnabled) throw fail('لا يوجد تحدٍ مفعّل في هذا الموقع.');
      const stage = {
        ...station,
        key: station.id,
        points: station.kilometer,
        duration: 45,
      };
      await connection.beginTransaction();
      const [[student]] = await connection.query(
        'SELECT points AS rankingPoints FROM students WHERE id = ? FOR UPDATE',
        [req.auth.id],
      );
      const activeStation = getSummitActiveStation(settings.summitMapConfig);
      const forcedStation = activeStation?.id === station.id;
      if (!student || (!forcedStation && Number(student.rankingPoints) < stage.points)) throw fail('لم تصل إلى هذه المرحلة بعد.', 403);
      const gameType = normalizeSummitChallengeType(station.challengeType);
      const challenge = gameType ? createDailyChallenge(gameType) : null;
      if (!challenge) throw fail('تعذر تجهيز تحدي هذا الموقع. راجع إعداد نوع التحدي.', 409);
      const attemptStage = { ...stage, challenge: getSummitChallengeTitle(gameType) };
      const [result] = await connection.query(
        'INSERT INTO student_summit_attempts (student_id, stage_points, challenge_json) VALUES (?, ?, ?)',
        [req.auth.id, stage.points, JSON.stringify({ gameType, challenge })],
      );
      await connection.commit();
      const publicAttempt = sanitizeDailyChallenge({
        id: result.insertId,
        challengeDate: getToday(),
        gameType,
        status: 'started',
        challenge,
      });
      return res.json({
        attemptId: result.insertId,
        stage: attemptStage,
        gameType,
        challenge: publicAttempt.challenge,
      });
    } catch (error) { await connection.rollback(); return next(error); } finally { connection.release(); }
  });

  router.post('/attempts/:attemptId/submit', async (req, res, next) => {
    const connection = await db().getConnection();
    try {
      if (req.auth?.role !== 'student') return res.status(403).json({ message: 'رحلة القمّة متاحة للطلاب فقط.' });
      const settings = await loadSettings();
      await connection.beginTransaction();
      const [[attempt]] = await connection.query(
        `SELECT id, stage_points AS stagePoints, challenge_json AS challengeJson, status,
          GREATEST(1, TIMESTAMPDIFF(SECOND, started_at, NOW())) AS elapsedSeconds
         FROM student_summit_attempts WHERE id = ? AND student_id = ? FOR UPDATE`,
        [req.params.attemptId, req.auth.id],
      );
      if (!attempt) throw fail('محاولة التحدي غير موجودة.', 404);
      if (attempt.status !== 'started') throw fail('سبق إنهاء هذه المحاولة.', 409);
      const station = getSummitMapEventLocation(settings.summitMapConfig, attempt.stagePoints);
      if (!station?.challengeEnabled) throw fail('تم تعطيل تحدي هذا الموقع.', 409);
      const stage = { ...station, points: station.kilometer, duration: 45 };
      const storedChallenge = JSON.parse(attempt.challengeJson);
      const challenge = storedChallenge.challenge || storedChallenge;
      const gameType = storedChallenge.gameType
        || normalizeSummitChallengeType(challenge.type);
      const score = SUMMIT_DAILY_CHALLENGE_GAME_TYPES.includes(gameType)
        ? scoreSummitChallenge(challenge, req.body, attempt.elapsedSeconds, stage.duration)
        : (() => {
            const completed = isDailyChallengeCorrect(gameType, challenge, req.body);
            return { completed, accuracy: completed ? 1 : 0, errors: completed ? 0 : 1, reward: completed ? 50 : 0 };
          })();
      let awardedPoints = 0;
      const [[previousReward]] = await connection.query(
        'SELECT best_reward AS bestReward FROM student_summit_stage_rewards WHERE student_id = ? AND stage_points = ? FOR UPDATE',
        [req.auth.id, stage.points],
      );
      if (score.completed) {
        const previousBest = Number(previousReward?.bestReward || 0);
        const maximumPoints = Math.max(0, Number(station.rewardPoints ?? settings.summitChallengeMaxPoints ?? 50));
        const calculatedPoints = Math.round((score.reward / 50) * maximumPoints);
        const improvement = Math.max(0, calculatedPoints - previousBest);
        const storedBest = settings.pointsSystemEnabled ? calculatedPoints : previousBest;
        if (settings.pointsSystemEnabled && improvement > 0) {
          awardedPoints = await applyStudentPointDelta(connection, req.auth.id, improvement, settings, { date: getToday() });
          if (awardedPoints > 0) {
            await logStudentPointTransaction(connection, {
              studentId: req.auth.id,
              actorRole: 'student',
              actorName: req.auth.name || 'الطالب',
              type: 'increase',
              points: awardedPoints,
              reason: `إكمال تحدي المسار: ${stage.name}`,
              date: getToday(),
              sourceType: 'summit_challenge',
              sourceId: attempt.id,
              dedupeKey: `summit_challenge:${attempt.id}`,
            });
          }
        }
        await connection.query(
          `INSERT INTO student_summit_stage_rewards
            (student_id, stage_points, best_reward, attempts_count, completed_at)
           VALUES (?, ?, ?, 1, NOW())
           ON DUPLICATE KEY UPDATE best_reward = GREATEST(best_reward, VALUES(best_reward)),
             attempts_count = attempts_count + 1, completed_at = COALESCE(completed_at, NOW())`,
          [req.auth.id, stage.points, storedBest],
        );
      } else {
        await connection.query(
          `INSERT INTO student_summit_stage_rewards (student_id, stage_points, attempts_count)
           VALUES (?, ?, 1) ON DUPLICATE KEY UPDATE attempts_count = attempts_count + 1`,
          [req.auth.id, stage.points],
        );
      }
      await connection.query(
        `UPDATE student_summit_attempts SET status = ?, accuracy = ?, errors_count = ?,
          reward_points = ?, completed_at = NOW() WHERE id = ?`,
        [score.completed ? 'completed' : 'failed', score.accuracy, score.errors, awardedPoints, attempt.id],
      );
      await connection.commit();
      return res.json({ ...score, awardedPoints });
    } catch (error) { await connection.rollback(); return next(error); } finally { connection.release(); }
  });

  return router;
}

import crypto from 'node:crypto';
import { createReadStream, createWriteStream } from 'node:fs';
import fs from 'node:fs/promises';
import nodePath from 'node:path';
import { spawn } from 'node:child_process';
import { pipeline } from 'node:stream/promises';
import { createGunzip, createGzip } from 'node:zlib';
import { DeleteObjectCommand, PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { db, getDatabaseContext } from '../db.js';

const DEFAULT_TIME = '03:00';
export const BACKUP_RETENTION_COUNT = 2;
const BACKUP_SETTING_KEYS = [
  'backupRemoteEnabled',
];

function backupError(message, statusCode = 503) {
  const error = new Error(message);
  error.statusCode = statusCode;
  return error;
}

const booleanValue = (value) => value === true || value === 'true' || value === '1';

function backupRoot() {
  return nodePath.resolve(process.env.BACKUP_DIRECTORY || nodePath.join(process.cwd(), 'backups'));
}

function databaseBackupDirectory(databaseName) {
  if (!/^\w+$/.test(databaseName)) throw new Error('اسم قاعدة البيانات غير صالح للنسخ الاحتياطي.');
  return nodePath.join(backupRoot(), databaseName);
}

async function loadBackupSettingRows() {
  const [rows] = await db().query(
    `SELECT setting_key AS settingKey, setting_value AS settingValue
     FROM app_settings WHERE setting_key IN (?)`,
    [BACKUP_SETTING_KEYS],
  );
  return Object.fromEntries(rows.map((row) => [row.settingKey, row.settingValue]));
}

export async function getBackupConfig() {
  const values = await loadBackupSettingRows();
  return {
    enabled: true,
    time: DEFAULT_TIME,
    retention: { latest: BACKUP_RETENTION_COUNT },
    remoteEnabled: booleanValue(values.backupRemoteEnabled),
    remoteConfigured: Boolean(
      process.env.BACKUP_S3_BUCKET
      && process.env.BACKUP_S3_ENDPOINT
      && process.env.BACKUP_S3_ACCESS_KEY_ID
      && process.env.BACKUP_S3_SECRET_ACCESS_KEY
    ),
  };
}

async function createCompressedDump(databaseName, targetPath) {
  const dump = spawn(process.env.MYSQLDUMP_BINARY || 'mysqldump', [
    '--single-transaction',
    '--quick',
    '--routines',
    '--triggers',
    '--events',
    '--hex-blob',
    '--no-tablespaces',
    '--default-character-set=utf8mb4',
    '--host', process.env.MYSQL_HOST || '127.0.0.1',
    '--port', String(process.env.MYSQL_PORT || 3306),
    '--user', process.env.MYSQL_USER || 'root',
    databaseName,
  ], {
    env: { ...process.env, MYSQL_PWD: process.env.MYSQL_PASSWORD || '' },
    windowsHide: true,
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let stderr = '';
  dump.stderr.setEncoding('utf8');
  dump.stderr.on('data', (chunk) => { stderr = `${stderr}${chunk}`.slice(-2000); });
  const exit = new Promise((resolve, reject) => {
    dump.once('error', reject);
    dump.once('close', (code) => code === 0
      ? resolve()
      : reject(new Error(stderr.trim() || `mysqldump exited with code ${code}`)));
  });
  try {
    await Promise.all([
      pipeline(dump.stdout, createGzip({ level: 9 }), createWriteStream(targetPath, { flags: 'wx' }))
        .catch((error) => { dump.kill(); throw error; }),
      exit,
    ]);
  } catch (error) {
    if (error.code === 'ENOENT') throw backupError('أداة mysqldump غير مثبتة أو مسارها غير صحيح على الخادم.');
    console.error('Database dump failed:', error.message);
    throw backupError('تعذر إنشاء تفريغ قاعدة البيانات. تحقق من أداة mysqldump وصلاحيات مستخدم قاعدة البيانات.');
  }
}

async function restoreCompressedDump(filePath, databaseName) {
  const mysql = spawn(process.env.MYSQL_BINARY || 'mysql', [
    '--default-character-set=utf8mb4',
    '--host', process.env.MYSQL_HOST || '127.0.0.1',
    '--port', String(process.env.MYSQL_PORT || 3306),
    '--user', process.env.MYSQL_USER || 'root',
    databaseName,
  ], {
    env: { ...process.env, MYSQL_PWD: process.env.MYSQL_PASSWORD || '' },
    windowsHide: true,
    stdio: ['pipe', 'ignore', 'pipe'],
  });
  let stderr = '';
  mysql.stderr.setEncoding('utf8');
  mysql.stderr.on('data', (chunk) => { stderr = `${stderr}${chunk}`.slice(-2000); });
  const exit = new Promise((resolve, reject) => {
    mysql.once('error', reject);
    mysql.once('close', (code) => code === 0
      ? resolve()
      : reject(new Error(stderr.trim() || `mysql exited with code ${code}`)));
  });
  try {
    await Promise.all([
      pipeline(createReadStream(filePath), createGunzip(), mysql.stdin)
        .catch((error) => { mysql.kill(); throw error; }),
      exit,
    ]);
  } catch (error) {
    if (error.code === 'ENOENT') throw backupError('أداة mysql غير مثبتة أو مسارها غير صحيح على الخادم.');
    console.error('Database restore failed:', error.message);
    throw backupError('تعذر استعادة النسخة الاحتياطية.');
  }
}

const quoteIdentifier = (value) => `\`${String(value).replaceAll('`', '``')}\``;

async function clearDatabase(connection, databaseName) {
  const [objects] = await connection.query(
    `SELECT TABLE_NAME AS tableName, TABLE_TYPE AS tableType
     FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = ?`,
    [databaseName],
  );
  const views = objects.filter(({ tableType }) => tableType === 'VIEW');
  const tables = objects.filter(({ tableType }) => tableType === 'BASE TABLE');
  await connection.query('SET FOREIGN_KEY_CHECKS = 0');
  try {
    for (const view of views) {
      await connection.query(`DROP VIEW IF EXISTS ${quoteIdentifier(databaseName)}.${quoteIdentifier(view.tableName)}`);
    }
    for (const table of tables) {
      await connection.query(`DROP TABLE IF EXISTS ${quoteIdentifier(databaseName)}.${quoteIdentifier(table.tableName)}`);
    }
  } finally {
    await connection.query('SET FOREIGN_KEY_CHECKS = 1');
  }
}

async function ensureBackupMetadataSchema(connection, databaseName) {
  const [[column]] = await connection.query(
    `SELECT COUNT(*) AS count FROM INFORMATION_SCHEMA.COLUMNS
     WHERE TABLE_SCHEMA = ? AND TABLE_NAME = 'backup_runs' AND COLUMN_NAME = 'retention_tiers'`,
    [databaseName],
  );
  if (!Number(column?.count)) {
    await connection.query('ALTER TABLE backup_runs ADD COLUMN retention_tiers JSON NULL AFTER storage_targets');
  }
}

async function recordSafetyBackup(connection, safety, actorName) {
  await connection.query(
    `INSERT INTO backup_runs
      (status, trigger_type, actor_name, file_name, size_bytes, checksum_sha256,
       storage_targets, retention_tiers, completed_at)
     VALUES ('completed', 'manual', ?, ?, ?, ?, ?, ?, NOW())`,
    [
      `نسخة طوارئ قبل الاستعادة - ${String(actorName).slice(0, 120)}`,
      safety.fileName,
      safety.sizeBytes,
      safety.checksum,
      JSON.stringify(safety.storageTargets),
      JSON.stringify(['safety']),
    ],
  );
}

async function sha256File(filePath) {
  const hash = crypto.createHash('sha256');
  for await (const chunk of createReadStream(filePath)) hash.update(chunk);
  return hash.digest('hex');
}

function createS3Client() {
  return new S3Client({
    region: process.env.BACKUP_S3_REGION || 'auto',
    endpoint: process.env.BACKUP_S3_ENDPOINT,
    forcePathStyle: booleanValue(process.env.BACKUP_S3_FORCE_PATH_STYLE),
    credentials: {
      accessKeyId: process.env.BACKUP_S3_ACCESS_KEY_ID,
      secretAccessKey: process.env.BACKUP_S3_SECRET_ACCESS_KEY,
    },
  });
}

async function uploadRemote(filePath, objectKey, tiers) {
  const client = createS3Client();
  try {
    const stat = await fs.stat(filePath);
    await client.send(new PutObjectCommand({
      Bucket: process.env.BACKUP_S3_BUCKET,
      Key: objectKey,
      Body: createReadStream(filePath),
      ContentLength: stat.size,
      ContentType: 'application/gzip',
      Metadata: { compressed: 'gzip', retention: tiers.join(',') },
    }));
  } finally {
    client.destroy();
  }
}

async function deleteRemote(objectKey) {
  const client = createS3Client();
  try {
    await client.send(new DeleteObjectCommand({ Bucket: process.env.BACKUP_S3_BUCKET, Key: objectKey }));
  } finally {
    client.destroy();
  }
}

const parseJsonArray = (value) => {
  if (Array.isArray(value)) return value;
  try {
    const parsed = JSON.parse(value || '[]');
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
};

const normalizeTiers = (tiers, trigger) => {
  const allowed = new Set(['weekly', 'monthly', 'yearly', 'safety', 'manual']);
  const normalized = [...new Set((Array.isArray(tiers) ? tiers : []).filter((tier) => allowed.has(tier)))];
  return normalized.length ? normalized : [trigger === 'scheduled' ? 'weekly' : 'manual'];
};

async function applyRetention(databaseName) {
  const [rows] = await db().query(
    `SELECT id, file_name AS fileName, storage_targets AS storageTargets,
      retention_tiers AS retentionTiers
     FROM backup_runs
     WHERE status = 'completed' AND file_name IS NOT NULL
     ORDER BY completed_at DESC, id DESC`,
  );
  const expired = rows.slice(BACKUP_RETENTION_COUNT).map(row => ({ ...row, storageTargets: parseJsonArray(row.storageTargets) }));

  const directory = databaseBackupDirectory(databaseName);
  const remoteConfigured = Boolean(
    process.env.BACKUP_S3_BUCKET
    && process.env.BACKUP_S3_ENDPOINT
    && process.env.BACKUP_S3_ACCESS_KEY_ID
    && process.env.BACKUP_S3_SECRET_ACCESS_KEY
  );
  for (const row of expired) {
    if (!row.fileName || nodePath.basename(row.fileName) !== row.fileName) continue;
    await fs.unlink(nodePath.join(directory, row.fileName)).catch((error) => {
      if (error.code !== 'ENOENT') throw error;
    });
    if (remoteConfigured && row.storageTargets.includes('remote')) {
      await deleteRemote(`${databaseName}/${row.fileName}`);
    }
    await db().query('DELETE FROM backup_runs WHERE id = ?', [row.id]);
  }
}

export async function createDatabaseBackup({
  trigger = 'manual',
  actorName = 'النظام',
  tiers,
  skipRetention = false,
} = {}) {
  const databaseName = getDatabaseContext().databaseName;
  const config = await getBackupConfig();
  const retentionTiers = normalizeTiers(tiers, trigger);
  if (config.remoteEnabled && !config.remoteConfigured) {
    throw backupError('التخزين الخارجي مفعّل لكن إعدادات S3/R2 غير مكتملة.');
  }

  const connection = await db().getConnection();
  const lockName = `madarij:backup:${crypto.createHash('sha256').update(databaseName).digest('hex').slice(0, 32)}`;
  let lockAcquired = false;
  let runId;
  let filePath;
  try {
    const [[lock]] = await connection.query('SELECT GET_LOCK(?, 0) AS acquired', [lockName]);
    lockAcquired = Number(lock?.acquired) === 1;
    if (!lockAcquired) throw backupError('يوجد نسخ احتياطي قيد التنفيذ حاليًا.', 409);
    const [result] = await connection.query(
      `INSERT INTO backup_runs (status, trigger_type, actor_name, retention_tiers)
       VALUES ('running', ?, ?, ?)`,
      [trigger, String(actorName || 'النظام').slice(0, 160), JSON.stringify(retentionTiers)],
    );
    runId = Number(result.insertId);
    const stamp = new Date().toISOString().replace(/[:.]/g, '-');
    const fileName = `${databaseName}-${stamp}.sql.gz`;
    const directory = databaseBackupDirectory(databaseName);
    filePath = nodePath.join(directory, fileName);
    await fs.mkdir(directory, { recursive: true });
    await createCompressedDump(databaseName, filePath);
    const stat = await fs.stat(filePath);
    const checksum = await sha256File(filePath);
    const targets = ['local'];
    if (config.remoteEnabled) {
      await uploadRemote(filePath, `${databaseName}/${fileName}`, retentionTiers);
      targets.push('remote');
    }
    await connection.query(
      `UPDATE backup_runs SET status = 'completed', file_name = ?, size_bytes = ?,
       checksum_sha256 = ?, storage_targets = ?, completed_at = NOW() WHERE id = ?`,
      [fileName, stat.size, checksum, JSON.stringify(targets), runId],
    );
    if (!skipRetention) await applyRetention(databaseName);
    return {
      id: String(runId),
      status: 'completed',
      fileName,
      sizeBytes: stat.size,
      checksum,
      storageTargets: targets,
      retentionTiers,
    };
  } catch (error) {
    const publicError = error.statusCode
      ? error
      : backupError('تعذر إكمال النسخة الاحتياطية. راجع إعدادات التخزين وسجل الخادم.');
    if (!error.statusCode) console.error('Database backup failed:', error.message);
    if (filePath) await fs.unlink(filePath).catch(() => {});
    if (runId) {
      await connection.query(
        `UPDATE backup_runs SET status = 'failed', error_message = ?, completed_at = NOW() WHERE id = ?`,
        [publicError.message, runId],
      ).catch(() => {});
    }
    throw publicError;
  } finally {
    if (lockAcquired) await connection.query('SELECT RELEASE_LOCK(?)', [lockName]).catch(() => {});
    connection.release();
  }
}

export async function listDatabaseBackups(limit = 30) {
  const [rows] = await db().query(
    `SELECT id, status, trigger_type AS triggerType, actor_name AS actorName,
      file_name AS fileName, size_bytes AS sizeBytes, checksum_sha256 AS checksum,
      storage_targets AS storageTargets, retention_tiers AS retentionTiers,
      error_message AS errorMessage,
      DATE_FORMAT(started_at, '%Y-%m-%d %H:%i') AS startedAt,
      DATE_FORMAT(completed_at, '%Y-%m-%d %H:%i') AS completedAt
     FROM backup_runs ORDER BY id DESC LIMIT ?`,
    [Math.min(100, Math.max(1, Number(limit) || 30))],
  );
  return rows.map((row) => ({
    ...row,
    id: String(row.id),
    sizeBytes: Number(row.sizeBytes || 0),
    storageTargets: Array.isArray(row.storageTargets)
      ? row.storageTargets
      : (() => { try { return JSON.parse(row.storageTargets || '[]'); } catch { return []; } })(),
    retentionTiers: normalizeTiers(parseJsonArray(row.retentionTiers), row.triggerType),
  }));
}

export async function resolveBackupDownload(runId) {
  const [[run]] = await db().query(
    `SELECT file_name AS fileName FROM backup_runs
     WHERE id = ? AND status = 'completed' LIMIT 1`,
    [runId],
  );
  if (!run?.fileName || nodePath.basename(run.fileName) !== run.fileName) return null;
  const databaseName = getDatabaseContext().databaseName;
  const filePath = nodePath.join(databaseBackupDirectory(databaseName), run.fileName);
  const stat = await fs.stat(filePath).catch(() => null);
  return stat?.isFile() ? { filePath, fileName: run.fileName } : null;
}

async function resolveBackupForRestore(runId) {
  const [[run]] = await db().query(
    `SELECT file_name AS fileName, checksum_sha256 AS checksum
     FROM backup_runs WHERE id = ? AND status = 'completed' LIMIT 1`,
    [runId],
  );
  if (!run?.fileName || nodePath.basename(run.fileName) !== run.fileName) return null;
  const databaseName = getDatabaseContext().databaseName;
  const filePath = nodePath.join(databaseBackupDirectory(databaseName), run.fileName);
  const stat = await fs.stat(filePath).catch(() => null);
  return stat?.isFile() ? { ...run, filePath, databaseName } : null;
}

export async function restoreDatabaseBackup(runId, actorName = 'المدير') {
  const selected = await resolveBackupForRestore(runId);
  if (!selected) throw backupError('النسخة الاحتياطية غير موجودة.', 404);
  const actualChecksum = await sha256File(selected.filePath);
  if (!selected.checksum || actualChecksum !== selected.checksum) {
    throw backupError('فشل التحقق من سلامة النسخة الاحتياطية.', 409);
  }

  const safety = await createDatabaseBackup({
    trigger: 'manual',
    actorName: `قبل الاستعادة - ${actorName}`,
    tiers: ['safety'],
    skipRetention: true,
  });
  const safetyPath = nodePath.join(databaseBackupDirectory(selected.databaseName), safety.fileName);
  const connection = await db().getConnection();
  const lockName = `madarij:backup:${crypto.createHash('sha256').update(selected.databaseName).digest('hex').slice(0, 32)}`;
  const temporaryDatabase = `${selected.databaseName.slice(0, 36)}_restore_${Date.now()}`;
  let lockAcquired = false;
  let liveRestoreStarted = false;
  try {
    const [[lock]] = await connection.query('SELECT GET_LOCK(?, 0) AS acquired', [lockName]);
    lockAcquired = Number(lock?.acquired) === 1;
    if (!lockAcquired) throw backupError('توجد عملية نسخ أو استعادة قيد التنفيذ حاليًا.', 409);

    await connection.query(`CREATE DATABASE \`${temporaryDatabase}\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`);
    try {
      await restoreCompressedDump(selected.filePath, temporaryDatabase);
      const [[validation]] = await connection.query(
        'SELECT COUNT(*) AS tableCount FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = ?',
        [temporaryDatabase],
      );
      if (!Number(validation?.tableCount)) throw backupError('النسخة الاحتياطية لا تحتوي على جداول قابلة للاستعادة.', 409);
    } finally {
      await connection.query(`DROP DATABASE IF EXISTS \`${temporaryDatabase}\``).catch(() => {});
    }

    liveRestoreStarted = true;
    await clearDatabase(connection, selected.databaseName);
    await restoreCompressedDump(selected.filePath, selected.databaseName);
    await ensureBackupMetadataSchema(connection, selected.databaseName);
    await connection.query('DELETE FROM auth_sessions');
    await recordSafetyBackup(connection, safety, actorName);
    await applyRetention(selected.databaseName);
    return { restored: true, safetyBackupCreated: true };
  } catch (error) {
    let rollbackSucceeded = false;
    if (liveRestoreStarted) {
      try {
        await clearDatabase(connection, selected.databaseName);
        await restoreCompressedDump(safetyPath, selected.databaseName);
        await ensureBackupMetadataSchema(connection, selected.databaseName);
        await connection.query('DELETE FROM auth_sessions');
        await recordSafetyBackup(connection, safety, actorName);
        rollbackSucceeded = true;
        await applyRetention(selected.databaseName).catch((retentionError) => {
          console.error('Backup retention after rollback failed:', retentionError.message);
        });
      } catch (rollbackError) {
        console.error('Database restore rollback failed:', rollbackError.message);
      }
    }
    if (liveRestoreStarted && rollbackSucceeded) {
      throw backupError('تعذرت الاستعادة وأعيدت البيانات إلى نسخة الطوارئ.', 503);
    }
    if (liveRestoreStarted) {
      throw backupError('تعذرت الاستعادة وكذلك العودة إلى نسخة الطوارئ. يلزم تدخل فني فورًا.', 503);
    }
    if (error.statusCode) throw error;
    console.error('Database restore operation failed:', error.message);
    await applyRetention(selected.databaseName).catch(() => {});
    throw backupError('تعذرت الاستعادة ولم تُغيّر البيانات الحالية.', 503);
  } finally {
    await connection.query(`DROP DATABASE IF EXISTS \`${temporaryDatabase}\``).catch(() => {});
    if (lockAcquired) await connection.query('SELECT RELEASE_LOCK(?)', [lockName]).catch(() => {});
    connection.release();
  }
}

export function scheduledBackupTiers(date) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(date || ''));
  if (!match) return [];
  const [, , month, day] = match;
  const weekday = new Date(`${date}T00:00:00Z`).getUTCDay();
  const tiers = [];
  if (weekday === 5) tiers.push('weekly');
  if (day === '01') tiers.push('monthly');
  if (month === '01' && day === '01') tiers.push('yearly');
  return tiers;
}

export async function runScheduledDatabaseBackup(now) {
  const config = await getBackupConfig();
  const [[latestSuccessful]] = await db().query(
    "SELECT id FROM backup_runs WHERE status = 'completed' LIMIT 1",
  );
  const scheduledTiers = scheduledBackupTiers(now.date);
  const isInitialBackup = !latestSuccessful;
  if (!isInitialBackup && (now.time.slice(0, 5) < config.time || !scheduledTiers.length)) return false;
  const tiers = scheduledTiers.length ? scheduledTiers : ['weekly'];
  const [[lastRun]] = await db().query(
    `SELECT id FROM backup_runs
     WHERE trigger_type = 'scheduled' AND DATE(started_at) = ?
       AND (status IN ('completed', 'running')
         OR started_at >= DATE_SUB(NOW(), INTERVAL 15 MINUTE))
     LIMIT 1`,
    [now.date],
  );
  if (lastRun) return false;
  await createDatabaseBackup({ trigger: 'scheduled', actorName: 'النظام', tiers });
  return true;
}

import { buildRecitationSegmentDetails, getQuranVerseLine } from './recitationSegments.js';
import { calculateSegmentedPlanPoints } from './quranPlanProgress.js';
