const position = (task, prefix) => ({ page: Number(task[`${prefix}Page`]), surah: Number(task[`${prefix}Surah`]), ayah: Number(task[`${prefix}Ayah`]) });
const getQuranRangeDirection = (start, end) => {
  if (start.surah !== end.surah) {
    if (start.surah < end.surah) {
      return 1;
    }
    return -1;
  }
  if (start.ayah <= end.ayah) {
    return 1;
  }
  return -1;
};
const missingRange = () => { const error = new Error('تعذر إثبات مقدار التسميع لاحتساب النقاط.'); error.statusCode = 409; throw error; };

export async function enqueueNazemPointReconciliation(connection, dailyId, snapshot) {
  const hash = crypto.createHash('sha256').update(JSON.stringify(snapshot)).digest('hex');
  await connection.query(`INSERT INTO nazem_point_reconciliations (daily_follow_up_id, source_hash)
    VALUES (?, ?) ON DUPLICATE KEY UPDATE
      status = IF(source_hash <> VALUES(source_hash), 'pending', status),
      source_hash = VALUES(source_hash)`, [dailyId, hash]);
}

async function adjacent(connection, start, direction) {
  if (direction >= 0) return loadAdjacentQuranPosition(connection, start, 'next');
  const [[same]] = await connection.query(`SELECT surah_number AS surah, ayah_number AS ayah, page_number AS page
    FROM quran_ayah_pages WHERE surah_number = ? AND ayah_number > ? ORDER BY ayah_number LIMIT 1`, [start.surah, start.ayah]);
  if (same) return same;
  const [[previous]] = await connection.query(`SELECT surah_number AS surah, ayah_number AS ayah, page_number AS page
    FROM quran_ayah_pages WHERE surah_number < ? ORDER BY surah_number DESC, ayah_number LIMIT 1`, [start.surah]);
  return previous || null;
}

export async function calculateNazemRewardGroups(connection, daily, tasks, settings) {
  const primary = tasks.filter((task) => task.taskType === daily.taskType && task.track === daily.track);
  if (!primary.length || primary.some((task) => !task.evaluatedAt)) {
    const error = new Error('متابعة ناظم لا تطابق مجموعة مهام مقيمة كاملة.'); error.statusCode = 409; throw error;
  }
  let reward = calculateEvaluatedGroupReward(primary);
  const first = primary[0];
  if (daily.taskType === 'memorization' && daily.track === first.planTrack) {
    const direction = getQuranRangeDirection(position(first, 'planStart'), position(first, 'planEnd'));
    const ordered = [...primary].sort((a, b) => compareQuranPositionInDirection(position(a, 'from'), position(b, 'from'), direction));
    const last = ordered.at(-1);
    const end = last.actualToAyah ? position(last, 'actualTo') : position(last, 'to');
    const context = { actualStart: position(ordered[0], 'from'), scheduledEnd: position(last, 'to'), normalEnd: position(last, 'to'), direction };
    const segments = await buildRecitationSegmentDetails(connection, context, end,
      { ...settings, allowQuranCompensation: false, allowQuranExtra: !Number(first.nazemLate) },
      { treatScheduledAsNormal: true, adjacentPosition: adjacent, rangeFaces: missingRange });
    reward = calculateSegmentedPlanPoints({ basePoints: reward, dailyAmount: Number(first.dailyPages || 1), segments,
      compensationPercent: settings.quranCompensationPointsPercent, extraPercent: settings.quranExtraPointsPercent }).total;
  }
  const groups = [{ taskType: daily.taskType, tasks: primary, points: reward }];
  const repeats = tasks.filter((task) => task.taskType === 'repeat' && task.track === daily.track);
  if (daily.taskType === 'memorization' && repeats.length) {
    const repeatReward = calculateStudentExecutionPoints({ taskType: 'memorization', track: daily.track,
      completedRepeatCount: Math.min(...repeats.map((task) => Number(task.actualRepeatCount || 0))), expectedRepeatCount: 30,
      completedListeningCount: Math.min(...repeats.map((task) => Number(task.actualListeningCount || 0))), expectedListeningCount: 1, settings });
    groups.push({ taskType: 'repeat', tasks: repeats, points: primary.every((task) => Number(task.teacherCompleted) === 1) ? repeatReward.total : 0 });
  }
  if (daily.taskType === 'memorization' && daily.track === 'memorization') {
    const links = tasks.filter((task) => task.taskType === 'link');
    if (links.length) {
      const remoteCount = isNazemFollowUpCompleted(daily.remoteResultStatus) ? readNazemLinkCount(daily.remoteLinkCount) : 0;
      if (remoteCount == null || links.some((task) => !task.evaluatedAt)
        || links.reduce((sum, task) => sum + Number(task.actualLinkCount || 0), 0) !== remoteCount) {
        const error = new Error('لم يثبت اكتمال مقدار الربط في ناظم؛ تحتاج نقاطه مراجعة.'); error.statusCode = 409; throw error;
      }
      groups.push({ taskType: 'link', tasks: links, points: calculateEvaluatedGroupReward(links) });
    }
  }
  return groups;
}

// Caller supplies a dedicated connection. Each settlement locks the student and is atomic.
export async function settleNazemPoints(connection, dailyId) {
  await connection.beginTransaction();
  let expected = null;
  let recorded = null;
  let sourceHash = null;
  try {
    const [[identity]] = await connection.query('SELECT ruwasi_student_id AS studentId FROM nazem_daily_follow_up_links WHERE id = ?', [dailyId]);
    if (!identity) { await connection.rollback(); return false; }
    await connection.query('SELECT id FROM students WHERE id = ? FOR UPDATE', [identity.studentId]);
    const [[daily]] = await connection.query(`SELECT d.id, d.ruwasi_student_id AS studentId, d.ruwasi_plan_id AS planId,
      d.teacher_id AS teacherId, DATE_FORMAT(d.follow_up_date, '%Y-%m-%d') AS taskDate, d.task_type AS taskType,
      d.track,
      JSON_UNQUOTE(JSON_EXTRACT(d.remote_snapshot, '$.status')) AS remoteResultStatus,
      JSON_UNQUOTE(JSON_EXTRACT(d.remote_snapshot, '$.link')) AS remoteLinkCount,
      JSON_UNQUOTE(JSON_EXTRACT(d.remote_snapshot, '$.attendanceStatus')) AS attendanceStatus,
      d.sync_status AS syncStatus, work.status, work.source_hash AS sourceHash
      FROM nazem_point_reconciliations work JOIN nazem_daily_follow_up_links d ON d.id = work.daily_follow_up_id
      WHERE d.id = ? FOR UPDATE`, [dailyId]);
    if (daily?.status !== 'pending') { await connection.commit(); return false; }
    sourceHash = daily.sourceHash;
    if (daily.syncStatus !== 'synced') { await connection.commit(); return false; }
    const [[activation]] = await connection.query("SELECT setting_value AS value FROM app_settings WHERE setting_key = 'nazemPointsStartDate'");
    const [tasks] = await connection.query(`SELECT task.id, task.task_type AS taskType, task.track, task.points,
      task.evaluated_at AS evaluatedAt, task.teacher_completed AS teacherCompleted, task.evaluation_score AS evaluationScore,
      task.from_page AS fromPage, task.from_surah AS fromSurah, task.from_ayah AS fromAyah,
      task.to_page AS toPage, task.to_surah AS toSurah, task.to_ayah AS toAyah,
      task.actual_to_page AS actualToPage, task.actual_to_surah AS actualToSurah, task.actual_to_ayah AS actualToAyah,
      task.actual_link_count AS actualLinkCount, task.actual_repeat_count AS actualRepeatCount, task.actual_listening_count AS actualListeningCount,
      ${buildNazemLateTaskExistsSql('task')} AS nazemLate, plan.daily_pages AS dailyPages, plan.track AS planTrack,
      plan.start_page AS planStartPage, plan.start_surah AS planStartSurah, plan.start_ayah AS planStartAyah,
      plan.end_page AS planEndPage, plan.end_surah AS planEndSurah, plan.end_ayah AS planEndAyah
      FROM student_quran_tasks task JOIN student_quran_plans plan ON plan.id = task.plan_id
      WHERE task.plan_id = ? AND task.student_id = ? AND task.task_date = ? AND task.track = ? FOR UPDATE`,
    [daily.planId, daily.studentId, daily.taskDate, daily.track]);
    const settings = await loadRecitationRewardSettings(connection);
    const groups = await calculateNazemRewardGroups(connection, daily, tasks, settings);
    expected = groups.reduce((sum, group) => sum + group.points, 0);
    const ids = groups.flatMap((group) => group.tasks.map((task) => Number(task.id)));
    const [[ledger]] = await connection.query(`SELECT COALESCE(SUM(CASE WHEN transaction_type = 'increase' THEN points ELSE -points END), 0) AS total
      FROM student_point_transactions WHERE student_id = ? AND source_type IN ('quran_plan','quran_execution','quran_evaluation')
        AND source_id IN (${ids.map(() => '?').join(',')})`, [daily.studentId, ...ids]);
    recorded = Number(ledger.total || 0);
    if (!activation?.value || daily.taskDate < activation.value || !settings.pointsSystemEnabled) {
      const error = new Error(!settings.pointsSystemEnabled ? 'نظام النقاط غير مفعّل.' : 'تاريخ الاستحقاق يسبق تفعيل تسوية نقاط ناظم؛ يحتاج مراجعة.');
      error.statusCode = 409; throw error;
    }
    const attendanceStatus = { 2: 'present', 3: 'absent', 4: 'excused', 5: 'late' }[Number(daily.attendanceStatus)];
    if (attendanceStatus) await saveAttendanceWithPoints(connection, { studentId: daily.studentId,
      date: daily.taskDate, status: attendanceStatus, awardNewPoints: true }, await loadAttendancePointSettings(connection));
    const delta = (group) => group.points - group.tasks.reduce((sum, task) => sum + Number(task.points || 0), 0);
    const _resolveReason = (group) => {
      if (group.taskType === 'repeat') {
        return 'اعتماد التكرار والسماع من ناظم';
      }
      if (group.taskType === 'link') {
        return 'اعتماد الربط من ناظم';
      }
      if (daily.track === 'mastery') {
        return 'اعتماد الإتقان من ناظم';
      }
      if (group.taskType === 'review') {
        return 'اعتماد المراجعة من ناظم';
      }
      return 'اعتماد الحفظ من ناظم';
    };
    for (const group of [...groups].sort((a, b) => delta(a) - delta(b))) await setQuranTaskGroupReward(connection, {
      taskIds: group.tasks.map((task) => task.id), studentId: daily.studentId, targetPoints: group.points,
      settings, date: daily.taskDate, actorRole: 'system', actorName: 'مزامنة ناظم', supervisorId: daily.teacherId,
      sourceType: 'quran_evaluation', reason: _resolveReason(group),
      dedupeKey: `quran_evaluation:${daily.planId}:${daily.taskDate}:${group.taskType}${daily.track === 'mastery' ? ':mastery' : ''}`,
    });
    await connection.query(`UPDATE nazem_point_reconciliations SET status = 'synced', expected_points = ?, recorded_points = ?,
      last_error = NULL, checked_at = NOW(3) WHERE daily_follow_up_id = ?`, [expected, expected, dailyId]);
    await connection.commit();
    return true;
  } catch (error) {
    await connection.rollback();
    if (![409, 422].includes(Number(error.statusCode))) throw error;
    await connection.query(`UPDATE nazem_point_reconciliations SET status = 'requires_review', expected_points = ?, recorded_points = ?,
      last_error = ?, checked_at = NOW(3) WHERE daily_follow_up_id = ? AND status = 'pending' AND source_hash = ?`,
    [expected, recorded, publicErrorMessage(error).slice(0, 500), dailyId, sourceHash]);
    return false;
  }
}

import { getBusinessDate } from '../../shared/business-date.js';

export function reconciliationStatus(row) {
  if (!row.dailyId) return 'unlinked';
  if (row.remoteStatus !== 'synced' || !row.remoteRecordId) return row.localAccepted ? 'local_only' : 'unverified';
  if (!row.localAccepted) return 'remote_only';
  if (row.pointsStatus === 'requires_review') return 'points_review';
  if (!row.remoteCheckedAt || !row.pointsCheckedAt || row.pointsStatus !== 'synced' || Number(row.expectedPoints) !== Number(row.recordedPoints)) return 'points_pending';
  return 'matched';
}

export async function loadNazemReconciliationReport(connection, auth, query = {}) {
  const from = String(query.from || getBusinessDate());
  const to = String(query.to || from);
  if (![from, to].every((value) => /^\d{4}-\d{2}-\d{2}$/.test(value) && Number.isFinite(Date.parse(`${value}T00:00:00Z`)) && new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value)
    || from > to || (Date.parse(to) - Date.parse(from)) / 86400000 > 31) {
    const error = new Error('اختر فترة صحيحة لا تتجاوز 31 يومًا.'); error.statusCode = 422; throw error;
  }
  if (query.committeeId && query.committeeId !== 'all' && (!Number.isSafeInteger(Number(query.committeeId)) || Number(query.committeeId) <= 0)) {
    const error = new Error('معرّف الحلقة غير صحيح.'); error.statusCode = 422; throw error;
  }
  const params = [from, to];
  const scope = [];
  if (auth.role === 'supervisor') {
    scope.push('daily.teacher_id = ? AND EXISTS (SELECT 1 FROM supervisor_committees sc WHERE sc.supervisor_id = ? AND sc.committee_id = student.committee_id)');
    params.push(auth.id, auth.id);
  }
  if (query.committeeId && query.committeeId !== 'all') {
    scope.push('student.committee_id = ?'); params.push(Number(query.committeeId));
  }
  const [rows] = await connection.query(`SELECT daily.id AS dailyId, student.id AS studentId, student.name AS studentName,
    committee.name AS committeeName, teacher.name AS teacherName, DATE_FORMAT(daily.follow_up_date, '%Y-%m-%d') AS date,
    daily.task_type AS taskType, daily.track, daily.sync_status AS remoteStatus, daily.nazem_record_id AS remoteRecordId,
    daily.last_remote_checked_at AS remoteCheckedAt, work.checked_at AS pointsCheckedAt,
    work.status AS pointsStatus, work.expected_points AS expectedPoints, work.recorded_points AS recordedPoints,
    COALESCE(work.last_error, daily.last_error) AS error,
    JSON_UNQUOTE(JSON_EXTRACT(daily.local_snapshot, '$.importedFromNazem')) AS importedFromNazem,
    EXISTS (SELECT 1 FROM student_quran_recitation_attempts attempt JOIN student_quran_tasks task ON task.id = attempt.task_id
      WHERE attempt.is_official = 1 AND attempt.evaluator_id = daily.teacher_id AND task.plan_id = daily.ruwasi_plan_id AND task.student_id = daily.ruwasi_student_id
        AND task.task_date = daily.follow_up_date AND task.task_type = daily.task_type AND task.track = daily.track) AS localAccepted
    FROM nazem_daily_follow_up_links daily JOIN students student ON student.id = daily.ruwasi_student_id
    JOIN supervisors teacher ON teacher.id = daily.teacher_id LEFT JOIN committees committee ON committee.id = student.committee_id
    LEFT JOIN nazem_point_reconciliations work ON work.daily_follow_up_id = daily.id
    WHERE daily.follow_up_date BETWEEN ? AND ? ${scope.length ? `AND ${scope.join(' AND ')}` : ''}
    ORDER BY daily.follow_up_date DESC, student.name, daily.id LIMIT 2001`, params);
  const missingParams = [];
  const missingScope = [];
  if (auth.role === 'supervisor') { missingScope.push('teacher.id = ?'); missingParams.push(auth.id); }
  if (query.committeeId && query.committeeId !== 'all') { missingScope.push('student.committee_id = ?'); missingParams.push(Number(query.committeeId)); }
  const [unlinked] = await connection.query(`SELECT DISTINCT student.id AS studentId, student.name AS studentName,
    teacher.id AS teacherId, teacher.name AS teacherName, committee.name AS committeeName
    FROM students student JOIN committees committee ON committee.id = student.committee_id
    JOIN supervisor_committees sc ON sc.committee_id = student.committee_id
    JOIN supervisors teacher ON teacher.id = sc.supervisor_id
    JOIN nazem_accounts account ON account.teacher_id = teacher.id AND account.status = 'connected'
    WHERE NOT EXISTS (SELECT 1 FROM nazem_plan_links link WHERE link.ruwasi_student_id = student.id
      AND link.teacher_id = teacher.id AND link.sync_status NOT IN ('deleted','detached'))
    ${missingScope.length ? `AND ${missingScope.join(' AND ')}` : ''} ORDER BY student.name LIMIT 2001`, missingParams);
  const combined = [...rows.slice(0, 2000), ...unlinked.slice(0, 2000).map((row) => ({ ...row, date: to, error: 'لا توجد خطة ناظم مرتبطة؛ لا يمكن إثبات المطابقة.' }))];
  return { from, to, truncated: rows.length > 2000 || unlinked.length > 2000, rows: combined.map((row) => ({
    ...row, status: reconciliationStatus(row), difference: row.expectedPoints == null || row.recordedPoints == null
      ? null : Number(row.expectedPoints) - Number(row.recordedPoints),
  })) };
}

import { assertRecitationReplacementCoverage } from './recitationSessionTransaction.js';
import crypto from 'node:crypto';
import { isUuid, recitationCandidateWins, recitationSessionTypeForTask } from '../../shared/offline-recitation.js';
import { normalizeMasterySessionIdentity } from './masterySessionIdentity.js';
import { resolveReviewSessionIdentity } from './recitationReviewSessionIdentity.js';

const MAX_TRUSTED_ELAPSED_MS = 7 * 24 * 60 * 60 * 1000;

const sqlDateTime = (epochMs) => {
  const date = new Date(epochMs);
  if (!Number.isFinite(date.getTime())) return null;
  return date.toISOString().slice(0, 23).replace('T', ' ');
};

const derivedUuid = (value) => {
  const hex = crypto.createHash('sha256').update(String(value || crypto.randomUUID())).digest('hex').slice(0, 32);
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-4${hex.slice(13, 16)}-a${hex.slice(17, 20)}-${hex.slice(20)}`;
};

const normalizeServerSessionId = (sessionId, requestId) => (
  isUuid(sessionId) ? String(sessionId).toLowerCase() : derivedUuid(String(requestId || '').split(':')[0])
);

export async function registerRecitationDevice(connection, { req, deviceId, bootId, deviceEpochMs, monotonicMs }) {
  const normalizedDeviceId = isUuid(deviceId) ? String(deviceId).toLowerCase() : crypto.randomUUID();
  const normalizedBootId = isUuid(bootId) ? String(bootId).toLowerCase() : null;
  const safeDeviceEpoch = Number.isFinite(Number(deviceEpochMs)) ? Math.trunc(Number(deviceEpochMs)) : null;
  const safeMonotonic = Number.isFinite(Number(monotonicMs)) ? Number(monotonicMs) : null;
  const [[existingDevice]] = await connection.query(
    'SELECT actor_role AS actorRole, actor_id AS actorId FROM recitation_devices WHERE device_id = ? FOR UPDATE',
    [normalizedDeviceId],
  );
  if (existingDevice && (existingDevice.actorRole !== req.auth.role || Number(existingDevice.actorId) !== Number(req.auth.id))) {
    const error = new Error('معرّف الجهاز مرتبط بحساب آخر.');
    error.statusCode = 403;
    throw error;
  }
  await connection.query(
    `INSERT INTO recitation_devices
      (device_id, actor_role, actor_id, boot_id, anchor_server_at, anchor_device_epoch_ms, anchor_monotonic_ms, last_seen_at)
     VALUES (?, ?, ?, ?, NOW(3), ?, ?, NOW(3))
     ON DUPLICATE KEY UPDATE actor_role = VALUES(actor_role), actor_id = VALUES(actor_id),
       boot_id = VALUES(boot_id), anchor_server_at = NOW(3),
       anchor_device_epoch_ms = VALUES(anchor_device_epoch_ms), anchor_monotonic_ms = VALUES(anchor_monotonic_ms),
       revoked_at = NULL, last_seen_at = NOW(3)`,
    [normalizedDeviceId, req.auth.role, req.auth.id, normalizedBootId, safeDeviceEpoch, safeMonotonic],
  );
  const [[anchor]] = await connection.query(
    `SELECT device_id AS deviceId, boot_id AS bootId,
      UNIX_TIMESTAMP(anchor_server_at) * 1000 AS serverEpochMs,
      anchor_device_epoch_ms AS deviceEpochMs, anchor_monotonic_ms AS monotonicMs
     FROM recitation_devices WHERE device_id = ?`,
    [normalizedDeviceId],
  );
  return anchor;
}

export async function resolveTrustedDeviceEventTime(connection, {
  deviceId,
  bootId,
  eventMonotonicMs,
  committedAtLocal,
  actorRole = '',
  actorId = 0,
}) {
  const [[device]] = await connection.query(
    `SELECT actor_role AS actorRole, actor_id AS actorId, boot_id AS bootId,
      UNIX_TIMESTAMP(anchor_server_at) * 1000 AS serverEpochMs,
      anchor_monotonic_ms AS anchorMonotonicMs, revoked_at AS revokedAt
     FROM recitation_devices WHERE device_id = ? FOR UPDATE`,
    [deviceId],
  );
  const eventMonotonic = Number(eventMonotonicMs);
  const anchorMonotonic = Number(device?.anchorMonotonicMs);
  const elapsed = eventMonotonic - anchorMonotonic;
  const trusted = Boolean(
    device && !device.revokedAt && isUuid(bootId) && bootId === device.bootId
    && (!actorRole || (device.actorRole === actorRole && Number(device.actorId) === Number(actorId)))
    && Number.isFinite(elapsed) && elapsed >= 0 && elapsed <= MAX_TRUSTED_ELAPSED_MS
  );
  if (trusted) return { eventAt: sqlDateTime(Number(device.serverEpochMs) + elapsed), trusted: true };
  const localEpoch = Date.parse(String(committedAtLocal || ''));
  return { eventAt: Number.isFinite(localEpoch) ? sqlDateTime(localEpoch) : sqlDateTime(Date.now()), trusted: false };
}

export async function claimRecitationSession(connection, {
  req,
  task,
  sessionDate,
  requestId,
}) {
  const sessionId = normalizeServerSessionId(req.body.sessionId, requestId);
  const deviceId = isUuid(req.body.deviceId) ? String(req.body.deviceId).toLowerCase() : derivedUuid(`${req.auth.role}:${req.auth.id}`);
  await connection.query(
    `INSERT IGNORE INTO recitation_devices (device_id, actor_role, actor_id, last_seen_at)
     VALUES (?, ?, ?, NOW(3))`,
    [deviceId, req.auth.role, req.auth.id],
  );
  const [[deviceOwner]] = await connection.query(
    'SELECT actor_role AS actorRole, actor_id AS actorId FROM recitation_devices WHERE device_id = ? FOR UPDATE',
    [deviceId],
  );
  if (deviceOwner?.actorRole !== req.auth.role || Number(deviceOwner?.actorId) !== Number(req.auth.id)) {
    const error = new Error('معرّف الجهاز مرتبط بحساب آخر.');
    error.statusCode = 403;
    throw error;
  }
  const event = await resolveTrustedDeviceEventTime(connection, {
    deviceId,
    bootId: String(req.body.bootId || '').toLowerCase(),
    eventMonotonicMs: req.body.eventMonotonicMs,
    committedAtLocal: req.body.committedAtLocal,
    actorRole: req.auth.role,
    actorId: req.auth.id,
  });
  const submittedPlanVersion = Math.max(1, Number(req.body.planVersion || task.planVersion || 1));
  const currentPlanVersion = Math.max(1, Number(task.planVersion || submittedPlanVersion));
  let sessionType = recitationSessionTypeForTask(task);
  sessionType = await resolveReviewSessionIdentity(connection, task, sessionDate, sessionType);
  if (task.taskType === 'memorization') await normalizeMasterySessionIdentity(connection, task.studentId, sessionDate);
  await connection.query(
    `INSERT INTO student_quran_recitation_submissions
      (session_id, student_id, evaluator_id, evaluator_role, device_id, session_date, session_type, event_at,
       event_time_trusted, created_at_local, committed_at_local, plan_id, plan_version,
       current_plan_version, plan_snapshot_json, payload_json)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
     ON DUPLICATE KEY UPDATE payload_json = VALUES(payload_json), plan_snapshot_json = VALUES(plan_snapshot_json),
       updated_at = NOW(3)`,
    [
      sessionId, task.studentId, req.auth.id, req.auth.role, deviceId, sessionDate, sessionType, event.eventAt,
      event.trusted ? 1 : 0, String(req.body.createdAtLocal || '').slice(0, 40) || null,
      String(req.body.committedAtLocal || '').slice(0, 40) || null, task.planId, submittedPlanVersion,
      currentPlanVersion,
      JSON.stringify(req.body.planSnapshot || {}), JSON.stringify(req.body || {}),
    ],
  );
  let [[slot]] = await connection.query(
    `SELECT slot.session_id AS sessionId,
      DATE_FORMAT(slot.accepted_event_at, '%Y-%m-%d %H:%i:%s.%f') AS eventAt,
      slot.event_time_trusted AS eventTimeTrusted, submission.evaluator_id AS evaluatorId
     FROM student_quran_recitation_daily_slots slot
     JOIN student_quran_recitation_submissions submission ON submission.session_id = slot.session_id
     WHERE slot.student_id = ? AND slot.session_date = ? AND slot.session_type = ? FOR UPDATE`,
    [task.studentId, sessionDate, sessionType],
  );
  if (!slot) {
    try {
      await connection.query(
        `INSERT INTO student_quran_recitation_daily_slots
          (student_id, session_date, session_type, session_id, evaluator_id, accepted_event_at, event_time_trusted)
         VALUES (?, ?, ?, ?, ?, ?, ?)`,
        [task.studentId, sessionDate, sessionType, sessionId, req.auth.id, event.eventAt, event.trusted ? 1 : 0],
      );
      slot = { sessionId };
    } catch (error) {
      if (error.code !== 'ER_DUP_ENTRY') throw error;
      [[slot]] = await connection.query(
        `SELECT session_id AS sessionId,
          DATE_FORMAT(accepted_event_at, '%Y-%m-%d %H:%i:%s.%f') AS eventAt,
          event_time_trusted AS eventTimeTrusted
         FROM student_quran_recitation_daily_slots
         WHERE student_id = ? AND session_date = ? AND session_type = ? FOR UPDATE`,
        [task.studentId, sessionDate, sessionType],
      );
    }
  }
  if (slot.sessionId !== sessionId) {
    const wins = recitationCandidateWins(
      { sessionId, eventAt: event.eventAt, trusted: event.trusted },
      { sessionId: slot.sessionId, eventAt: String(slot.eventAt || '').slice(0, 23), trusted: Boolean(slot.eventTimeTrusted) },
    );
    if (!wins) {
      await connection.query(
        `UPDATE student_quran_recitation_submissions SET status = 'rejected_duplicate',
          rejection_code = 'DAILY_SESSION_EXISTS', rejection_message = ?, resolved_at = NOW(3)
         WHERE session_id = ?`,
        ['تم تسميع الطالب اليوم بالفعل.', sessionId],
      );
      await writeRecitationAudit(connection, {
        sessionId, req, deviceId, eventType: 'rejected_duplicate',
        details: { winningSessionId: slot.sessionId, sessionDate },
      });
      return { accepted: false, sessionId, winningSessionId: slot.sessionId };
    }
    await assertRecitationReplacementCoverage(connection, slot.sessionId,
      req.recitationTransaction ? req.recitationSessionTaskIds : [task.id]);
    if (req.recitationTransaction) req.recitationTransaction.superseded = true;
    await connection.query(
      `UPDATE student_quran_recitation_submissions SET status = 'rejected_duplicate',
        rejection_code = 'EARLIER_TRUSTED_SESSION', rejection_message = ?, resolved_at = NOW(3)
       WHERE session_id = ?`,
      ['وصل تسميع أسبق وفق مرجع الوقت الموثوق.', slot.sessionId],
    );
    await connection.query(
      `UPDATE student_quran_recitation_attempts SET is_official = 0
       WHERE session_id = ? OR request_id LIKE ?`,
      [slot.sessionId, `${slot.sessionId}:%`],
    );
    await connection.query(
      `UPDATE student_quran_recitation_session_parts SET status = 'rejected'
       WHERE session_id = ?`,
      [slot.sessionId],
    );
    await writeRecitationAudit(connection, {
      sessionId: slot.sessionId,
      req,
      deviceId,
      eventType: 'superseded_by_earlier_session',
      details: { winningSessionId: sessionId, sessionDate },
    });
    await connection.query(
      `UPDATE student_quran_recitation_daily_slots SET session_id = ?, evaluator_id = ?,
        accepted_event_at = ?, event_time_trusted = ?
       WHERE student_id = ? AND session_date = ? AND session_type = ?`,
      [sessionId, req.auth.id, event.eventAt, event.trusted ? 1 : 0, task.studentId, sessionDate, sessionType],
    );
  }
  await writeRecitationAudit(connection, {
    sessionId, req, deviceId, eventType: 'session_claimed',
    details: {
      sessionDate,
      eventAt: event.eventAt,
      eventTimeTrusted: event.trusted,
      submittedPlanVersion,
      currentPlanVersion,
      planVersionChanged: submittedPlanVersion !== currentPlanVersion,
    },
  });
  return {
    accepted: true,
    sessionId,
    deviceId,
    eventTimeTrusted: event.trusted,
    submittedPlanVersion,
    currentPlanVersion,
  };
}

export async function finalizeRecitationTask(connection, { claim, req, task, result }) {
  await connection.query(
    `INSERT INTO student_quran_recitation_session_parts
      (session_id, task_id, task_type, payload_json, result_json, status)
     VALUES (?, ?, ?, ?, ?, 'accepted')
     ON DUPLICATE KEY UPDATE payload_json = VALUES(payload_json), result_json = VALUES(result_json),
       status = 'accepted', updated_at = NOW(3)`,
    [claim.sessionId, task.id, task.taskType, JSON.stringify(req.body || {}), JSON.stringify(result || {})],
  );
  const expectedTaskIds = [...new Set((req.recitationSessionTaskIds?.length ? req.recitationSessionTaskIds : [task.id]).map(Number))];
  const [[parts]] = await connection.query(
    `SELECT COUNT(*) AS acceptedParts FROM student_quran_recitation_session_parts
     WHERE session_id = ? AND status = 'accepted' AND task_id IN (${expectedTaskIds.map(() => '?').join(',')})`,
    [claim.sessionId, ...expectedTaskIds],
  );
  const complete = Number(parts.acceptedParts) === expectedTaskIds.length;
  await connection.query(
    `UPDATE student_quran_recitation_submissions SET status = ?, rejection_code = NULL,
      rejection_message = NULL, resolved_at = IF(?, NOW(3), NULL) WHERE session_id = ?`,
    [complete ? 'accepted' : 'pending', complete ? 1 : 0, claim.sessionId],
  );
  await writeRecitationAudit(connection, {
    sessionId: claim.sessionId,
    req,
    deviceId: claim.deviceId,
    eventType: 'task_accepted',
    details: { taskId: task.id, taskType: task.taskType, result },
  });
}

async function writeRecitationAudit(connection, { sessionId, req, deviceId, eventType, details }) {
  await connection.query(
    `INSERT INTO student_quran_recitation_audit_log
      (session_id, event_type, actor_role, actor_id, device_id, details_json)
     VALUES (?, ?, ?, ?, ?, ?)`,
    [sessionId, eventType, req.auth?.role || 'system', req.auth?.id || null, deviceId || null, JSON.stringify(details || {})],
  );
}

import PDFDocument from 'pdfkit';

const colors = {
  primary: '#008aad',
  background: '#eff9fc',
  panel: '#ffffff',
  soft: '#f8fdff',
  border: '#b6e3ef',
  text: '#0f172a',
  muted: '#64748b',
};

const metricConfig = [
  ['attendance', 'الحضور', '#22c55e'],
  ['review', 'المراجعة', '#f59e0b'],
  ['link', 'الربط', '#06b6d4'],
  ['memorization', 'الحفظ', '#14b8a6'],
  ['mastery', 'الإتقان', '#8b5cf6'],
];

const leaderConfig = [
  ['review', 'الطلاب الأكثر مراجعة', '#f59e0b', 'faces', 'وجه'],
  ['link', 'الطلاب الأكثر ربطًا', '#06b6d4', 'faces', 'وجه'],
  ['mastery', 'الأكثر حفظًا في مسار الإتقان', '#8b5cf6', 'faces', 'وجه'],
  ['memorization', 'الأكثر حفظًا في مسار الحفظ', '#14b8a6', 'faces', 'وجه'],
  ['committees', 'الحلقات الأعلى إنجازًا', '#22c55e', 'completionRate', '%'],
];

const number = (value) => Number(value || 0).toLocaleString('ar-SA');
const preserveArabicSpacing = (value) => String(value ?? '').replace(/ (?=[\u0600-\u06ff])/g, '\u00a0');

const arcPath = (cx, cy, radius, percentage) => {
  const value = Math.max(0, Math.min(99.99, Number(percentage || 0)));
  if (!value) return null;
  const start = -90;
  const end = start + (value * 3.6);
  const point = (angle) => {
    const radians = (angle * Math.PI) / 180;
    return [cx + radius * Math.cos(radians), cy + radius * Math.sin(radians)];
  };
  const [sx, sy] = point(start);
  const [ex, ey] = point(end);
  return `M ${sx} ${sy} A ${radius} ${radius} 0 ${value > 50 ? 1 : 0} 1 ${ex} ${ey}`;
};

export async function buildOverviewPdf(report, { fontPair = null } = {}) {
  return await new Promise((resolve, reject) => {
    const chunks = [];
    const doc = new PDFDocument({ size: 'A4', layout: 'landscape', margin: 24, bufferPages: true });
    let regularFont = 'Helvetica';
    let boldFont = 'Helvetica-Bold';
    try {
      if (fontPair) {
        doc.registerFont('Arabic', fontPair.regular);
        doc.registerFont('ArabicBold', fontPair.bold);
        regularFont = 'Arabic';
        boldFont = 'ArabicBold';
      }
    } catch (error) {
      console.warn('Arabic PDF font registration failed; using the built-in fallback:', error.message);
    }
    doc.on('data', (chunk) => chunks.push(chunk));
    doc.on('end', () => resolve(Buffer.concat(chunks)));
    doc.on('error', reject);

    const pageWidth = doc.page.width;
    const pageHeight = doc.page.height;
    const margin = 24;
    const contentWidth = pageWidth - margin * 2;
    const write = (value, x, y, width, options = {}) => {
      doc.font(options.bold ? boldFont : regularFont)
        .fontSize(options.size || 9)
        .fillColor(options.color || colors.text)
        .text(preserveArabicSpacing(value), x, y, {
          width,
          align: options.align || 'right',
          lineBreak: options.lineBreak !== false,
          ellipsis: true,
          height: options.height,
        });
    };
    let pageStarted = false;
    const addPage = (sectionTitle = '') => {
      if (pageStarted) doc.addPage();
      pageStarted = true;
      doc.rect(0, 0, pageWidth, pageHeight).fill(colors.background);
      doc.roundedRect(margin, 18, contentWidth, 50, 12).fill(colors.panel).stroke(colors.border);
      write('الإحصائيات', pageWidth - margin - 220, 30, 190, { size: 17, bold: true, color: colors.primary });
      write(`${report.period?.from || '-'} - ${report.period?.to || '-'}`, margin + 24, 35, 260, { size: 9, bold: true, color: colors.muted, align: 'left', lineBreak: false });
      if (sectionTitle) write(sectionTitle, margin, 76, contentWidth, { size: 13, bold: true, color: colors.text });
    };

    addPage();
    const totals = report.totals || {};
    const quran = totals.quranFaces || {};
    const execution = totals.quranExecution || {};
    const summaries = [
      ['الطلاب', totals.studentsCount, '#38bdf8'],
      ['عدد الحلقات', totals.familiesCount, '#84cc16'],
      ['إجمالي أوجه الحفظ', quran.memorization, '#14b8a6'],
      ['إجمالي أوجه الإتقان', quran.mastery, '#8b5cf6'],
      ['إجمالي أوجه المراجعة', quran.review, '#f59e0b'],
      ['إجمالي أوجه الربط', quran.link, '#06b6d4'],
      ['التنفيذ الطبيعي', execution.normal?.faces, '#22c55e'],
      ['التعويض', execution.compensation?.faces, '#f97316'],
      ['الزيادة خارج الخطة', execution.extra?.faces, '#0ea5e9'],
    ];
    const summaryGap = 8;
    const summaryWidth = (contentWidth - summaryGap * 5) / 6;
    summaries.forEach(([label, value, color], index) => {
      const x = margin + (index % 6) * (summaryWidth + summaryGap);
      const y = 82 + Math.floor(index / 6) * 74;
      doc.roundedRect(x, y, summaryWidth, 68, 10).fill(colors.panel).stroke(colors.border);
      doc.circle(x + 18, y + 19, 7).fill(color);
      write(label, x + 8, y + 12, summaryWidth - 16, { size: 8.5, bold: true });
      write(number(value), x + 8, y + 37, summaryWidth - 16, { size: 18, bold: true, color });
    });

    const cardGap = 10;
    const cardWidth = (contentWidth - cardGap * 2) / 3;
    const cardHeight = 176;
    leaderConfig.forEach(([key, title, color, valueKey, suffix], index) => {
      const column = index % 3;
      const row = Math.floor(index / 3);
      const x = margin + column * (cardWidth + cardGap);
      const y = 236 + row * (cardHeight + cardGap);
      doc.roundedRect(x, y, cardWidth, cardHeight, 11).fill(colors.panel).stroke(colors.border);
      doc.circle(x + cardWidth - 20, y + 19, 8).fill(color);
      write(title, x + 12, y + 12, cardWidth - 42, { size: 10, bold: true });
      const rows = (report.quranLeaders?.[key] || []).slice(0, 5);
      if (!rows.length) {
        write('لا توجد بيانات في هذه الفترة.', x + 12, y + 76, cardWidth - 24, { size: 8, bold: true, color: colors.muted, align: 'center' });
      }
      rows.forEach((item, rowIndex) => {
        const rowY = y + 43 + rowIndex * 25;
        if (rowIndex) doc.moveTo(x + 12, rowY - 5).lineTo(x + cardWidth - 12, rowY - 5).strokeColor('#e0f2f8').lineWidth(0.6).stroke();
        doc.circle(x + cardWidth - 19, rowY + 6, 8).fill('#e0f2f8');
        write(number(rowIndex + 1), x + cardWidth - 25, rowY + 2, 12, { size: 7, bold: true, color: colors.primary, align: 'center', lineBreak: false });
        write(item.name || '-', x + 62, rowY, cardWidth - 92, { size: 8.5, bold: true, lineBreak: false });
        write(`${number(item[valueKey])}${suffix === '%' ? '%' : ` ${suffix}`}`, x + 10, rowY, 54, { size: 8, bold: true, color, align: 'left', lineBreak: false });
      });
    });

    const committees = report.committeeIndicators || [];
    if (committees.length) {
      addPage('مؤشرات الحلقات');
      let y = 100;
      const committeeWidth = (contentWidth - 12) / 2;
      committees.forEach((committee, index) => {
        if (index > 0 && index % 4 === 0) {
          addPage('مؤشرات الحلقات');
          y = 100;
        }
        const column = index % 2;
        const row = Math.floor((index % 4) / 2);
        const x = margin + column * (committeeWidth + 12);
        const cardY = y + row * 210;
        doc.roundedRect(x, cardY, committeeWidth, 194, 12).fill(colors.panel).stroke(colors.border);
        write(committee.name, x + 14, cardY + 12, committeeWidth - 90, { size: 12, bold: true });
        write(`${number(committee.studentsCount)} طالب`, x + 14, cardY + 32, committeeWidth - 28, { size: 8, bold: true, color: colors.muted });
        write(`${number(committee.overallPercentage)}%`, x + committeeWidth - 70, cardY + 15, 52, { size: 11, bold: true, color: colors.primary, align: 'center' });
        const gaugeWidth = (committeeWidth - 24) / 5;
        metricConfig.forEach(([metricKey, label, color], metricIndex) => {
          const metric = committee.metrics?.[metricKey] || {};
          const cx = x + 12 + gaugeWidth * metricIndex + gaugeWidth / 2;
          const cy = cardY + 92;
          doc.circle(cx, cy, 25).lineWidth(6).strokeColor('#cbd5e1').stroke();
          const path = arcPath(cx, cy, 25, metric.percentage);
          if (path) doc.path(path).lineWidth(6).lineCap('round').strokeColor(color).stroke();
          write(`${number(metric.percentage)}%`, cx - 22, cy - 5, 44, { size: 8, bold: true, align: 'center', lineBreak: false });
          write(label, cx - gaugeWidth / 2 + 2, cardY + 127, gaugeWidth - 4, { size: 7.5, bold: true, align: 'center', lineBreak: false });
          write(`${Number(metric.done || 0)} / ${Number(metric.total || 0)}`, cx - gaugeWidth / 2 + 2, cardY + 147, gaugeWidth - 4, { size: 7, bold: true, color: colors.muted, align: 'center', lineBreak: false });
        });
      });
    }

    const range = doc.bufferedPageRange();
    for (let pageIndex = 0; pageIndex < range.count; pageIndex += 1) {
      doc.switchToPage(pageIndex);
      const center = pageWidth / 2;
      write(String(pageIndex + 1), center - 24, pageHeight - 40, 16, { size: 7.5, bold: true, color: colors.muted, align: 'center', lineBreak: false });
      write('/', center - 8, pageHeight - 40, 16, { size: 7.5, bold: true, color: colors.muted, align: 'center', lineBreak: false });
      write(String(range.count), center + 8, pageHeight - 40, 16, { size: 7.5, bold: true, color: colors.muted, align: 'center', lineBreak: false });
    }
    doc.end();
  });
}

// Review rotates through the available memorized pages, independently of the new plan's bounds.
export function reviewStartFromHistory(rows, fallbackPage) {
  let cursor = Number(fallbackPage || 1);
  const days = new Map();
  for (const row of rows) {
    const date = String(row.taskDate || '');
    if (!days.has(date)) days.set(date, []);
    days.get(date).push(row);
  }
  let initialized = false;
  for (const [, day] of [...days.entries()].sort(([a], [b]) => a.localeCompare(b))) {
    const touched = day.some((row) => row.teacherCompleted != null || row.executedAt || row.studentStatus === 'done');
    // Generated future/pending rows are not evidence of progress.
    if (initialized && !touched) continue;
    initialized = true;
    const ascending = [...day].sort((a, b) => Number(a.fromPage) - Number(b.fromPage));
    let start = ascending.findIndex((row) => Number(row.toPage) >= cursor);
    if (start < 0) start = 0;
    const ordered = [...ascending.slice(start), ...ascending.slice(0, start)];
    const incomplete = ordered.find((row) => Number(row.teacherCompleted) !== 1
      && (row.teacherCompleted != null || row.studentStatus !== 'done' || row.executionState === 'partial'));
    if (incomplete) {
      cursor = Number(incomplete.teacherCompleted == null && incomplete.executionState === 'partial'
        ? incomplete.actualToPage || incomplete.fromPage : incomplete.fromPage);
      if (incomplete.teacherCompleted == null && incomplete.executionState === 'partial' && incomplete.actualCompletesPage) cursor += 1;
    } else {
      const last = ordered.at(-1);
      cursor = Number(last.toPage) + 1;
    }
  }
  return cursor;
}

export async function getReviewStartForDate(connection, plan, date) {
  const [rows] = await connection.query(
    `SELECT DATE_FORMAT(task_date, '%Y-%m-%d') AS taskDate,
      from_page AS fromPage, to_page AS toPage, actual_to_page AS actualToPage,
      actual_to_surah AS actualToSurah, actual_to_ayah AS actualToAyah,
      teacher_completed AS teacherCompleted, student_status AS studentStatus,
      execution_state AS executionState, executed_at AS executedAt
     FROM student_quran_tasks
     WHERE plan_id = ? AND task_type = 'review' AND task_date < ?
     ORDER BY task_date, from_page, id`,
    [plan.id, date],
  );
  const boundaries = new Map();
  for (const row of rows) {
    if (row.executionState !== 'partial' || !row.actualToPage || row.teacherCompleted != null) continue;
    if (!boundaries.has(Number(row.actualToPage))) {
      const [[boundary]] = await connection.query(
        `SELECT surah_number AS surah, ayah_number AS ayah FROM quran_ayah_pages
         WHERE page_number = ? ORDER BY surah_number DESC, ayah_number DESC LIMIT 1`, [row.actualToPage],
      );
      boundaries.set(Number(row.actualToPage), boundary);
    }
    const boundary = boundaries.get(Number(row.actualToPage));
    row.actualCompletesPage = Boolean(boundary && Number(row.actualToSurah) === Number(boundary.surah)
      && Number(row.actualToAyah) === Number(boundary.ayah));
  }
  return reviewStartFromHistory(rows, plan.startPage);
}

export function reviewPagesMatch(rows, desiredPages) {
  const current = new Set(rows.flatMap((row) => Array.from(
    { length: Number(row.toPage) - Number(row.fromPage) + 1 }, (_, index) => Number(row.fromPage) + index,
  )));
  const desired = new Set(desiredPages);
  return current.size === desired.size && [...current].every((page) => desired.has(page));
}

import { calculateStudentExecutionPoints } from './quranPoints.js';
const number = (value) => Number.isFinite(Number(value)) ? Number(value) : 0;
const labels = { attendance: 'الحضور', quran_evaluation: 'التسميع', quran_execution: 'التنفيذ' };

export function buildStudentPlanPoints({ total, rows, transactions, attendance, settings, today }) {
  const days = new Map();
  const dayFor = (date) => {
    if (!days.has(date)) days.set(date, { date, earned: 0, maximum: 0, pending: true, details: [], groups: new Map() });
    return days.get(date);
  };
  for (const row of rows) {
    if (row.taskDate > today) continue;
    const day = dayFor(row.taskDate);
    const key = `${row.taskType}:${row.track}`;
    if (!day.groups.has(key)) day.groups.set(key, []);
    day.groups.get(key).push(row);
    if (row.evaluatedAt) day.pending = false;
  }
  for (const record of attendance) {
    if (record.date > today) continue;
    const day = dayFor(record.date);
    day.pending = false;
  }
  for (const row of transactions) {
    if (row.date > today) continue;
    const day = dayFor(row.date);
    const value = row.type === 'deduction' ? -number(row.points) : number(row.points);
    day.earned += value;
    day.pending = false;
    day.details.push({ label: row.reason || labels[row.source] || 'أخرى', earned: value });
    if (!['attendance', 'quran_evaluation', 'quran_execution'].includes(row.source) && value > 0) day.maximum += value;
  }
  for (const day of days.values()) {
    day.maximum += Math.max(0, number(settings.attendancePoints));
    for (const group of day.groups.values()) {
      day.maximum += group.reduce((sum, task) => sum + number(task.pointsMaximum), 0) / group.length;
      if (settings.hasStudentQuranExecution && group[0].taskType === 'memorization') {
        const mastery = group[0].track === 'mastery';
        const repeats = number(mastery ? settings.masteryRepeatCount : settings.memorizationRepeatCount);
        const listening = number(mastery ? settings.masteryListeningCount : settings.memorizationListeningCount);
        day.maximum += calculateStudentExecutionPoints({ taskType: 'memorization', track: group[0].track,
          completedRepeatCount: repeats, expectedRepeatCount: repeats,
          completedListeningCount: listening, expectedListeningCount: listening, settings }).total;
      }
    }
    day.maximum = Math.round(day.maximum);
    delete day.groups;
  }
  return { total: number(total), days: [...days.values()] };
}

// Use the same transaction as the point movement: neither may outlive a rollback.
export async function notifyTeacherPointAdjustment(connection, {
  transactionId, studentId, type, points, reason, actor,
}) {
  if (!(Number(transactionId) > 0) || !(Number(points) > 0)) return null;
  const increase = type === 'increase';
  const [notification] = await connection.query(
    `INSERT INTO app_notifications
      (title, body, dedupe_key, recipient_type, created_by_role, created_by_id, created_by_name)
     VALUES (?, ?, ?, 'specific', 'supervisor', ?, ?)
     ON DUPLICATE KEY UPDATE id = LAST_INSERT_ID(id)`,
    [increase ? 'إضافة من المعلم' : 'خصم من المعلم',
      `${increase ? 'أضاف' : 'خصم'} المعلم ${actor.name || 'المعلم'} ${points} كم. السبب: ${reason}`,
      `teacher-points:${transactionId}`, actor.id, actor.name || 'المعلم'],
  );
  const notificationId = Number(notification.insertId);
  await connection.query(
    `INSERT IGNORE INTO app_notification_recipients (notification_id, user_role, user_id)
     VALUES (?, 'student', ?)`, [notificationId, studentId],
  );
  await connection.query(
    `INSERT IGNORE INTO notification_push_deliveries (notification_id, device_id, user_role, user_id)
     SELECT r.notification_id, d.id, r.user_role, r.user_id FROM app_notification_recipients r
     JOIN notification_devices d ON d.user_role = r.user_role AND d.user_id = r.user_id
     WHERE r.notification_id = ?`, [notificationId],
  );
  return notificationId;
}

export function formatClockTime(value) {
  if (!value) return '-';
  const match = /(?:^|[T ])(\d{1,2}):(\d{2})(?::\d{2})?/.exec(String(value));
  if (!match) return String(value);
  const hour = Number(match[1]);
  const minute = Number(match[2]);
  if (hour > 23 || minute > 59) return '-';
  return `${hour % 12 || 12}${minute ? `:${match[2]}` : ''}${hour < 12 ? 'ص' : 'م'}`;
}

const compareForwardPosition = (first, second) => {
  if (Number(first.page) !== Number(second.page)) return Number(first.page) - Number(second.page);
  if (Number(first.surah) !== Number(second.surah)) return Number(first.surah) - Number(second.surah);
  return Number(first.ayah) - Number(second.ayah);
};

export async function buildForwardQuranFaceRange({
  start,
  endLimit,
  targetFaces,
  getPageEnd,
  getNextPosition,
  getHalfPageEnd,
  getFractionalPageEnd,
}) {
  const requestedFaces = Math.max(0.25, Math.round(Math.max(0, Number(targetFaces || 1)) * 4) / 4);
  const wholeFaces = Math.floor(requestedFaces);
  const fractionalFace = Number((requestedFaces - wholeFaces).toFixed(2));
  let end = start;
  let cursor = start;
  const segments = [];

  for (let face = 0; face < wholeFaces && cursor; face += 1) {
    const segmentEnd = await getPageEnd(cursor);
    segments.push({ start: cursor, end: segmentEnd, faces: 1 });
    end = segmentEnd;
    if (compareForwardPosition(end, endLimit) >= 0) break;
    cursor = await getNextPosition(end);
  }

  if (fractionalFace > 0 && compareForwardPosition(end, endLimit) < 0) {
    const fractionalStart = wholeFaces > 0 ? cursor : start;
    if (fractionalStart) {
      const fractionalEnd = getFractionalPageEnd
        ? await getFractionalPageEnd(fractionalStart, fractionalFace)
        : await getHalfPageEnd(fractionalStart);
      if (!fractionalEnd) return { start, end, faces: requestedFaces, segments };
      end = compareForwardPosition(fractionalEnd, endLimit) > 0 ? endLimit : fractionalEnd;
      segments.push({ start: fractionalStart, end, faces: fractionalFace });
    }
  }

  return { start, end, faces: requestedFaces, segments };
}

import React, { useCallback, useEffect, useRef, useState } from 'react';
import { Camera, CameraOff, LogOut, Mic, MicOff, MonitorPlay, MonitorUp, PhoneCall, PhoneOff, ScreenShareOff, User, X } from 'lucide-react';
import { Room, RoomEvent, Track } from 'livekit-client';
import { Button } from '@/components/ui/button';
import IconActionButton from '@/components/ui/icon-action-button';
import { Card, CardContent, CardHeader } from '@/components/ui/card';
import DashboardLoader from '@/components/dashboard/DashboardLoader';
import { useToast } from '@/components/ui/use-toast';
import { studentsApi } from '@/services/studentsApi';

const getScreenPublication = (participant) => (
  Array.from(participant?.trackPublications?.values?.() || []).find(
    (publication) => publication.source === Track.Source.ScreenShare && !publication.isMuted,
  ) || null
);

const getCameraPublication = (participant) => (
  Array.from(participant?.trackPublications?.values?.() || []).find(
    (publication) => publication.source === Track.Source.Camera && !publication.isMuted,
  ) || null
);

const CameraVideo = ({ publication, isLocal }) => {
  const containerRef = useRef(null);

  useEffect(() => {
    const track = publication?.track;
    const container = containerRef.current;
    if (!track || !container) return undefined;
    const element = track.attach();
    element.autoplay = true;
    element.playsInline = true;
    element.muted = Boolean(isLocal);
    container.replaceChildren(element);
    return () => {
      track.detach(element);
      element.remove();
    };
  }, [isLocal, publication?.track]);

  return (
    <div
      ref={containerRef}
      className={`aspect-video w-full overflow-hidden bg-black [&>video]:h-full [&>video]:w-full [&>video]:object-cover ${isLocal ? '[&>video]:-scale-x-100' : ''}`}
    />
  );
};

const canCaptureScreen = () => (
  typeof navigator !== 'undefined'
  && typeof navigator.mediaDevices?.getDisplayMedia === 'function'
);

const isUnsupportedScreenShareError = (error) => (
  /getdisplaymedia.*not.*support|notsupported|not.?supported/i
    .test(`${error?.name || ''} ${error?.message || ''}`)
);

const getScreenShareErrorDescription = (error) => {
  const errorText = `${error?.name || ''} ${error?.message || ''}`;
  if (isUnsupportedScreenShareError(error)) {
    return 'متصفح الجوال لا يدعم بث الشاشة. يمكنك مشاهدة بث الآخرين من الجوال، ولإنشاء بث شاشة استخدم الكمبيوتر.';
  }
  if (/notallowed|permission|denied/i.test(errorText)) {
    return 'لم يتم السماح بمشاركة الشاشة. اسمح بالمشاركة من نافذة المتصفح ثم حاول مرة أخرى.';
  }
  if (/abort|cancel/i.test(errorText)) return 'تم إلغاء مشاركة الشاشة.';
  return 'تعذر بدء بث الشاشة. حاول مرة أخرى أو استخدم متصفحًا آخر.';
};

const AudioCallRoom = ({ roomInfo, isOwner, minimized = false, onRestore, onLeave, onClosed }) => {
  const { toast } = useToast();
  const livekitRoomRef = useRef(null);
  const audioContainerRef = useRef(null);
  const screenContainerRef = useRef(null);
  const activeScreenIdentityRef = useRef('');
  const [participants, setParticipants] = useState([]);
  const [isConnecting, setIsConnecting] = useState(true);
  const [isMuted, setIsMuted] = useState(false);
  const [isCameraEnabled, setIsCameraEnabled] = useState(false);
  const [isTogglingCamera, setIsTogglingCamera] = useState(false);
  const [isSharingScreen, setIsSharingScreen] = useState(false);
  const [activeScreenShare, setActiveScreenShare] = useState(null);
  const [isClosing, setIsClosing] = useState(false);

  const closeScreenShareView = useCallback(() => {
    activeScreenIdentityRef.current = '';
    screenContainerRef.current?.replaceChildren();
    setActiveScreenShare(null);
  }, []);

  useEffect(() => {
    if (minimized) closeScreenShareView();
  }, [closeScreenShareView, minimized]);

  const syncParticipants = useCallback(() => {
    const room = livekitRoomRef.current;
    if (!room) return;
    const toParticipant = (participant, isLocal) => {
      const cameraPublication = getCameraPublication(participant);
      return {
        identity: participant.identity,
        name: participant.name || (isLocal ? 'أنت' : 'مشارك'),
        isLocal,
        isMuted: !participant.isMicrophoneEnabled,
        isSpeaking: participant.isSpeaking,
        hasScreenShare: Boolean(getScreenPublication(participant)),
        cameraPublication,
      };
    };
    setParticipants([toParticipant(room.localParticipant, true), ...Array.from(room.remoteParticipants.values()).map((participant) => toParticipant(participant, false))]);
    setIsMuted(!room.localParticipant.isMicrophoneEnabled);
    setIsCameraEnabled(room.localParticipant.isCameraEnabled);
    setIsSharingScreen(room.localParticipant.isScreenShareEnabled);
  }, []);

  const showScreenShare = useCallback((identity) => {
    const room = livekitRoomRef.current;
    if (!room) return;
    const participant = room.localParticipant.identity === identity
      ? room.localParticipant
      : room.remoteParticipants.get(identity);
    const publication = getScreenPublication(participant);
    if (!participant || !publication) {
      toast({ title: 'البث غير متاح الآن', variant: 'destructive' });
      return;
    }

    activeScreenIdentityRef.current = identity;
    setActiveScreenShare({
      identity,
      name: participant.name || (participant === room.localParticipant ? 'أنت' : 'مشارك'),
    });
    screenContainerRef.current?.replaceChildren();
    if (publication.track && screenContainerRef.current) {
      screenContainerRef.current.appendChild(publication.track.attach());
    } else if (typeof publication.setSubscribed === 'function') {
      publication.setSubscribed(true);
    }
  }, [toast]);

  useEffect(() => {
    let mounted = true;
    const room = new Room({ adaptiveStream: true, dynacast: true });
    const audioContainer = audioContainerRef.current;
    const screenContainer = screenContainerRef.current;
    livekitRoomRef.current = room;
    const attachTrack = (track, publication, participant) => {
      if (track.kind === Track.Kind.Audio && audioContainer) {
        const element = track.attach();
        element.autoplay = true;
        audioContainer.appendChild(element);
      }
      if (
        publication?.source === Track.Source.ScreenShare
        && activeScreenIdentityRef.current === participant?.identity
        && screenContainer
      ) {
        screenContainer.replaceChildren(track.attach());
      }
      syncParticipants();
    };
    const detachTrack = (track, publication, participant) => {
      track.detach().forEach((element) => element.remove());
      if (
        publication?.source === Track.Source.ScreenShare
        && activeScreenIdentityRef.current === participant?.identity
      ) closeScreenShareView();
      syncParticipants();
    };
    const participantDisconnected = (participant) => {
      if (activeScreenIdentityRef.current === participant.identity) closeScreenShareView();
      syncParticipants();
    };
    const publicationChanged = (publication, participant) => {
      if (
        publication?.source === Track.Source.ScreenShare
        && publication.isMuted
        && activeScreenIdentityRef.current === participant?.identity
      ) closeScreenShareView();
      syncParticipants();
    };
    const screenPublicationEnded = (publication, participant) => {
      if (
        publication?.source === Track.Source.ScreenShare
        && activeScreenIdentityRef.current === participant?.identity
      ) closeScreenShareView();
      syncParticipants();
    };
    const localPublicationEnded = (publication) => {
      if (
        publication?.source === Track.Source.ScreenShare
        && activeScreenIdentityRef.current === room.localParticipant.identity
      ) closeScreenShareView();
      syncParticipants();
    };
    room
      .on(RoomEvent.ParticipantConnected, syncParticipants)
      .on(RoomEvent.ParticipantDisconnected, participantDisconnected)
      .on(RoomEvent.ActiveSpeakersChanged, syncParticipants)
      .on(RoomEvent.TrackMuted, publicationChanged)
      .on(RoomEvent.TrackUnmuted, publicationChanged)
      .on(RoomEvent.TrackPublished, publicationChanged)
      .on(RoomEvent.TrackUnpublished, screenPublicationEnded)
      .on(RoomEvent.LocalTrackPublished, syncParticipants)
      .on(RoomEvent.LocalTrackUnpublished, localPublicationEnded)
      .on(RoomEvent.TrackSubscribed, attachTrack)
      .on(RoomEvent.TrackUnsubscribed, detachTrack);

    const connect = async () => {
      try {
        const credentials = await studentsApi.getCallToken(roomInfo.id);
        await room.connect(credentials.serverUrl, credentials.token, { autoSubscribe: true });
        if (mounted) syncParticipants();
      } catch (error) {
        console.error('LiveKit room connection failed', error);
        toast({ title: 'تعذر دخول المكالمة', description: 'تعذر الاتصال بالغرفة الصوتية. تحقق من اتصال الإنترنت ثم حاول مرة أخرى.', variant: 'destructive' });
        onLeave();
      } finally {
        if (mounted) setIsConnecting(false);
      }
    };
    connect();
    return () => {
      mounted = false;
      room.disconnect();
      livekitRoomRef.current = null;
      activeScreenIdentityRef.current = '';
      audioContainer?.replaceChildren();
      screenContainer?.replaceChildren();
    };
  }, [closeScreenShareView, onLeave, roomInfo.id, syncParticipants, toast]);

  const toggleMicrophone = async () => {
    try {
      await livekitRoomRef.current?.localParticipant.setMicrophoneEnabled(isMuted);
      syncParticipants();
    } catch (error) {
      const permissionDenied = /permission|denied|notallowed/i.test(String(error?.name || error?.message || ''));
      toast({
        title: 'تعذر فتح الميكروفون',
        description: permissionDenied ? 'اسمح للمتصفح باستخدام الميكروفون من إعدادات الموقع ثم حاول مرة أخرى.' : error.message,
        variant: 'destructive',
      });
    }
  };

  const toggleCamera = async () => {
    setIsTogglingCamera(true);
    try {
      const localParticipant = livekitRoomRef.current?.localParticipant;
      if (!localParticipant) return;
      await localParticipant.setCameraEnabled(
        !isCameraEnabled,
        !isCameraEnabled ? { facingMode: 'user' } : undefined,
      );
      syncParticipants();
    } catch (error) {
      const permissionDenied = /permission|denied|notallowed/i.test(`${error?.name || ''} ${error?.message || ''}`);
      const unavailable = /notfound|devicesnotfound|overconstrained/i.test(`${error?.name || ''} ${error?.message || ''}`);
      const _resolveDescription = () => {
        if (permissionDenied) {
          return 'اسمح للمتصفح باستخدام الكاميرا من إعدادات الموقع ثم حاول مرة أخرى.';
        }
        if (unavailable) {
          return 'لم يتم العثور على كاميرا متاحة في هذا الجهاز.';
        }
        return error.message || 'تعذر تشغيل الكاميرا. حاول مرة أخرى.';
      };
      toast({
        title: 'تعذر فتح الكاميرا',
        description: _resolveDescription(),
        variant: 'destructive',
      });
    } finally {
      setIsTogglingCamera(false);
    }
  };

  const toggleScreenShare = async () => {
    if (!canCaptureScreen()) {
      toast({
        title: 'بث الشاشة غير متاح على هذا الجوال',
        description: getScreenShareErrorDescription({ name: 'GetDisplayMediaNotSupported' }),
      });
      return;
    }
    try {
      const localParticipant = livekitRoomRef.current?.localParticipant;
      if (!localParticipant) return;
      const nextEnabled = !isSharingScreen;
      await localParticipant.setScreenShareEnabled(nextEnabled, { audio: false });
      syncParticipants();
      if (!nextEnabled && activeScreenIdentityRef.current === localParticipant.identity) closeScreenShareView();
    } catch (error) {
      toast({
        title: isUnsupportedScreenShareError(error) ? 'بث الشاشة غير متاح على هذا الجوال' : 'تعذر مشاركة الشاشة',
        description: getScreenShareErrorDescription(error),
        variant: isUnsupportedScreenShareError(error) ? undefined : 'destructive',
      });
    }
  };

  const leave = async () => { livekitRoomRef.current?.disconnect(); await studentsApi.leaveCallRoom(roomInfo.id).catch(() => {}); onLeave(); };
  const closeRoom = async () => {
    setIsClosing(true);
    try { await studentsApi.closeCallRoom(roomInfo.id); livekitRoomRef.current?.disconnect(); onClosed(); }
    catch (error) { toast({ title: 'تعذر إغلاق الغرفة', description: error.message, variant: 'destructive' }); }
    finally { setIsClosing(false); }
  };

  if (isConnecting) {
    if (minimized) {
      return (
        <button type="button" onClick={onRestore} className="fixed bottom-3 left-3 z-[60] flex w-[min(88vw,320px)] items-center gap-3 rounded-2xl border border-primary/30 bg-card/95 p-3 text-right shadow-2xl shadow-primary/20 backdrop-blur-xl sm:bottom-5 sm:left-5" dir="rtl">
          <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-primary/15 text-primary"><PhoneCall className="h-5 w-5 animate-pulse" /></span>
          <span className="min-w-0"><span className="block truncate font-black text-foreground">{roomInfo.name}</span><span className="block text-xs font-bold text-muted-foreground">جاري الاتصال بالمكالمة...</span></span>
        </button>
      );
    }
    return <DashboardLoader className="min-h-[420px]" />;
  }

  if (minimized) {
    return (
      <>
        <button
          type="button"
          onClick={onRestore}
          className="fixed bottom-3 left-3 z-[60] flex w-[min(88vw,340px)] items-center gap-3 rounded-2xl border border-primary/35 bg-card/95 p-3 text-right shadow-2xl shadow-primary/20 backdrop-blur-xl transition hover:border-primary/60 hover:bg-card sm:bottom-5 sm:left-5"
          aria-label={`العودة إلى المكالمة ${roomInfo.name}`}
          dir="rtl"
        >
          <span className="relative flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-primary/15 text-primary">
            <span className="absolute inset-0 animate-ping rounded-full bg-primary/10" />
            <PhoneCall className="relative h-5 w-5" />
          </span>
          <span className="min-w-0 flex-1">
            <span className="block truncate font-black text-foreground">{roomInfo.name}</span>
            <span className="mt-0.5 block text-xs font-bold text-primary">المكالمة مستمرة · {participants.length} مشارك</span>
          </span>
          <span className="flex shrink-0 items-center gap-1.5 text-muted-foreground">
            {isMuted ? <MicOff className="h-4 w-4 text-destructive" /> : <Mic className="h-4 w-4 text-primary" />}
            {isCameraEnabled ? <Camera className="h-4 w-4 text-primary" /> : <CameraOff className="h-4 w-4" />}
          </span>
        </button>
        <div ref={audioContainerRef} className="hidden" aria-hidden="true" />
      </>
    );
  }

  return (
    <>
      <Card className="border-primary/30 bg-card neon-glow" dir="rtl">
      <CardHeader className="gap-4 border-b border-primary/20">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <h2 className="text-xl font-black text-foreground sm:text-2xl">{roomInfo.name}</h2>
          <div className="flex flex-wrap items-center gap-2">
            <IconActionButton label={isMuted ? 'فتح الميكروفون' : 'كتم الميكروفون'} variant={isMuted ? 'destructive' : 'outline'} onClick={toggleMicrophone}>
              {isMuted ? <MicOff className="h-4 w-4" /> : <Mic className="h-4 w-4" />}
            </IconActionButton>
            <IconActionButton label={isCameraEnabled ? 'إيقاف الكاميرا' : 'فتح الكاميرا'} variant={isCameraEnabled ? 'default' : 'outline'} onClick={toggleCamera} disabled={isTogglingCamera}>
              {isCameraEnabled ? <Camera className="h-4 w-4" /> : <CameraOff className="h-4 w-4" />}
            </IconActionButton>
            <IconActionButton label={isSharingScreen ? 'إيقاف مشاركة الشاشة' : 'مشاركة الشاشة'} variant={isSharingScreen ? 'default' : 'outline'} onClick={toggleScreenShare}>
              {isSharingScreen ? <ScreenShareOff className="h-4 w-4" /> : <MonitorUp className="h-4 w-4" />}
            </IconActionButton>
            <IconActionButton label="الخروج من المكالمة" variant="outline" onClick={leave}>
              <LogOut className="h-4 w-4" />
            </IconActionButton>
            {isOwner && <Button variant="destructive" onClick={closeRoom} disabled={isClosing} className="gap-2"><PhoneOff className="h-4 w-4" /> إغلاق الغرفة</Button>}
          </div>
        </div>
      </CardHeader>
      <CardContent className="space-y-5 pt-4 sm:pt-6">
        <div className={activeScreenShare ? 'overflow-hidden rounded-lg border border-primary/20 bg-black' : 'hidden'}>
          <div className="flex items-center justify-between bg-background/95 px-3 py-2 text-sm font-black text-foreground">
            <span className="truncate">بث {activeScreenShare?.name}</span>
            <IconActionButton label="إغلاق عرض البث" variant="ghost" onClick={closeScreenShareView} className="h-11 w-11 shrink-0">
              <X className="h-4 w-4" />
            </IconActionButton>
          </div>
