                onClick={submit}
              >
                {saving ? 'جاري الاستيراد...' : `استيراد الطلاب ذوي الخطط (${candidatesWithPlans.length})`}
              </Button>
            </DialogFooter>
          </div>;
  };
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="max-h-[92dvh] max-w-5xl [font-family:var(--font-ui)]"
        dir="rtl"
