import { useEffect } from 'react';
import { App as CapacitorApp } from '@capacitor/app';
import { Network } from '@capacitor/network';
import { Capacitor } from '@capacitor/core';
import { BackgroundRunner } from '@capacitor/background-runner';
import {
  prepareOfflineRecitationWorkspace,
  syncOfflineRecitations,
} from '@/services/offlineRecitationService';
import { syncOfflineStudent } from '@/services/offlineStudentService';
import { prefetchOfflineManagementWorkspace } from '@/services/offlineOperationsService';
import { getSiteConfig } from '@/site/siteConfigs';
import { serverConnectivityChangeEvent } from '@/hooks/useOnlineStatus';
import { getAuthSessionVersion, hasAuthSession } from '@/lib/authSession';

const getSupervisorId = () => {
  const role = localStorage.getItem('wajeh_role');
  if (!['supervisor', 'reciter', 'admin'].includes(role)) return 0;
  return Number(localStorage.getItem('wajeh_supervisor_id') || 0);
};

const getStudentId = () => (
  localStorage.getItem('wajeh_role') === 'student'
    ? Number(localStorage.getItem('wajeh_student_id') || 0)
    : 0
);

const getManagementAccount = () => {
  const role = localStorage.getItem('wajeh_role') || '';
  if (!['manager', 'admin'].includes(role)) return { id: 0, role: '' };
  return { id: Number(localStorage.getItem('wajeh_account_id') || 0), role };
};

const OfflineRecitationSyncBridge = () => {
  useEffect(() => {
    let active = true;
    const run = async ({ bootstrap = false, force = false } = {}) => {
      const sessionVersion = getAuthSessionVersion();
      const isCurrent = () => active && hasAuthSession() && sessionVersion === getAuthSessionVersion();
      if (!isCurrent()) return;
      const supervisorId = getSupervisorId();
      const studentId = getStudentId();
      const management = getManagementAccount();
      if ((!supervisorId && !studentId && !management.id) || !active || navigator.onLine === false) return;
      if (supervisorId) {
        await syncOfflineRecitations(supervisorId, { force }).catch(() => undefined);
        if (!isCurrent()) return;
        if (bootstrap) await prepareOfflineRecitationWorkspace(supervisorId, { automatic: true }).catch(() => undefined);
        if (!isCurrent()) return;
        if (bootstrap) await syncOfflineRecitations(supervisorId, { force }).catch(() => undefined);
      }
      if (!isCurrent()) return;
      if (studentId && (bootstrap || force || document.visibilityState === 'visible')) {
        await syncOfflineStudent(studentId, { force }).catch(() => undefined);
      }
      if (!isCurrent()) return;
      if (management.id && bootstrap) {
        await prefetchOfflineManagementWorkspace(management.id, management.role, { automatic: true }).catch(() => undefined);
      }
    };
    const consumeNativeWakeup = async () => {
      if (!Capacitor.isNativePlatform()) return;
      await BackgroundRunner.dispatchEvent({
        label: getSiteConfig().backgroundRunnerLabel,
        event: 'consumeMadarijOfflineRecitationWakeup',
        details: {},
      }).catch(() => undefined);
    };
    const onOnline = () => void run({ bootstrap: true });
    const onServerConnectivity = (event) => {
      if (event.detail) void run({ bootstrap: true });
    };
    const onFocus = () => void run();
    const onVisibility = () => {
      if (document.visibilityState === 'visible') void run();
    };
    window.addEventListener('online', onOnline);
    window.addEventListener('madarij-authenticated', onOnline);
    window.addEventListener(serverConnectivityChangeEvent, onServerConnectivity);
    window.addEventListener('focus', onFocus);
    document.addEventListener('visibilitychange', onVisibility);
    const onServiceWorkerMessage = (event) => {
      if (['MADARIJ_SYNC_OFFLINE_RECITATION', 'MADARIJ_SYNC_OFFLINE_OPERATIONS'].includes(event.data?.type)) {
        void run();
      }
    };
    navigator.serviceWorker?.addEventListener('message', onServiceWorkerMessage);
    void consumeNativeWakeup().then(() => run({ bootstrap: true }));
    const foregroundSyncInterval = window.setInterval(() => void run(), 60_000);

    let networkHandle;
    let appHandle;
    void Network.addListener('networkStatusChange', ({ connected }) => {
      if (connected) void run({ bootstrap: true });
    }).then((handle) => { networkHandle = handle; });
    void CapacitorApp.addListener('appStateChange', ({ isActive }) => {
      if (isActive) void consumeNativeWakeup().then(() => run());
    }).then((handle) => { appHandle = handle; });

    return () => {
      active = false;
      window.removeEventListener('online', onOnline);
      window.removeEventListener('madarij-authenticated', onOnline);
      window.removeEventListener(serverConnectivityChangeEvent, onServerConnectivity);
      window.removeEventListener('focus', onFocus);
      document.removeEventListener('visibilitychange', onVisibility);
      navigator.serviceWorker?.removeEventListener('message', onServiceWorkerMessage);
      window.clearInterval(foregroundSyncInterval);
      void networkHandle?.remove();
      void appHandle?.remove();
    };
  }, []);

  return null;
};

export default OfflineRecitationSyncBridge;

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import LoadingIndicator from '@/components/ui/loading-indicator';
import { Bell } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { studentsApi } from '@/services/studentsApi';
import { enableDeviceNotifications, isNativeNotificationsAvailable, listenForDeviceNotifications } from '@/services/nativeNotifications';

const NotificationButton = ({ showTrigger = true, presentation = 'dialog', open: controlledOpen, onOpenChange, onUnreadCountChange }) => {
  const [localOpen, setLocalOpen] = useState(false);
  const open = controlledOpen ?? localOpen;
  const setOpen = useCallback((value) => { setLocalOpen(value); onOpenChange?.(value); }, [onOpenChange]);
  const [notifications, setNotifications] = useState([]);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);
  const readAttempts = useRef(new Set());

  const load = useCallback(async () => {
    const rows = await studentsApi.getNotifications();
    setNotifications(Array.isArray(rows) ? rows : []);
    setError('');
    setLoading(false);
  }, []);

  useEffect(() => {
    const refresh = () => void load().catch(() => { setError('تعذر تحميل الإشعارات.'); setLoading(false); });
    refresh();
    const interval = window.setInterval(refresh, 45_000);
    let disposed = false;
    let cleanup;
    void listenForDeviceNotifications({ onNotification: refresh, onOpen: () => { setOpen(true); refresh(); }, onError: setError })
      .then((remove) => { if (disposed) remove(); else cleanup = remove; })
      .catch(() => setError('تعذر تهيئة إشعارات الجهاز.'));
    window.addEventListener('focus', refresh);
    return () => { disposed = true; cleanup?.(); window.clearInterval(interval); window.removeEventListener('focus', refresh); };
  }, [load, setOpen]);

  const unreadCount = useMemo(() => notifications.filter((item) => !item.isRead).length, [notifications]);
  useEffect(() => { onUnreadCountChange?.(unreadCount); }, [unreadCount, onUnreadCountChange]);
  useEffect(() => {
    if (!open) { readAttempts.current.clear(); return; }
    const ids = notifications.filter((item) => !item.isRead && !readAttempts.current.has(item.id)).map((item) => item.id);
    if (!ids.length) return;
    ids.forEach((id) => readAttempts.current.add(id));
    setNotifications((current) => current.map((item) => ids.includes(item.id) ? { ...item, isRead: true } : item));
    void studentsApi.markNotificationsRead(ids).catch(() => {
      setNotifications((current) => current.map((item) => ids.includes(item.id) ? { ...item, isRead: false } : item));
      setError('تعذر تحديث حالة القراءة.');
    });
  }, [open, notifications]);
  const markRead = async (notification) => {
    if (notification.isRead) return;
    setNotifications((current) => current.map((item) => item.id === notification.id ? { ...item, isRead: true } : item));
    await studentsApi.markNotificationRead(notification.id).catch(() => {
      setNotifications((current) => current.map((item) => item.id === notification.id ? { ...item, isRead: false } : item));
      setError('تعذر تحديث حالة القراءة.');
    });
  };

  const trigger = (<Button type="button" variant="outline" size="icon" onClick={presentation === 'popover' ? undefined : () => setOpen(true)} className="relative h-11 w-11 touch-manipulation [font-family:var(--font-ui)]" aria-label={`الإشعارات${unreadCount && !open ? `، ${unreadCount} غير مقروء` : ''}`}>
        <Bell className="h-5 w-5" />
        {unreadCount > 0 && !open && <span className="absolute -left-1 -top-1 flex h-5 min-w-5 items-center justify-center rounded-full bg-destructive px-1 text-[10px] font-black text-white">{Math.min(99, unreadCount)}</span>}
      </Button>);
  const _resolveContent = () => {
    if (loading) {
      return <LoadingIndicator className="py-3" />;
    }
    if (notifications.length) {
      return notifications.map((notification) => (
              <button key={notification.id} type="button" onClick={() => markRead(notification)} className={`w-full rounded-xl border p-3 text-right transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary ${notification.isRead ? 'border-primary/10 bg-background/60' : 'border-primary/35 bg-primary/10'}`}>
                <div className="break-words font-black text-foreground">{notification.title}</div>
                <p className="mt-1 whitespace-pre-wrap break-words text-sm font-bold leading-6 text-muted-foreground">{notification.body}</p>
                <div className="mt-2 text-xs font-bold text-muted-foreground">{notification.createdAt}</div>
              </button>
            ));
    }
    return <div className="py-3 text-right text-xs font-bold text-muted-foreground">لا توجد إشعارات.</div>;
  };
  const content = <>          {isNativeNotificationsAvailable() && <Button variant="outline" className="min-h-11" onClick={() => void enableDeviceNotifications().catch((e) => setError(e.message))}>تفعيل إشعارات الجهاز</Button>}
          {error && <p role="alert" className="text-sm text-destructive">{error}</p>}
          <div className="min-h-0 flex-1 space-y-2 overflow-y-auto overscroll-contain">
            {_resolveContent()}
          </div>
</>;
  if (presentation === 'popover') return <Popover open={open} onOpenChange={setOpen}>
    <PopoverTrigger asChild>{trigger}</PopoverTrigger>
    <PopoverContent align="end" sideOffset={10} dir="rtl" aria-label="الإشعارات" className="student-home-notifications flex max-h-[min(70dvh,520px)] w-[min(180px,calc(100vw-32px))] flex-col gap-3 rounded-2xl bg-card p-2 text-foreground [font-family:var(--font-ui)]">
      {content}
    </PopoverContent>
  </Popover>;
  return <>{showTrigger && trigger}<Dialog open={open} onOpenChange={setOpen}>
    <DialogContent className="flex max-h-[88dvh] max-w-lg flex-col bg-card p-4 [font-family:var(--font-ui)] sm:p-5" dir="rtl">
      <DialogHeader><DialogTitle>الإشعارات</DialogTitle></DialogHeader>{content}
    </DialogContent>
  </Dialog></>;
};

export default NotificationButton;

import React, { useEffect, useState } from 'react';
import { ChevronDown, Save, SlidersHorizontal } from 'lucide-react';
import { platformSettingsGroups } from '../../../shared/platform-settings-catalog.js';
import OwnerErrorState from '@/components/owner/OwnerErrorState';
import OwnerPolicySetting from '@/components/owner/OwnerPolicySetting';
import DashboardLoader from '@/components/dashboard/DashboardLoader';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useToast } from '@/components/ui/use-toast';
import { platformApi } from '@/services/platformApi';
import useRewardUnits from '@/hooks/useRewardUnits';

const OwnerSettingsSection = ({ complexes }) => {
  const { toast } = useToast();
  const activeComplexes = complexes.filter((complex) => complex.status === 'active');
  const [complexId, setComplexId] = useState(() => String(activeComplexes[0]?.id || ''));
  const [settings, setSettings] = useState(null);
  const [policies, setPolicies] = useState(null);
  const [error, setError] = useState('');
  const [busy, setBusy] = useState('');
  const rewardUnits = useRewardUnits(settings?.summitEnabled);

  const load = async () => {
    if (!complexId) return;
    setError('');
    setSettings(null);
    setPolicies(null);
    try {
      const sourceComplexId = complexId === 'all' ? activeComplexes[0]?.id : complexId;
      const result = await platformApi.getSettings(sourceComplexId);
      setSettings(result.settings);
      setPolicies(result.policies);
    } catch (requestError) {
      setError(requestError.message || 'تعذر تحميل الإعدادات.');
    }
  };

  useEffect(() => { load(); }, [complexId]);

  const updatePolicy = (definition, policy) => {
    setPolicies((current) => ({ ...current, [definition.key]: policy }));
    if (definition.type === 'boolean' && policy !== 'tenant') {
      setSettings((current) => ({ ...current, [definition.key]: policy === 'enabled' }));
    }
  };

  const save = async () => {
    const all = complexId === 'all';
    setBusy('save');
    try {
      const result = await platformApi.updateSettings({
        complexIds: all ? [] : [Number(complexId)],
        settings,
        policies,
      });
      setSettings(result.settings);
      setPolicies(result.policies);
      toast({ title: all ? 'حُفظت الإعدادات لجميع المجمعات' : 'حُفظت إعدادات المجمع' });
    } catch (requestError) {
      toast({ title: 'تعذر حفظ الإعدادات', description: requestError.message, variant: 'destructive' });
    } finally {
      setBusy('');
    }
  };

  if (!activeComplexes.length) return <OwnerErrorState message="لا توجد مجمعات مفعّلة." />;

  const _resolveOwnerSettingsSection = () => {
    if (error) {
      return <OwnerErrorState message={error} onRetry={load} />;
    }
    if (!settings || !policies) {
      return <DashboardLoader className="min-h-80" />;
    }
    return <>
          <Card className="border-border/70 bg-card shadow-sm">
            <CardContent className="space-y-2 p-3 sm:p-4">
              {platformSettingsGroups.map((group, groupIndex) => (
                <details key={group.key} className="group rounded-xl border border-border/70 bg-card" open={groupIndex === 0}>
                  <summary className="flex min-h-12 cursor-pointer list-none items-center gap-2 px-4 py-3 font-black outline-none focus-visible:ring-2 focus-visible:ring-ring">
                    <SlidersHorizontal className="h-4 w-4 text-primary" aria-hidden="true" />
                    <span className="min-w-0 flex-1">{rewardUnits.text(group.label)}</span>
                    <ChevronDown className="h-4 w-4 text-muted-foreground transition group-open:rotate-180" aria-hidden="true" />
                  </summary>
                  <div className="grid gap-3 border-t border-border/70 p-3 xl:grid-cols-2">
                    {group.settings.map((definition) => (
                      <OwnerPolicySetting
                        key={definition.key}
                        definition={{ ...definition, label: rewardUnits.text(definition.label) }}
                        value={settings[definition.key]}
                        policy={policies[definition.key] || 'tenant'}
                        onValueChange={(value) => setSettings((current) => ({ ...current, [definition.key]: value }))}
                        onPolicyChange={(policy) => updatePolicy(definition, policy)}
                      />
                    ))}
                  </div>
                </details>
              ))}
            </CardContent>
          </Card>

          <Button type="button" className="h-11 w-full gap-2 sm:w-auto sm:min-w-56" loading={busy === 'save'} disabled={Boolean(busy)} onClick={save}>
            <Save className="h-4 w-4" />{complexId === 'all' ? 'حفظ لجميع المجمعات' : 'حفظ لهذا المجمع'}
          </Button>
        </>;
  };
  return (
    <section className="space-y-4 [font-family:var(--font-ui)]">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
        <h2 className="text-xl font-black text-foreground sm:text-2xl">إعدادات المنصة</h2>
        <div className="w-full sm:w-72">
          <Label className="mb-1 block text-xs font-black">المجمع</Label>
          <Select value={complexId} onValueChange={setComplexId}>
            <SelectTrigger className="h-11 bg-card" aria-label="اختيار المجمع"><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="all">جميع المجمعات</SelectItem>
              {activeComplexes.map((complex) => <SelectItem key={complex.id} value={String(complex.id)}>{complex.name}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>
      </div>

      {_resolveOwnerSettingsSection()}
    </section>
  );
};

export default OwnerSettingsSection;

