import { useCallback, useEffect, useState } from 'react';

const views = new Set(['sessions', 'mushaf', 'store', 'programs', 'calls', 'journey', 'challenge']);
const readView = () => {
  const value = window.location.hash.replace('#student/', '');
  return window.location.hash.startsWith('#student/') && views.has(value) ? value : null;
};

export default function useStudentHomeNavigation() {
  const [view, setView] = useState(readView);
  const open = useCallback((next) => {
    if (next === readView()) return;
    const depth = Number(window.history.state?.studentHomeDepth || 0);
    window.history.pushState({ ...window.history.state, studentHomeDepth: depth + 1 }, '', `${window.location.pathname}${window.location.search}${next ? `#student/${next}` : ''}`);
    setView(next);
  }, []);
  const back = useCallback(() => {
    if (readView() === 'programs') {
      const url = new URL(window.location.href);
      if (url.searchParams.has('section')) url.searchParams.delete('section');
      else if (url.searchParams.has('program')) url.searchParams.delete('program');
      else url.hash = '';
      window.history.replaceState(window.history.state, '', `${url.pathname}${url.search}${url.hash}`);
      window.dispatchEvent(new PopStateEvent('popstate', { state: window.history.state }));
    } else if (window.history.state?.studentHomeDepth > 0) window.history.back();
    else {
      window.history.replaceState(window.history.state, '', `${window.location.pathname}${window.location.search}`);
      setView(null);
    }
  }, []);
  useEffect(() => {
    const sync = () => setView(readView());
    const nativeBack = (event) => { if (readView()) { event.preventDefault(); back(); } };
    window.addEventListener('popstate', sync);
    window.addEventListener('hashchange', sync);
    window.addEventListener('madarij-student-back', nativeBack);
    return () => {
      window.removeEventListener('popstate', sync);
      window.removeEventListener('hashchange', sync);
      window.removeEventListener('madarij-student-back', nativeBack);
    };
  }, [back]);
  return { view, open, back };
}

import { hasAcceptedRecitationTask } from './recitationTaskResults.js';
import { mergeRecitationDeliveryReceipts } from './recitationDeliveryReceipts.js';
import { advanceRecitationTaskQueue, canAdvanceRecitationSession } from './recitationTaskQueue.js';

const UNSYNCED_RECITATION_STATUSES = new Set(['pending', 'syncing', 'invalid_sequence', 'failed']);
const LOCAL_ATTENDANCE_STATUSES = new Set(['pending', 'syncing', 'failed']);

// A device acknowledgement is useful only for the exact task that the server accepted.
const protectsAcceptedTask = (session, item, task) => hasAcceptedRecitationTask(session, item)
  && Number(session.studentId) === Number(task.studentId)
  && Number(item.planId) === Number(task.planId)
  && item.taskType === task.taskType
  && (!task.planVersion || Number(item.planVersion) === Number(task.planVersion))
  && !task.evaluatedAt && !(Number(task.attemptCount) > 0)
  && (task.nazemManaged || item.result.teacherCompleted === true);

export function mergeCommittedOfflineEvaluation(evaluation, sessions = [], actions = []) {
  if (!evaluation) return evaluation;
  const evaluationDate = String(evaluation.date || '');
  const pendingSessions = sessions.filter((session) => (
    (UNSYNCED_RECITATION_STATUSES.has(session.status) || session.status === 'synced'
      || session.tasks?.some((item) => hasAcceptedRecitationTask(session, item)))
    && String(session.sessionDate || '') === evaluationDate
  ));
  let mergedEvaluation = evaluation;
  const pendingStudentIds = new Set();
  pendingSessions.forEach((session) => {
    const taskById = new Map(
      [...(mergedEvaluation.taskQueue || []), ...(mergedEvaluation.tasks || [])]
        .map((task) => [Number(task.id), task]),
    );
    const sessionTasks = (session.tasks || [])
      .map((item) => {
        const task = taskById.get(Number(item.taskId));
        if (!task) return null;
        // A transport failure protects only a complete durable submission, not
        // an unsubmitted placeholder in a partially accepted batch.
        if (session.status === 'failed' && !item.synced
          && (!item.payload || Number(item.planId) !== Number(task.planId)
            || Number(session.studentId) !== Number(task.studentId)
            || item.taskType !== task.taskType
            || (task.planVersion && Number(item.planVersion) !== Number(task.planVersion)))) return null;
        if ((item.synced || !UNSYNCED_RECITATION_STATUSES.has(session.status))
          && !protectsAcceptedTask(session, item, task)) return null;
        return task;
      })
      .filter(Boolean);
    if (!sessionTasks.length) return;
    if (Number(session.studentId)) pendingStudentIds.add(Number(session.studentId));
    sessionTasks.forEach((task) => pendingStudentIds.add(Number(task.studentId)));
    mergedEvaluation = advanceRecitationTaskQueue(mergedEvaluation, sessionTasks, { promote: canAdvanceRecitationSession(session) });
  });
  const latestAttendanceByStudent = new Map();
  actions.forEach((action) => {
    const newerReceipt = action.status === 'synced' && Number(action.result?.serverRecordedAt) > Number(evaluation.attendanceSnapshotAt || 0);
    if ((!LOCAL_ATTENDANCE_STATUSES.has(action.status) && !newerReceipt)
      || action.actionType !== 'student_attendance'
      || String(action.payload?.date || '') !== evaluationDate) return;
    latestAttendanceByStudent.set(Number(action.payload?.studentId), action.payload?.status || '');
  });
  const absentStudentIds = new Set((mergedEvaluation.students || []).filter((student) => (
    ['absent', 'excused'].includes(latestAttendanceByStudent.get(Number(student.studentId)) || student.attendanceStatus)
  )).map((student) => Number(student.studentId)));
  const remainingTasks = (mergedEvaluation.tasks || []).filter((task) => !absentStudentIds.has(Number(task.studentId)));
  return {
    ...mergedEvaluation,
    deliveryReceipts: mergeRecitationDeliveryReceipts(evaluation, sessions),
    tasks: remainingTasks,
    taskQueue: (mergedEvaluation.taskQueue || []).filter((task) => !absentStudentIds.has(Number(task.studentId))),
    students: (mergedEvaluation.students || [])
      .map((student) => ({
        ...student,
        ...(latestAttendanceByStudent.has(Number(student.studentId))
          ? { attendanceStatus: latestAttendanceByStudent.get(Number(student.studentId)) }
          : {}),
        ...(pendingStudentIds.has(Number(student.studentId))
          ? {
              recitationFinished: false,
              recitationPending: !remainingTasks.some((task) => (
                Number(task.studentId) === Number(student.studentId)
              )),
            }
          : {}),
      }))
      // Missing tasks may mean Nazem has not supplied the amount yet, not completion.
      // The task list decides visibility using actual completion and remaining work.
      .filter((student) => !['absent', 'excused'].includes(student.attendanceStatus)),
  };
}

export function isRecitationActionPending(task) {
  if (task.locallySaved || [true, 1].includes(task.teacherCompleted)) return false;
  if (task.nazemManaged) {
    return !task.nazemSubmissionLocked && !(Number(task.attemptCount) > 0);
  }
  return ![true, 1].includes(task.teacherCompleted);
}

export function shouldShowRecitationStudent(student, tasks = [], taskQueue = []) {
  if (!['present', 'late'].includes(student.attendanceStatus)) return true;
  const remaining = tasks.some((task) => (
    Number(task.studentId) === Number(student.studentId) && isRecitationActionPending(task)
  ));
  if (remaining) return true;
  const saved = student.recitationFinished || student.recitationPending || student.recitationSyncFailed
    || [...tasks, ...taskQueue].some((task) => Number(task.studentId) === Number(student.studentId)
      && !isRecitationActionPending(task));
  return !saved;
}

import { hasAcceptedRecitationTask } from './recitationTaskResults.js';

export const recitationDeliveryLabels = {
  local_saved: 'محفوظ على الجهاز — بانتظار اعتماد السيرفر',
  local_failed: 'تعذر اعتماد السيرفر — النتيجة محفوظة على الجهاز',
  local_rejected: 'لم يعتمد السيرفر النتيجة',
  server_saved: 'معتمد في المنصة',
  nazem_pending: 'معتمد في المنصة — بانتظار تأكيد ناظم',
  nazem_failed: 'معتمد في المنصة — تعذر تأكيد ناظم',
  nazem_confirmed: 'تأكد التسجيل في ناظم',
  nazem_adopted: 'اعتُمدت نتيجة ناظم الموجودة مسبقًا',
};

export function mergeRecitationDeliveryReceipts(evaluation, sessions = []) {
  const receipts = new Map((evaluation.deliveryReceipts || []).map(row => [Number(row.taskId), row]));
  const tasks = new Map([...(evaluation.taskQueue || []), ...(evaluation.tasks || [])].map(task => [Number(task.id), task]));
  const students = new Map((evaluation.students || []).map(student => [Number(student.studentId), student]));
  const orderedSessions = [...sessions].sort((a, b) => (
    String(b.committedAtLocal || b.createdAtLocal || '').localeCompare(String(a.committedAtLocal || a.createdAtLocal || ''))
    || String(b.sessionId || '').localeCompare(String(a.sessionId || ''))
    || (b.tasks || []).filter((item) => hasAcceptedRecitationTask(b, item)).length
      - (a.tasks || []).filter((item) => hasAcceptedRecitationTask(a, item)).length
  ));
  for (const session of orderedSessions) {
    if (session.sessionDate !== evaluation.date) continue;
    for (const item of session.tasks || []) {
      if (receipts.has(Number(item.taskId))) continue;
      const task = tasks.get(Number(item.taskId));
      if (task && (Number(session.studentId) !== Number(task.studentId)
        || (item.planId && task.planId && Number(item.planId) !== Number(task.planId))
        || (item.planVersion && task.planVersion && Number(item.planVersion) !== Number(task.planVersion)))) continue;
      const accepted = hasAcceptedRecitationTask(session, item);
      const student = students.get(Number(session.studentId));
      const _resolveStatus = () => {
        if (accepted) {
          if (item.nazemManaged || task?.nazemManaged || student?.nazemManaged) {
            return 'nazem_pending';
          }
          return 'server_saved';
        }
        if (session.status === 'failed') {
          return 'local_failed';
        }
        if (['conflict', 'invalid_sequence', 'rejected_permission', 'rejected_duplicate'].includes(session.status)) {
          return 'local_rejected';
        }
        return 'local_saved';
      };
      receipts.set(Number(item.taskId), {
        taskId: item.taskId, studentId: session.studentId, studentName: student?.studentName || 'الطالب',
        taskType: item.taskType || task?.taskType, taskDate: item.taskDate || task?.taskDate || session.sessionDate,
        track: item.track || task?.track,
        status: _resolveStatus(),
        error: accepted ? '' : session.lastError || '',
      });
    }
  }
  return [...receipts.values()];
}

import { hideStudentTaskAmount, isStudentAmountHidden } from '../../shared/student-amount-visibility.js';
import { getBusinessDate, shiftDateOnly } from '../../shared/business-date.js';
import { formatQuranRangeText } from './quranRangeText.js';
import { compactQuranAmount } from '../../shared/quran-display-text.js';

export const PLAN_TASK_TYPES = ['memorization', 'link', 'review'];
export const PLAN_TASK_LABELS = { memorization: 'الحفظ', link: 'الربط', review: 'المراجعة' };
const validDate = (value) => /^\d{4}-\d{2}-\d{2}$/.test(value || '') && getBusinessDate(`${value}T12:00:00Z`) === value;

export const planWeekStart = (date) => shiftDateOnly(date, -new Date(`${date}T12:00:00Z`).getUTCDay());
export const planDayName = (date) => new Intl.DateTimeFormat('ar-SA', { weekday: 'long', timeZone: 'Asia/Riyadh' }).format(new Date(`${date}T12:00:00Z`));
export const planTaskCompleted = (task) => task.teacherCompleted === true || task.teacherCompleted === 1;
export const planTaskAmount = (task) => task.amountHidden ? '' : task.ayahPreview || task.preview || formatQuranRangeText({
  startSurah: task.fromSurah, startSurahName: task.fromSurahName, startAyah: task.fromAyah,
  endSurah: task.toSurah, endSurahName: task.toSurahName, endAyah: task.toAyah,
  startPage: task.fromPage, endPage: task.toPage,
});

export const planCompactAmount = (task) => compactQuranAmount(planTaskAmount(task));

export const planProgressPercent = (plan) => {
  const value = Number(plan?.progressPercent ?? plan?.progress?.progressPercent ?? 0);
  return Number.isFinite(value) ? Math.max(0, Math.min(100, value)) : 0;
};

export const buildStudentPlanWeeks = ({ rows = [], todayData = null, points = null, today = getBusinessDate() } = {}) => {
  const tasks = new Map();
  // Today assignments are authoritative only for the date returned by the server.
  for (const task of rows) {
    const date = task.taskDate || task.sessionDate;
    if (validDate(date) && date <= today && PLAN_TASK_TYPES.includes(task.taskType)) tasks.set(`${date}:${task.id}`, { ...task, taskDate: date });
  }
  if (validDate(todayData?.date) && todayData.date <= today) {
    for (const task of todayData.todayAmounts || todayData.tasks || []) {
      if (!PLAN_TASK_TYPES.includes(task.taskType)) continue;
      const key = `${todayData.date}:${task.id}`;
      const existing = tasks.get(key);
      tasks.set(key, { ...task, ...existing, taskDate: todayData.date,
        repeatCount: existing?.repeatCount ?? task.repeatCount ?? todayData.repeatCount,
        listeningCount: existing?.listeningCount ?? task.listeningCount ?? todayData.listeningCount,
      });
    }
  }
  const days = new Map([[today, { date: today, tasks: [] }]]);
  const preview = todayData?.nextDay;
  if (todayData?.date === today && preview?.date === shiftDateOnly(today, 1)) {
    const previewTasks = (preview.tasks || []).filter((task) => PLAN_TASK_TYPES.includes(task.taskType));
    if (previewTasks.length) days.set(preview.date, { date: preview.date, tasks: previewTasks, preview: true });
  }
  for (const task of tasks.values()) {
    if (!days.has(task.taskDate)) days.set(task.taskDate, { date: task.taskDate, tasks: [] });
    days.get(task.taskDate).tasks.push(isStudentAmountHidden(todayData, task.taskType) ? hideStudentTaskAmount(task) : task);
  }
  for (const summary of points?.days || []) {
    if (!validDate(summary.date) || summary.date > today) continue;
    if (!days.has(summary.date)) days.set(summary.date, { date: summary.date, tasks: [] });
    days.get(summary.date).points = summary;
  }
  const weeks = new Map();
  for (const day of [...days.values()].sort((a, b) => b.date.localeCompare(a.date))) {
    day.tasks.sort((a, b) => Number(a.id) - Number(b.id));
    const start = planWeekStart(day.date);
    if (!weeks.has(start)) weeks.set(start, { start, end: shiftDateOnly(start, 6), days: [] });
    weeks.get(start).days.push(day);
  }
  return [...weeks.values()].sort((a, b) => b.start.localeCompare(a.start));
};

export const buildPlanMushafTarget = (tasks, label) => {
  const ranges = tasks.filter((task) => !task.amountHidden && Number(task.fromPage) >= 1 && Number(task.fromPage) <= 604).map((task) => ({
    page: Number(task.fromPage), preview: planTaskAmount(task),
    range: Number(task.fromSurah) > 0 && Number(task.toSurah) > 0 && Number(task.fromAyah) > 0 && Number(task.toAyah) > 0 ? {
      fromSurah: Number(task.fromSurah), fromAyah: Number(task.fromAyah),
      toSurah: Number(task.toSurah), toAyah: Number(task.toAyah),
      direction: Number(task.fromSurah) > Number(task.toSurah) || (Number(task.fromSurah) === Number(task.toSurah) && Number(task.fromAyah) > Number(task.toAyah)) ? -1 : 1,
    } : null,
  }));
  return ranges.length ? { ...ranges[0], label, ranges } : null;
};

export const buildStudentSessionWeeks = (rows = []) => buildStudentPlanWeeks({
  rows: rows.map((row) => ({ ...row, taskDate: row.sessionDate })),
}).map((week) => ({ ...week, days: week.days.filter((day) => day.tasks.length > 0) })).filter((week) => week.days.length > 0);

