  { key: 'whatsappSend', label: 'الإرسال عبر الواتس', icon: Send },
  { key: 'contactMessages', label: 'التواصل', icon: MessageSquare },
  { key: 'registrationRequests', label: 'طلبات التسجيل', icon: UserPlus },
  { key: 'store', label: 'المتجر', icon: Store, managementOnly: true },
  { key: 'settings', label: 'الإعدادات', icon: Settings, children: settingsNavigationItems },
  { key: 'quranEvaluation', label: 'جلسات التسميع', icon: ClipboardCheck, supervisorOnly: true },
  {
    key: 'previousRecitationSessions',
    permissionKey: 'quranEvaluation',
    label: 'جلسات التسميع السابقة',
    icon: History,
    supervisorOnly: true,
  },
];

const supervisorSectionOrder = new Map([
  ['staffAttendance', 0],
  ['quranEvaluation', 1],
  ['previousRecitationSessions', 2],
  ['teacherPoints', 3],
  ['reports', 4],
  ['culturalCompetition', 5],
  ['calls', 6],
  ['studentPlans', Number.POSITIVE_INFINITY],
]);

const reciterSectionOrder = new Map([
  ['staffAttendance', 0],
  ['quranEvaluation', 1],
  ['mushaf', 3],
]);

const offlineDashboardSections = new Set([
  'staffAttendance',
  'mushaf',
  'reports',
  'students',
  'studentPlans',
  'families',
  'quranTests',
  'narrationDay',
  'quranEvaluation',
  'previousRecitationSessions',
]);

const WajehDashboard = () => {
  const site = useSiteConfig();
  const navigate = useNavigate();
  const { section: sectionSlug = '' } = useParams();
  const isOnline = useOnlineStatus();
  const [settings, setSettings] = useState(defaultSettings);
  const rewardUnits = useRewardUnits(site.features?.summit !== false && settings.summitEnabled);
  const [isDashboardLoading, setIsDashboardLoading] = useState(true);
  const [dashboardPermissions, setDashboardPermissions] = useState(readStoredDashboardPermissions);
  const [activeCallRoom, setActiveCallRoom] = useState(null);
  const role = localStorage.getItem('wajeh_role') || '';
  const supervisorId = Number(localStorage.getItem('wajeh_supervisor_id') || 0);
  const hasSession = hasAuthSession(role);
  const isManager = role === 'manager' && hasSession;
  const isSupervisor = role === 'supervisor' && hasSession;
  const isReciter = role === 'reciter' && hasSession;
  const isAdmin = role === 'admin' && hasSession;
  const hasDashboardAccess = isManager || isAdmin || isReciter || (isSupervisor && dashboardPermissions.length > 0);

  useEffect(() => {
    const routeKey = dashboardSectionRoutes.getKey(sectionSlug);
    const _resolvePreloadKey = () => {
      if (routeKey === 'executionFollowup') {
        return 'reports';
      }
      if (isSettingsNavigationKey(routeKey)) {
        return 'settings';
      }
      return routeKey;
    };
    const preloadKey = _resolvePreloadKey();
    dashboardSectionPreloaders[preloadKey]?.();
  }, [sectionSlug]);

  useEffect(() => {
    if (!isOnline) {
      setIsDashboardLoading(false);
      return;
    }
    if (isManager || isSupervisor || isAdmin || isReciter) {
      studentsApi.getDashboardBootstrap()
        .then((data) => {
          setSettings({ ...defaultSettings, ...(data.settings) });
          const permissions = data.permissions || [];
          storeDashboardPermissions(permissions);
          setDashboardPermissions(permissions);
        })
        .catch(() => {
          setSettings(defaultSettings);
          if (!isManager) {
            storeDashboardPermissions([]);
            setDashboardPermissions([]);
          }
        })
        .finally(() => setIsDashboardLoading(false));
    } else {
      setIsDashboardLoading(false);
    }
  }, [isAdmin, isManager, isOnline, isReciter, isSupervisor]);

  const staffAttendanceActive = settings.staffAttendanceSource === 'teacher' && (isSupervisor || isAdmin || isReciter);
  const staffAttendanceState = useStaffAttendance(staffAttendanceActive);
  const { alreadyPresentToday } = staffAttendanceState;

  const sections = useMemo(() => {
    const localizeSections = (items) => items.map((item) => ({
      ...item,
      label: rewardUnits.text(item.label),
      children: item.children?.map((child) => ({ ...child, label: rewardUnits.text(child.label) })),
    }));
    if (isReciter) return localizeSections(baseSections
      .filter((section) => (
        ['quranEvaluation', 'staffAttendance', 'mushaf'].includes(section.key)
        && (section.key !== 'staffAttendance' || (settings.staffAttendanceSource === 'teacher' && !alreadyPresentToday))
      ))
      .sort((first, second) => reciterSectionOrder.get(first.key) - reciterSectionOrder.get(second.key)));
    const filteredSections = baseSections.filter((section) => {
      const featureKey = sectionFeatureKeys[section.key];
      if (featureKey && settings[featureKey] === false) return false;
      if (section.managerOnly && !isManager) return false;
      if (section.managementOnly && isSupervisor) return false;
      if (section.key === 'store' && site.features?.store === false) return false;
      if (section.key === 'teacherPoints' && !settings.teacherManualPointsEnabled) return false;
      if (section.key === 'studentExecutionCorrections' && settings.hasStudentQuranExecution === false) return false;
      if (section.supervisorOnly && !isSupervisor) return false;
      if (isSupervisor && ['manualAttendance', 'students'].includes(section.key)) return false;
      if (isSupervisor && section.key === 'studentPlans') return true;
      if (isSupervisor && section.key === 'teacherPoints') return true;
      if (isSupervisor && section.key === 'culturalCompetition') return true;
      if (isSupervisor && section.key === 'calls') return true;
      if (isSupervisor && section.key === 'reports') return true;
      if (section.key === 'staffAttendance') {
        return settings.staffAttendanceSource === 'teacher' && !alreadyPresentToday && (
          isSupervisor
          || isReciter
          || (isAdmin && dashboardPermissions.includes('staffAttendance'))
        );
      }
      if (section.key === 'mushaf') return isSupervisor || isReciter;
      const permissionKeys = section.permissionKeys || [section.permissionKey || section.key];
      if (!isManager && !permissionKeys.some((key) => dashboardPermissions.includes(key))) return false;
      if (!isSupervisor && section.key === 'manualAttendance' && (!settings.attendanceManualEnabled || settings.recitationAttendanceSource === 'teacher')) return false;
      return true;
    });

    const availableSections = isOnline
      ? filteredSections
      : filteredSections.filter((section) => offlineDashboardSections.has(section.key));
    if (!isSupervisor) return localizeSections([...availableSections].sort((first, second) => (
      Number(second.key === 'staffAttendance') - Number(first.key === 'staffAttendance')
    )));
    return localizeSections([...availableSections].sort((first, second) => (
      (supervisorSectionOrder.get(first.key) ?? Number.MAX_SAFE_INTEGER)
      - (supervisorSectionOrder.get(second.key) ?? Number.MAX_SAFE_INTEGER)
    )));
  }, [alreadyPresentToday, dashboardPermissions, isAdmin, isManager, isOnline, isReciter, isSupervisor, rewardUnits, settings, site.features]);

  const routeSection = dashboardSectionRoutes.getKey(sectionSlug);
  const _resolveRequestedSection = () => {
    if (routeSection === 'executionFollowup') {
      return 'reports';
    }
    if (routeSection === 'settings') {
      return defaultSettingsNavigationKey;
    }
    return routeSection;
  };
  const requestedSection = _resolveRequestedSection();
  const isVisibleSection = sections.some((section) => (
    section.key === requestedSection
    || section.children?.some((child) => child.key === requestedSection)
  ));
  const visibleActiveSection = isVisibleSection
    ? requestedSection
    : defaultAccountSection(role, sections);

  useEffect(() => {
    if (isDashboardLoading || !hasDashboardAccess || !visibleActiveSection) return;
    const canonicalSlug = dashboardSectionRoutes.getSlug(visibleActiveSection);
    if (sectionSlug !== canonicalSlug) {
      navigate(`/dashboard/${canonicalSlug}`, { replace: true });
    }
  }, [hasDashboardAccess, isDashboardLoading, navigate, sectionSlug, visibleActiveSection]);

  const changeSection = useCallback((key) => {
    const slug = dashboardSectionRoutes.getSlug(key);
    if (slug) navigate(`/dashboard/${slug}`);
  }, [navigate]);

  const logout = useAccountLogout();

  const clearActiveCall = useCallback(() => setActiveCallRoom(null), []);
  const restoreActiveCall = useCallback(() => changeSection('calls'), [changeSection]);

  const renderSection = () => {
    if (visibleActiveSection === 'students') return <StudentsSection />;
    if (visibleActiveSection === 'registrationRequests') return <RegistrationRequestsSection />;
    if (visibleActiveSection === 'studentPlans') return <StudentPlansSection hideCommitteeFilter={isSupervisor && !isManager} />;
    if (visibleActiveSection === 'studentExecutionCorrections') return <StudentExecutionCorrectionsSection />;
    if (visibleActiveSection === 'teacherPoints') return <TeacherPointsAdjustmentSection />;
    if (visibleActiveSection === 'quranTests') return <QuranTestsSection />;
    if (visibleActiveSection === 'quranEvaluation') return <TeacherEvaluationSection />;
    if (visibleActiveSection === 'previousRecitationSessions') return <TeacherPreviousSessionsPanel />;
    if (visibleActiveSection === 'families') return <FamiliesSection />;
    if (visibleActiveSection === 'supervisors') return <SupervisorsSection />;
    if (visibleActiveSection === 'reciters') return <RecitersSection />;
    if (visibleActiveSection === 'administrators') return <AdministratorsSection />;
    if (visibleActiveSection === 'reports') return (
      <ReportsSection
        teacherScoped={isSupervisor}
        canViewStandardReports={isSupervisor || isManager || dashboardPermissions.includes('reports')}
        canViewExecutionFollowup={
          settings.hasStudentQuranExecution !== false
          && (isSupervisor || isManager || dashboardPermissions.includes('executionFollowup'))
        }
        canViewTeacherPoints={settings.teacherManualPointsEnabled}
      />
    );
    if (visibleActiveSection === 'programs') return <ProgramsSection />;
    if (visibleActiveSection === 'culturalCompetition') return <CulturalCompetitionSection canManageBank={isManager || isAdmin} />;
    if (visibleActiveSection === 'calls') return activeCallRoom ? null : <LazyCallsSection onJoinRoom={setActiveCallRoom} />;
    if (visibleActiveSection === 'narrationDay') return <NarrationDaySection />;
    if (visibleActiveSection === 'notifications') return <NotificationsSection />;
    if (visibleActiveSection === 'whatsappSend') return <WhatsAppSendSection />;
    if (visibleActiveSection === 'contactMessages') return <ContactMessagesSection />;
    if (visibleActiveSection === 'manualAttendance') return <ManualAttendanceSection teacherScoped={isSupervisor} />;
    if (visibleActiveSection === 'staffAttendance') return <StaffAttendanceSection attendanceState={staffAttendanceState} />;
    if (visibleActiveSection === 'mushaf') return <StudentMushafSection />;
    if (isSettingsNavigationKey(visibleActiveSection)) return (
      <SettingsSection
        activeCategory={visibleActiveSection}
        onSettingsChange={setSettings}
        canManageDeletionRequests={isManager}
        canResetPoints={isManager}
      />
    );
    if (visibleActiveSection === 'store') return <StoreSection />;
    return (
      <Card className="border-primary/30 bg-card">
        <CardContent className="p-8 text-muted-foreground">القسم غير متاح حالياً.</CardContent>
      </Card>
    );
  };

  if (isDashboardLoading) {
    return (
      <div className="min-h-screen bg-background text-foreground [font-family:var(--font-ui)]" dir="rtl">
        <CustomCursor />
        <LoadingScreen />
      </div>
    );
  }

  if (!hasDashboardAccess) {
    return (
      <div className="min-h-screen bg-background px-4 py-16 text-foreground [font-family:var(--font-ui)]" dir="rtl">
        <CustomCursor />
        <Helmet>
          <title>غير مصرح</title>
        </Helmet>
        <div className="mx-auto max-w-xl rounded-2xl border border-border bg-card p-8 text-center shadow-[0_12px_35px_hsl(210_40%_20%/0.08)]">
          <span className="mx-auto grid h-12 w-12 place-items-center rounded-xl bg-primary/10 text-primary">
            <ShieldCheck className="h-6 w-6" />
          </span>
          <h1 className="mt-4 text-2xl font-black text-foreground">غير مصرح بالدخول</h1>
          <p className="mt-2 text-sm font-semibold text-muted-foreground">هذا الحساب لا يملك صلاحية الوصول إلى لوحة التحكم.</p>
          <Button type="button" variant="outline" className="mt-5" onClick={logout}>
            <LogOut className="h-4 w-4" />
            العودة لتسجيل الدخول
          </Button>
        </div>
      </div>
    );
  }

  if (visibleActiveSection === 'mushaf') {
    const returnSection = sections.find((section) => section.key !== 'mushaf');
    return (
      <div className="fixed inset-0 z-[100] h-dvh overflow-hidden bg-background [font-family:var(--font-ui)]" dir="rtl">
        <Suspense fallback={<DashboardLoader mode="screen" className="h-dvh" />}>
          <StudentMushafSection onBack={() => returnSection && changeSection(returnSection.key)} />
        </Suspense>
      </div>
    );
  }

  return (
    <>
    <StaffAttendancePrompt active={staffAttendanceActive} attendanceState={staffAttendanceState} />
    <DashboardShell
      headerContent={visibleActiveSection === 'quranEvaluation' ? <><Suspense fallback={null}><RecitationSettingsButton staffId={supervisorId} /></Suspense><NotificationButton showTrigger={false} /></> : <NotificationButton />}
      title={site.name}
      logo={site.markLogo || site.squareLogo || site.logo}
      sections={sections}
      activeSection={visibleActiveSection}
      contentKey={isSettingsNavigationKey(visibleActiveSection) ? 'settings' : visibleActiveSection}
      onSectionChange={changeSection}
      onLogout={logout}
      persistentContent={activeCallRoom ? (
        <LazyAudioCallRoom
          roomInfo={activeCallRoom}
          isOwner={activeCallRoom.isOwner}
          minimized={visibleActiveSection !== 'calls'}
          onRestore={restoreActiveCall}
          onLeave={clearActiveCall}
          onClosed={clearActiveCall}
        />
      ) : null}
    >
      <Suspense fallback={<DashboardLoader className="min-h-[420px]" />}>
        {renderSection()}
      </Suspense>
    </DashboardShell>
    </>
  );
};

export default WajehDashboard;

import { request } from '@/services/studentsApi';

const statusRequestOptions = { timeoutMs: 30_000 };
const terminalImportRefreshStatuses = new Set(['synced', 'failed', 'blocked', 'requires_review', 'dismissed']);
const createAbortError = () => {
  const error = new Error('تم إلغاء جلب بيانات ناظم.');
  error.name = 'AbortError';
  return error;
};
const throwIfAborted = (signal) => {
  if (signal?.aborted) throw createAbortError();
};
const wait = (milliseconds, signal) => new Promise((resolve, reject) => {
  throwIfAborted(signal);
  const timer = window.setTimeout(() => {
    signal?.removeEventListener('abort', abort);
    resolve();
  }, milliseconds);
  const abort = () => {
    window.clearTimeout(timer);
    reject(createAbortError());
  };
  signal?.addEventListener('abort', abort, { once: true });
});

export const nazemIntegrationApi = {
  getReconciliation: (query) => request(`/nazem/reconciliation?${new URLSearchParams(query)}`, statusRequestOptions),
  getConfig: () => request('/nazem/config', statusRequestOptions),
  updateConfig: (enabled) => request('/nazem/config', {
    method: 'PUT',
    body: JSON.stringify({ enabled }),
  }),
  getAccounts: () => request('/nazem/accounts', statusRequestOptions),
  getAccountIssues: (teacherId) => request(`/nazem/accounts/${teacherId}/issues`),
  retryStudentDiscovery: (teacherId, studentExternalId) => request(
    `/nazem/accounts/${teacherId}/issues/${encodeURIComponent(studentExternalId)}/retry`,
    { method: 'POST' },
  ),
  linkAccount: (teacherId, credentials) => request(`/nazem/accounts/${teacherId}/link`, {
    method: 'POST',
    body: JSON.stringify(credentials),
  }),
  confirmAccountIdentity: (teacherId, identity) => request(`/nazem/accounts/${teacherId}/confirm-identity`, {
    method: 'POST',
    body: JSON.stringify(identity),
  }),
  unlinkAccount: (teacherId) => request(`/nazem/accounts/${teacherId}`, { method: 'DELETE' }),
  getStudentLinks: (teacherId) => request(`/nazem/accounts/${teacherId}/students`),
  getImportPreview: (teacherId, committeeId = '', options = {}) => request(
    `/nazem/accounts/${teacherId}/import-preview${committeeId ? `?committeeId=${encodeURIComponent(committeeId)}` : ''}`,
    options,
  ),
  refreshImportData: (teacherId, options = {}) => request(`/nazem/accounts/${teacherId}/refresh-import`, {
    ...options,
    method: 'POST',
  }),
  getImportRefreshStatus: (teacherId, jobId, options = {}) => request(
    `/nazem/accounts/${teacherId}/refresh-import/${encodeURIComponent(jobId)}`,
    options,
  ),
  prepareImportData: async (teacherId, {
    attempts = 300,
    intervalMs = 2_000,
    onProgress = () => {},
    signal,
  } = {}) => {
    throwIfAborted(signal);
    const started = await nazemIntegrationApi.refreshImportData(teacherId, { signal });
    onProgress(0);
    let latest = { status: started.status };
    for (let attempt = 0; attempt < attempts; attempt += 1) {
      throwIfAborted(signal);
      latest = await nazemIntegrationApi.getImportRefreshStatus(teacherId, started.jobId, { signal });
      onProgress(Number(latest.progressPercent || 0));
      if (terminalImportRefreshStatuses.has(latest.status)) break;
      await wait(intervalMs, signal);
    }
    if (latest.status !== 'synced' && terminalImportRefreshStatuses.has(latest.status)) {
      throw new Error(latest.lastError || 'تعذر جلب الطلاب والخطط كاملة من ناظم.');
    }
    if (latest.status !== 'synced') {
      throw new Error('استغرق جلب بيانات ناظم وقتًا أطول من المتوقع. حاول مرة أخرى.');
    }
    onProgress(100);
    const [initialPreview, conflicts] = await Promise.all([
      nazemIntegrationApi.getImportPreview(teacherId, '', { signal }),
      nazemIntegrationApi.getConflicts(teacherId, { signal }),
    ]);
    const recommendedCommitteeId = initialPreview.recommendedCommitteeId;
    const preview = recommendedCommitteeId
      ? await nazemIntegrationApi.getImportPreview(teacherId, recommendedCommitteeId, { signal })
      : initialPreview;
    const firstCircle = preview.candidates[0];
    return {
      preview,
      conflicts: conflicts.filter((row) => row.entityType === 'plan'),
      refreshResult: latest.result || null,
      mode: recommendedCommitteeId ? 'existing' : 'new',
      committeeId: recommendedCommitteeId ? String(recommendedCommitteeId) : '',
      newCommitteeName: firstCircle?.circleName || preview.suggestedNewCommitteeName || '',
    };
  },
  importStudentsAndPlans: (teacherId, payload) => request(`/nazem/accounts/${teacherId}/import`, {
    method: 'POST',
    body: JSON.stringify(payload),
  }),
  matchStudent: (teacherId, studentId, candidateId) => request(`/nazem/accounts/${teacherId}/students/${studentId}`, {
    method: 'PUT',
    body: JSON.stringify({ candidateId }),
  }),
  getDiscoveredPlans: (teacherId) => request(`/nazem/accounts/${teacherId}/plans`),
  importDiscoveredPlan: (teacherId, candidateId) => request(`/nazem/accounts/${teacherId}/plans/${candidateId}/import`, {
    method: 'POST',
  }),
  importDiscoveredPlansBulk: (teacherId, candidateIds) => request(`/nazem/accounts/${teacherId}/plans/import-bulk`, {
    method: 'POST',
    body: JSON.stringify({ candidateIds }),
  }),
  importReadyPlans: () => request('/nazem/plans/import-ready', { method: 'POST' }),
  ignoreDiscoveredPlan: (teacherId, candidateId) => request(`/nazem/accounts/${teacherId}/plans/${candidateId}/ignore`, {
    method: 'POST',
  }),
  getJobs: (status = '') => request(`/nazem/jobs${status ? `?status=${encodeURIComponent(status)}` : ''}`),
  getLog: () => request('/nazem/log'),
  retryJob: (jobId) => request(`/nazem/jobs/${jobId}/retry`, { method: 'POST' }),
  dismissJob: (jobId) => request(`/nazem/jobs/${jobId}/dismiss`, { method: 'POST' }),
  getConflicts: (teacherId = '', options = {}) => request(
    `/nazem/conflicts${teacherId ? `?teacherId=${encodeURIComponent(teacherId)}` : ''}`,
    options,
  ),
  resolveConflict: (conflictId, resolution) => request(`/nazem/conflicts/${conflictId}/resolve`, {
    method: 'POST',
    body: JSON.stringify({ resolution }),
  }),
  getPlanStatuses: (studentId = '') => request(`/nazem/plan-statuses${studentId ? `?studentId=${studentId}` : ''}`),
  getDailyStatuses: (date = '') => request(`/nazem/daily-statuses${date ? `?date=${encodeURIComponent(date)}` : ''}`),
};

import { singleFlight, limitedTaskQueue } from '@/lib/asyncRequests';
import { createRefreshGate } from '@/lib/refreshGate';
import { getAuthSessionVersion } from '@/lib/authSession';
import { studentsApi } from '@/services/studentsApi';
import { getTenantRegistrationNumber } from '@/services/apiBase';
import { offlineRecitationStore } from '@/services/offlineRecitationStore';
import { getBusinessDate, shiftDateOnly } from '../../shared/business-date.js';

const ACTION_HANDLERS = Object.freeze({
  student_attendance: (payload) => studentsApi.checkInStudent(payload.studentId, payload),
  staff_attendance: (payload) => studentsApi.checkInMyStaffAttendance(payload),
  quran_test_result: (payload) => studentsApi.saveQuranTestResult(payload),
  narration_part: (payload) => studentsApi.updateNarrationPart(payload.eventId, payload.partId, {
    ...payload.evaluation,
    requestId: payload.requestId,
    deviceId: payload.deviceId,
    bootId: payload.bootId,
    eventMonotonicMs: payload.eventMonotonicMs,
    committedAtLocal: payload.committedAtLocal,
  }),
  narration_student_status: (payload) => studentsApi.updateNarrationStudentStatus(
    payload.eventId,
    payload.entryId,
    payload.status,
    payload,
  ),
  daily_challenge_submit: (payload) => studentsApi.submitDailyChallenge(payload),
  store_purchase: (payload) => studentsApi.purchaseStoreProduct(payload.productId, payload),
});

const isOnline = () => typeof navigator === 'undefined' || navigator.onLine !== false;

const registerBackgroundSync = async () => {
  if (typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return;
  const registration = await navigator.serviceWorker.ready.catch(() => null);
  await registration?.sync?.register?.('madarij-offline-operations').catch(() => undefined);
};

export const offlineActorKey = (accountId, actorRole = 'supervisor') => (
  `${getTenantRegistrationNumber() || 'default'}:${String(actorRole || 'supervisor')}:${Number(accountId || 0)}`
);

const refreshManagementWorkspace = createRefreshGate(5 * 60_000);
const fetchSnapshot = singleFlight(async (key, session, loader) => {
  const value = await loader();
  await offlineRecitationStore.cacheSnapshot(key, value);
  return value;
}, (key, session) => JSON.stringify([key, session]));

export async function loadOfflineSnapshot(accountId, resourceKey, loader, {
  actorRole = 'supervisor',
  preferCache = false,
  onRefresh,
} = {}) {
  const key = `${offlineActorKey(accountId, actorRole)}:resource:${resourceKey}`;
  const cached = await offlineRecitationStore.getSnapshot(key);
  if (!isOnline()) {
    if (cached !== null && cached !== undefined) return cached;
    throw new Error('هذه البيانات غير محفوظة للعمل دون إنترنت. اتصل بالإنترنت مرة واحدة أولًا.');
  }
  if (preferCache && cached !== null && cached !== undefined) {
    void fetchSnapshot(key, getAuthSessionVersion(), loader).then((value) => {
      onRefresh?.(value);
    }).catch(() => undefined);
    return cached;
  }
  try {
    return await fetchSnapshot(key, getAuthSessionVersion(), loader);
  } catch (error) {
    if (cached !== null && cached !== undefined) return cached;
    throw error;
  }
}

export async function commitOfflineOperation(accountId, actionType, payload, { dedupeKey = '', actorRole = 'supervisor' } = {}) {
  if (!ACTION_HANDLERS[actionType]) throw new Error('نوع العملية المحلية غير مدعوم.');
  const device = await offlineRecitationStore.getDeviceContext(offlineActorKey(accountId, actorRole));
  const capturedAtLocal = new Date().toISOString();
  const action = await offlineRecitationStore.commitAction(
    offlineActorKey(accountId, actorRole),
    actionType,
    {
      ...payload,
      deviceId: device.deviceId,
      bootId: device.bootId,
      eventMonotonicMs: device.monotonicMs,
      capturedAtLocal,
      committedAtLocal: capturedAtLocal,
      registrationNumber: getTenantRegistrationNumber(),
    },
    { dedupeKey },
  );
  void registerBackgroundSync();
  return action;
}

export async function syncOfflineActions(accountId, { force = false, actorRole = 'supervisor' } = {}) {
  if (!accountId || !isOnline()) return [];
  const actorKey = offlineActorKey(accountId, actorRole);
  const actions = await offlineRecitationStore.getActions(actorKey, ['pending', 'failed', 'syncing']);
  const results = [];
  for (const action of actions) {
    if (!force && action.nextRetryAt && Date.parse(action.nextRetryAt) > Date.now()) continue;
    const handler = ACTION_HANDLERS[action.actionType];
    if (!handler) continue;
    await offlineRecitationStore.updateAction(actorKey, action.actionId, { status: 'syncing', lastError: '' });
    try {
      const result = await handler(action.payload);
      if (action.actionType === 'staff_attendance' && result?.date) {
        const key = `${actorKey}:resource:staff-attendance:me`;
        const cached = await offlineRecitationStore.getSnapshot(key);
        if (!cached?.date || result.date >= cached.date) {
          await offlineRecitationStore.cacheSnapshot(key, result);
        }
      }
      results.push(await offlineRecitationStore.updateAction(actorKey, action.actionId, {
        status: 'synced', result, nextRetryAt: null, lastError: '',
      }));
      await offlineRecitationStore.setMeta(`last_sync:${actorKey}`, new Date().toISOString());
    } catch (error) {
      const retryCount = Number(action.retryCount || 0) + 1;
      const terminal = Number(error?.status) >= 400
        && Number(error?.status) < 500
        && ![408, 429].includes(Number(error?.status));
      const _resolveStatus = () => {
        if (error?.status === 403) {
          return 'rejected_permission';
        }
        if (error?.status === 409) {
          return 'rejected_conflict';
        }
        if (terminal) {
          return 'rejected_validation';
        }
        return 'failed';
      };
      results.push(await offlineRecitationStore.updateAction(actorKey, action.actionId, {
        status: _resolveStatus(),
        retryCount,
        nextRetryAt: terminal ? null : new Date(Date.now() + Math.min(60 * 60_000, 5_000 * (3 ** retryCount))).toISOString(),
        lastError: error.message || 'تعذرت المزامنة.',
      }));
    }
  }
  return results;
}

export async function prefetchOfflineWorkspace(accountId) {
  if (!accountId || !isOnline()) return;
  const date = getBusinessDate();
  const cache = (key, loader) => loadOfflineSnapshot(accountId, key, loader);
  const reportTo = date;
  const reportFrom = shiftDateOnly(date, -369);
  const [, scheduleResult, eventsResult] = await Promise.allSettled([
    cache('quran-tests:settings', () => studentsApi.getSettings()),
    cache(`quran-tests:schedule:${date}`, () => studentsApi.getQuranTestSchedule({ date })),
    cache('narration:events', () => studentsApi.getNarrationEvents()),
    cache('staff-attendance:me', () => studentsApi.getMyStaffAttendance()),
    cache('quran-tests:students', () => studentsApi.getQuranTestStudents()),
    cache('narration:committees', () => studentsApi.getCommittees()),
    cache('plans:rows:all', () => studentsApi.getStudentPlans({ committeeId: 'all' })),
    cache('quran:chapters', () => studentsApi.getQuranChapters()),
    cache('quran:juz-ranges', () => studentsApi.getQuranJuzRanges()),
    cache('settings:public', () => studentsApi.getPublicSettings()),
    cache('reports:recitation-sessions', () => studentsApi.getRecitationSessionsReport({ from: reportFrom, to: reportTo })),
  ]);
  const schedule = scheduleResult.status === 'fulfilled' && Array.isArray(scheduleResult.value) ? scheduleResult.value : [];
  const events = eventsResult.status === 'fulfilled' && Array.isArray(eventsResult.value) ? eventsResult.value : [];
  const openEvent = events.find((item) => item.status === 'open');
  const event = openEvent
    ? await cache(`narration:event:${openEvent.id}`, () => studentsApi.getNarrationEvent(openEvent.id)).catch(() => null)
    : null;
  const detailJobs = [];
  for (const appointment of schedule) {
    detailJobs.push(cache(
      `quran-tests:ayahs:${appointment.studentId}:${appointment.juz}`,
      () => studentsApi.getQuranTestJuzAyahs(appointment.studentId, appointment.juz),
    ));
  }
  if (event) {
    for (const student of event.students || []) {
      for (const part of student.parts || []) {
        detailJobs.push(cache(
          `narration:ayahs:${event.id}:${part.id}`,
          () => studentsApi.getNarrationPartAyahs(event.id, part.id),
        ));
      }
    }
  }
  await Promise.allSettled(detailJobs);
}

export async function prefetchOfflineManagementWorkspace(accountId, actorRole = 'manager', { automatic = false } = {}) {
